        '\n'
        '\n'
        'def package_root() -> Path:\n'
        '    return Path(__file__).resolve().parents[1]\n'
        '\n'
        '\n'
        'def engine_path() -> Path:\n'
        '    return package_root() / "pv_ae" / "panel_day_engine.py"\n'
        '\n'
        '\n'
        'def fixed_fault6_table_path() -> Path:\n'
        '    return package_root() / "artifacts" / "fault6_fixed_result_table_v1.csv"\n'
        '\n'
        '\n'
        'def fixed_fault6_preview_path() -> Path:\n'
        '    return package_root() / "artifacts" / "fault6_label_and_algorithm_preview_v1.csv"\n'
        '\n'
        '\n'
        'def baseline_manifest_path() -> Path:\n'
        '    return package_root() / "artifacts" / "input_baseline_manifest_v1.json"\n'
        '\n'
        '\n'
        'def baseline_core_digest_path() -> Path:\n'
        '    return package_root() / "artifacts" / "panel_day_core_baseline_digest_v1.json"\n'
        '\n'
        '\n'
        'def fault6_provenance_path() -> Path:\n'
        '    return package_root() / "artifacts" / "fault6_fixed_result_provenance_v1.json"\n'
        '\n'
        '\n'
        'def dependency_audit_json_path() -> Path:\n'
        '    return package_root() / "artifacts" / "runtime_chain_dependency_audit_v1.json"\n'
        '\n'
        '\n'
        'def dependency_audit_md_path() -> Path:\n'
        '    return package_root() / "artifacts" / "runtime_chain_dependency_audit_v1.md"\n'
        '\n'
        '\n'
        'def packaged_share_root() -> Path:\n'
        '    return package_root() / "_share"\n'
        '\n'
        '\n'
        'def packaged_pipeline_root() -> Path:\n'
        '    return package_root() / "research" / "prognostics"\n'
        '\n'
        '\n'
        'def packaged_script_path(name: str) -> Path:\n'
        '    return packaged_pipeline_root() / name\n'
        '\n'
        '\n'
        'def extract_date_from_name(path: Path) -> pd.Timestamp:\n'
        '    match = DATE_RE.search(path.name)\n'
        '    if not match:\n'
        '        return pd.NaT\n'
        '    return pd.to_datetime(match.group(1), errors="coerce").normalize()\n'
        '\n'
        '\n'
        'def normalize_sites(raw_sites: str) -> list[str]:\n'
        '    sites = [token.strip() for token in str(raw_sites).split(",") if token.strip()]\n'
        '    if not sites:\n'
        '        raise SystemExit("at least one site must be provided")\n'
        '    return sites\n'
        '\n'
        '\n'
        'def scan_site_files(data_root: Path, site: str, pattern: str) -> tuple[pd.Timestamp, pd.Timestamp, list[Path]]:\n'
        '    raw_dir = data_root / site / "raw"\n'
        '    if not raw_dir.exists():\n'
        '        raise SystemExit(f"missing raw dir for site={site}: {raw_dir}")\n'
        '    files = sorted(path for path in raw_dir.glob(pattern) if path.is_file() and path.suffix.lower() == ".csv")\n'
        '    if not files:\n'
        '        raise SystemExit(f"raw csv not found for site={site}: {raw_dir}")\n'
        '    valid_dates = [value for value in (extract_date_from_name(path) for path in files) if pd.notna(value)]\n'
        '    if not valid_dates:\n'
        '        raise SystemExit(f"no YYYY-MM-DD found in filenames for site={site}: {raw_dir}")\n'
        '    return min(valid_dates), max(valid_dates), files\n'
        '\n'
        '\n'
        'def propose_windows(min_date: pd.Timestamp, max_date: pd.Timestamp, train_days: int) -> dict[str, str]:\n'
        '    span_days = int((max_date - min_date).days)\n'
        '    proposed = min(int(train_days) - 1, max(14, int(span_days * 0.30)))\n'
        '    if proposed < 1:\n'
        '        proposed = 1\n'
        '\n'
        '    train_start = min_date\n'
        '    train_end = min_date + pd.Timedelta(days=proposed)\n'
        '    if train_end >= max_date:\n'
        '        train_end = max_date - pd.Timedelta(days=1)\n'
        '    if train_end < min_date:\n'
        '        raise SystemExit("date span too short to propose train/eval windows")\n'
        '\n'
        '    eval_start = train_end + pd.Timedelta(days=1)\n'
        '    eval_end = max_date\n'
        '    if eval_start > eval_end:\n'
        '        raise SystemExit("date span too short to propose eval window")\n'
        '\n'
        '    return {\n'
        '        "train_start": str(train_start.date()),\n'
        '        "train_end": str(train_end.date()),\n'
        '        "eval_start": str(eval_start.date()),\n'
        '        "eval_end": str(eval_end.date()),\n'
        '        "input_date_min": str(min_date.date()),\n'
        '        "input_date_max": str(max_date.date()),\n'
        '    }\n'
        '\n'
        '\n'
        'def site_manifest(files: list[Path]) -> dict[str, object]:\n'
        '    date_tokens = [match.group(1) for path in files if (match := DATE_RE.search(path.name))]\n'
        '    return {\n'
        '        "file_count": int(len(files)),\n'
        '        "total_bytes": int(sum(path.stat().st_size for path in files)),\n'
        '        "first_filenames": [path.name for path in files[:5]],\n'
        '        "last_filenames": [path.name for path in files[-5:]],\n'
        '        "min_date": min(date_tokens) if date_tokens else "",\n'
        '        "max_date": max(date_tokens) if date_tokens else "",\n'
        '    }\n'
        '\n'
        '\n'
        'def build_site_plan(args: argparse.Namespace, site: str) -> tuple[dict[str, object], list[str]]:\n'
        '    data_root = args.data_root.expanduser().resolve()\n'
        '    output_root = args.output_root.expanduser().resolve()\n'
        '    site_output_dir = output_root / "sites" / site / "output"\n'
        '    site_log_dir = output_root / "sites" / site / "log"\n'
        '    site_output_dir.mkdir(parents=True, exist_ok=True)\n'
        '    site_log_dir.mkdir(parents=True, exist_ok=True)\n'
        '\n'
        '    min_date, max_date, files = scan_site_files(data_root, site, args.pattern)\n'
        '    windows = propose_windows(min_date, max_date, args.train_days)\n'
        '    cmd = [\n'
        '        sys.executable,\n'
        '        str(engine_path()),\n'
        '        "--site",\n'
        '        site,\n'
        '        "--data-root",\n'
        '        str(data_root),\n'
        '        "--out-dir",\n'
        '        str(site_output_dir),\n'
        '        "--log-dir",\n'
        '        str(site_log_dir),\n'
        '        "--pattern",\n'
        '        args.pattern,\n'
        '        "--train-start",\n'
        '        windows["train_start"],\n'
        '        "--train-end",\n'
        '        windows["train_end"],\n'
        '        "--eval-start",\n'
        '        windows["eval_start"],\n'
        '        "--eval-end",\n'
        '        windows["eval_end"],\n'
        '        "--epochs",\n'
        '        str(args.epochs),\n'
        '        "--latent",\n'
        '        str(args.latent),\n'
        '        "--device",\n'
        '        args.device,\n'
        '    ]\n'
        '    plan = {\n'
        '        "site": site,\n'
        '        "raw_dir": str(data_root / site / "raw"),\n'
        '        "output_dir": str(site_output_dir),\n'
        '        "log_dir": str(site_log_dir),\n'
        '        "windows": windows,\n'
        '        "file_manifest": site_manifest(files),\n'
        '        "command": cmd,\n'
        '    }\n'
        '    return plan, cmd\n'
        '\n'
        '\n'
        'def write_json(path: Path, payload: dict[str, object]) -> None:\n'
        '    path.parent.mkdir(parents=True, exist_ok=True)\n'
        '    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")\n'
        '\n'
        '\n'
        'def write_text(path: Path, text: str) -> None:\n'
        '    path.parent.mkdir(parents=True, exist_ok=True)\n'
        '    path.write_text(text, encoding="utf-8")\n'
        '\n'
        '\n'
        'def emit_progress(percent: int, message: str) -> None:\n'
        '    safe_percent = max(0, min(100, int(percent)))\n'
        '    print(f"[{safe_percent:03d}%] {message}", flush=True)\n'
        '\n'
        '\n'
        'def load_baseline_manifest() -> dict[str, object]:\n'
        '    path = baseline_manifest_path()\n'
        '    if not path.exists():\n'
        '        raise SystemExit(f"missing packaged baseline manifest: {path}")\n'
        '    return json.loads(path.read_text(encoding="utf-8"))\n'
        '\n'
        '\n'
        'def compare_to_baseline(site_plans: list[dict[str, object]]) -> dict[str, object]:\n'
        '    baseline = load_baseline_manifest()\n'
        '    comparison: dict[str, object] = {"all_sites_match": True, "sites": {}}\n'
        '    baseline_sites = baseline.get("sites", {})\n'
        '    for plan in site_plans:\n'
        '        site = str(plan["site"])\n'
        '        actual = plan["file_manifest"]\n'
        '        expected = baseline_sites.get(site, {})\n'
        '        site_match = True\n'
        '        diffs: list[str] = []\n'
        '        for key in ["file_count", "total_bytes", "min_date", "max_date"]:\n'
        '            if actual.get(key) != expected.get(key):\n'
        '                site_match = False\n'
        '                diffs.append(f"{key}: expected={expected.get(key)} actual={actual.get(key)}")\n'
        '        comparison["sites"][site] = {\n'
        '            "match": site_match,\n'
        '            "expected": expected,\n'
        '            "actual": actual,\n'
        '            "diffs": diffs,\n'
        '        }\n'
        '        if not site_match:\n'
        '            comparison["all_sites_match"] = False\n'
        '    comparison["note_ko"] = (\n'
        '        "all_sites_match=1 이면 packaged fixed result table을 만든 baseline raw corpus와 현재 입력의 경량 fingerprint가 일치한다. "\n'
        '        "일치하지 않으면 engine은 실행될 수 있어도 fixed result table exact replay 보장은 약해진다."\n'
        '    )\n'
        '    return comparison\n'
        '\n'
        '\n'
        'def copy_fixed_results(output_root: Path) -> dict[str, str]:\n'
        '    output_dir = output_root / "result"\n'
        '    output_dir.mkdir(parents=True, exist_ok=True)\n'
        '    fault6_dest = output_dir / "fault6_fixed_result_table_v1.csv"\n'
        '    preview_dest = output_dir / "fault6_label_and_algorithm_preview_v1.csv"\n'
        '    shutil.copy2(fixed_fault6_table_path(), fault6_dest)\n'
        '    if fixed_fault6_preview_path().exists():\n'
        '        preview_df = pd.read_csv(fixed_fault6_preview_path(), encoding="utf-8-sig", low_memory=False)\n'
        '        to_user_preview_schema(preview_df).to_csv(preview_dest, index=False, encoding="utf-8-sig")\n'
        '    return {\n'
        '        "fault6_fixed_result_table_v1": str(fault6_dest),\n'
        '        "fault6_label_and_algorithm_preview_v1": str(preview_dest),\n'
        '    }\n'
        '\n'
        '\n'
        'def copy_tree(source: Path, target: Path) -> None:\n'
        '    if not source.exists():\n'
        '        raise SystemExit(f"missing source tree: {source}")\n'
        '    target.parent.mkdir(parents=True, exist_ok=True)\n'
        '    shutil.copytree(source, target, dirs_exist_ok=True)\n'
        '\n'
        '\n'
        'def path_size_bytes(path: Path) -> int:\n'
        '    if not path.exists():\n'
        '        return 0\n'
        '    if path.is_file() or path.is_symlink():\n'
        '        return int(path.lstat().st_size)\n'
        '    total = 0\n'
        '    for child in path.rglob("*"):\n'
        '        try:\n'
        '            total += int(child.lstat().st_size)\n'
        '        except OSError:\n'
        '            continue\n'
        '    return total\n'
        '\n'
        '\n'
        'def remove_workspace_path(path: Path) -> dict[str, object]:\n'
        '    exists_before = path.exists() or path.is_symlink()\n'
        '    size_before = path_size_bytes(path)\n'
        '    if exists_before:\n'
        '        if path.is_dir() and not path.is_symlink():\n'
        '            shutil.rmtree(path)\n'
        '        else:\n'
        '            path.unlink()\n'
        '    return {\n'
        '        "path": str(path),\n'
        '        "exists_before": bool(exists_before),\n'
        '        "size_bytes_before": int(size_before),\n'
        '        "removed": bool(exists_before),\n'
        '    }\n'
        '\n'
        '\n'
        'def apply_workspace_retention(output_root: Path, retention: str) -> dict[str, object]:\n'
        '    report: dict[str, object] = {\n'
        '        "workspace_retention": retention,\n'
        '        "status": "full_workspace_retained",\n'
        '        "removed_paths": [],\n'
        '        "kept_paths": [\n'
        '            str(output_root / "result"),\n'
        '            str(output_root / "shadow_compare_v1.json"),\n'
        '            str(output_root / "run_metadata_v1.json"),\n'
        '        ],\n'
        '        "bytes_removed_estimate": 0,\n'
        '        "note_ko": (\n'
        '            "full 모드는 기존처럼 site output/workspace data를 모두 보존한다. "\n'
        '            "result-only 모드는 재생성 가능한 대용량 중복 data copy만 제거하고 result 및 _share 산출물은 보존한다."\n'
        '        ),\n'
        '    }\n'
        '    if retention == "full":\n'
        '        return report\n'
        '\n'
        '    removable_paths = [\n'
        '        output_root / "sites",\n'
        '        output_root / "live_chain_workspace" / "data",\n'
        '        output_root / "raw_only_chain_workspace" / "data",\n'
        '    ]\n'
        '    removed = [remove_workspace_path(path) for path in removable_paths]\n'
        '    report["removed_paths"] = removed\n'
        '    report["bytes_removed_estimate"] = int(sum(int(item["size_bytes_before"]) for item in removed))\n'
        '    report["status"] = "result_and_share_artifacts_retained"\n'
        '    for share_path in [\n'
        '        output_root / "live_chain_workspace" / "_share",\n'
        '        output_root / "raw_only_chain_workspace" / "_share",\n'
        '    ]:\n'
        '        if share_path.exists():\n'
        '            report["kept_paths"].append(str(share_path))\n'
        '    return report\n'
        '\n'
        '\n'
        'def copy_existing_site_outs(reuse_root: Path, output_root: Path, sites: list[str]) -> dict[str, str]:\n'
        '    copied: dict[str, str] = {}\n'
        '    for site in sites:\n'
        '        source = reuse_root / site / "out"\n'
        '        target = output_root / "sites" / site / "output"\n'
        '        if not source.exists():\n'
        '            raise SystemExit(f"missing precomputed out dir for site={site}: {source}")\n'
        '        if target.exists():\n'
        '            shutil.rmtree(target)\n'
        '        copy_tree(source, target)\n'
        '        copied[site] = str(target)\n'
        '    return copied\n'
        '\n'
        '\n'
        'def site_outs_available(root: Path, sites: list[str]) -> bool:\n'
        '    for site in sites:\n'
        '        if not (root / site / "out" / "panel_day_core.csv").exists():\n'
        '            return False\n'
        '    return True\n'
        '\n'
        '\n'
        'def raw_latest_mtime(root: Path, site: str) -> float | None:\n'
        '    raw_dir = root / site / "raw"\n'
        '    if not raw_dir.exists():\n'
        '        return None\n'
        '    mtimes = [path.stat().st_mtime for path in raw_dir.glob("*.csv") if path.is_file()]\n'
        '    return max(mtimes) if mtimes else None\n'
        '\n'
        '\n'
        'def site_outs_freshness(root: Path, sites: list[str]) -> dict[str, object]:\n'
        '    site_entries: dict[str, object] = {}\n'
        '    all_fresh = True\n'
        '    for site in sites:\n'
        '        out_path = root / site / "out" / "panel_day_core.csv"\n'
        '        raw_mtime = raw_latest_mtime(root, site)\n'
        '        out_exists = out_path.exists()\n'
        '        out_mtime = out_path.stat().st_mtime if out_exists else None\n'
        '        fresh = bool(out_exists and raw_mtime is not None and out_mtime is not None and out_mtime >= raw_mtime)\n'
        '        site_entries[site] = {\n'
        '            "panel_day_core_exists": out_exists,\n'
        '            "raw_latest_mtime": raw_mtime,\n'
        '            "panel_day_core_mtime": out_mtime,\n'
        '            "fresh_enough": fresh,\n'
        '        }\n'
        '        if not fresh:\n'
        '            all_fresh = False\n'
        '    return {"all_fresh": all_fresh, "sites": site_entries}\n'
        '\n'
        '\n'
        'def resolve_reuse_existing_site_outs_root(\n'
        '    data_root: Path,\n'
        '    explicit_reuse_root: Path | None,\n'
        '    prefer_existing_site_outs: str,\n'
        '    sites: list[str],\n'
        ') -> tuple[Path | None, str, dict[str, object]]:\n'
        '    if explicit_reuse_root is not None:\n'
        '        return explicit_reuse_root, "explicit", {"mode": "explicit", "sites": {}}\n'
        '\n'
        '    if prefer_existing_site_outs == "off":\n'
        '        return None, "disabled", {"mode": "disabled", "sites": {}}\n'
        '\n'
        '    if site_outs_available(data_root, sites):\n'
        '        freshness = site_outs_freshness(data_root, sites)\n'
        '        if freshness["all_fresh"]:\n'
        '            return data_root, "auto_fresh" if prefer_existing_site_outs == "auto" else "forced_fresh", freshness\n'
        '        if prefer_existing_site_outs == "on":\n'
        '            raise SystemExit(\n'
        '                "prefer-existing-site-outs=on 이지만 data-root/<site>/out 가 raw보다 오래되었음"\n'
        '            )\n'
        '        return None, "auto_stale_out", freshness\n'
        '\n'
        '    if prefer_existing_site_outs == "on":\n'
        '        raise SystemExit(\n'
        '            f"prefer-existing-site-outs=on 이지만 data-root 아래 precomputed out를 찾지 못함: {data_root}"\n'
        '        )\n'
        '\n'
        '    return None, "not_available", {"mode": "not_available", "sites": {}}\n'
        '\n'
        '\n'
        'def normalize_text(value: object) -> str:\n'
        '    if value is None:\n'
        '        return ""\n'
        '    if isinstance(value, float) and pd.isna(value):\n'
        '        return ""\n'
        '    text = str(value).strip()\n'
        '    if text.lower() == "nan":\n'
        '        return ""\n'
        '    return text\n'
        '\n'
        '\n'
        'def truthy_mask(series: pd.Series) -> pd.Series:\n'
        '    lowered = series.astype(str).str.strip().str.lower()\n'
        '    return lowered.isin({"1", "true", "t", "yes"})\n'
        '\n'
        '\n'
        'def ensure_columns(df: pd.DataFrame, required: list[str], name: str) -> None:\n'
        '    missing = [column for column in required if column not in df.columns]\n'
        '    if missing:\n'
        '        raise SystemExit(f"{name} missing columns: {missing}")\n'
        '\n'
        '\n'
        'def row_key(site: object, panel_id: object) -> tuple[str, str]:\n'
        '    return normalize_text(site), normalize_text(panel_id)\n'
        '\n'
        '\n'
        'def display_heuristic_name(raw_label: object) -> str:\n'
        '    return shared_display_heuristic_name(raw_label)\n'
        '\n'
        '\n'
        'def display_heuristic_note(raw_label: object) -> str:\n'
        '    return shared_display_heuristic_note(raw_label)\n'
        '\n'
        '\n'
        'def choose_display_precursor_date(\n'
        '    event_type_ko: object,\n'
        '    interpreted_onset_date: object,\n'
        '    first_warning_date: object,\n'
        ') -> str:\n'
        '    if normalize_text(event_type_ko) != "전조형 고장":\n'
        '        return ""\n'
        '    onset_date = normalize_text(interpreted_onset_date)\n'
        '    if onset_date:\n'
        '        return onset_date\n'
        '    return normalize_text(first_warning_date)\n'
        '\n'
        '\n'
        'def choose_display_fault_date(\n'
        '    fault_date: object,\n'
        '    strict_trigger_date: object,\n'
        '    first_final_fault_date: object,\n'
        ') -> str:\n'
        '    for candidate in [fault_date, strict_trigger_date, first_final_fault_date]:\n'
        '        text = normalize_text(candidate)\n'
        '        if text:\n'
        '            return text\n'
        '    return ""\n'
        '\n'
        '\n'
        'def display_preview_precursor_date(value: object) -> str:\n'
        '    text = normalize_text(value)\n'
        '    return text if text else "전조없음"\n'
        '\n'
        '\n'
        'def display_signal_grade(row: pd.Series) -> str:\n'
        '    grade = normalize_text(row.get("운영해석등급_ko"))\n'
        '    if not grade:\n'
        '        grade = normalize_text(row.get("운영 판정"))\n'
        '    if not grade:\n'
        '        grade = normalize_text(row.get("현재상태"))\n'
        '    if grade:\n'
        '        if grade in {"고장 신호 포착", "고장 확정"}:\n'
        '            return "확정"\n'
        '        if grade == "강한 이상징후":\n'
        '            return "고위험 관찰"\n'
        '        if grade == "이상징후":\n'
        '            return "관찰"\n'
        '        return grade\n'
        '    if normalize_text(row.get("패널고장여부_ko")) == "고장":\n'
        '        return "확정"\n'
        '    return ""\n'
        '\n'
        '\n'
        'def display_existing_algorithm_source(value: object) -> str:\n'
        '    text = normalize_text(value)\n'
        '    if not text:\n'
        '        return "미검출"\n'
        '    if text.lower() == "none":\n'
        '        return "미검출"\n'
        '    if text == "기존 알고리즘 미검출":\n'
