        '    return pd.DataFrame(rows).reindex(columns=SIGNAL_PREVIEW_OUTPUT_COLS)\n'
        '\n'
        '\n'
        'def load_raw_only_common_module():\n'
        '    package = package_root()\n'
        '    if str(package) not in sys.path:\n'
        '        sys.path.insert(0, str(package))\n'
