        '        "panel_day_engine_abrupt6_symptom_map_v1.csv",\n'
        '        "panel_day_engine_kernellog_project_mapping_v1.csv",\n'
        '        "panel_day_engine_gpv7_perf_summary_v1.csv",\n'
        '        "panel_day_engine_project_final_decision_pack_v1.csv",\n'
        '        "panel_day_engine_precursor_onset_truth_v1.csv",\n'
        '        "panel_day_engine_non_precursor_performance_cases_v1.csv",\n'
        '        "panel_day_engine_common_cause_descriptive_retrofit_cases_v1.csv",\n'
        '        "panel_day_engine_gpvs_panel_attach_inventory_v1.csv",\n'
        '        "panel_day_engine_gpvs_panel_attach_feasibility_v1.csv",\n'
        '        "panel_day_engine_gpvs_panel_attach_candidates_v1.csv",\n'
        '        "panel_day_engine_precursor_abrupt_consistency_cases_v1.csv",\n'
        '        "panel_day_engine_precursor_abrupt_consistency_summary_v1.csv",\n'
        '        "panel_day_engine_precursor_abrupt_consistency_recommendation_v1.csv",\n'
        '        "panel_day_engine_c42997_1_1_forensic_summary_v1.csv",\n'
        '        "panel_day_engine_fault_panel_event_audit_v1.csv",\n'
        '        "panel_day_engine_detailed_fault_bridge_audit_v1.csv",\n'
        '        "panel_day_engine_detailed_fault_bridge_summary_v1.csv",\n'
        '        "panel_day_engine_gpvs_bytype_rebuild_summary_v1.csv",\n'
        '        "panel_day_engine_gpvs_detailed_type_inference_audit_v1.csv",\n'
        '        "panel_day_engine_gpvs_detailed_type_realpanel_sanity_v1.csv",\n'
        '        "panel_day_engine_gpvs_mlpe_panel_agreement_v1.csv",\n'
        '        "panel_day_engine_gpvs_canonical_dictionary_v1.csv",\n'
        '        "panel_day_engine_gpvs_mlpe_fault_matching_table_v1.csv",\n'
        '        "panel_day_engine_gpvs_mlpe_compatibility_summary_v1.csv",\n'
        '        "panel_day_engine_gpvs_mlpe_fault_matching_summary_v1.csv",\n'
        '        "panel_day_engine_gpvs_evidence_pack_v1.csv",\n'
        '        "panel_day_engine_panel_multiaxis_verdict_v1.csv",\n'
        '        "panel_date_reaudit_working.csv",\n'
        '    ]\n'
        '    missing_scripts = [name for name in required_scripts if not packaged_script_path(name).exists()]\n'
        '    missing_share = [name for name in required_share_inputs if not (packaged_share_root() / name).exists()]\n'
        '    supported = not missing_scripts and not missing_share\n'
        '    return {\n'
        '        "supported": supported,\n'
        '        "required_scripts": required_scripts,\n'
        '        "required_share_inputs": required_share_inputs,\n'
        '        "missing_scripts": missing_scripts,\n'
        '        "missing_share_inputs": missing_share,\n'
        '        "note_ko": (\n'
        '            "live chain은 package 내부에 복사된 bootstrap/audit/verdict/evidence/heuristic 스크립트와 "\n'
        '            "frozen share 입력을 사용해 workspace-only로 재계산한다."\n'
        '        ),\n'
