        '\n'
        '\n'
        'def packaged_raw_only_chain_support() -> dict[str, object]:\n'
        '    required_scripts = [\n'
        '        "runtime_rawonly_chain_common_v1.py",\n'
        '        "build_panel_day_engine_runtime_fault_event_audit_v1.py",\n'
        '        "build_panel_day_engine_runtime_final_verdict_v1.py",\n'
        '        "build_panel_day_engine_runtime_heuristic_v1.py",\n'
        '    ]\n'
        '    missing_scripts = [name for name in required_scripts if not packaged_script_path(name).exists()]\n'
        '    return {\n'
        '        "supported": not missing_scripts,\n'
        '        "required_scripts": required_scripts,\n'
        '        "missing_scripts": missing_scripts,\n'
        '        "note_ko": (\n'
        '            "raw-only chain은 package 내부에 복사된 runtime audit/verdict/heuristic 스크립트만 사용한다. "\n'
        '            "frozen share truth/support asset은 참조하지 않는다."\n'
        '        ),\n'
        '    }\n'
        '\n'
        '\n'
        'def normalize_core_digest_frame(df: pd.DataFrame, source_name: str) -> pd.DataFrame:\n'
        '    ensure_columns(df, CORE_DIGEST_COLUMNS, source_name)\n'
        '    digest_df = df.loc[:, CORE_DIGEST_COLUMNS].copy()\n'
        '    digest_df["date"] = pd.to_datetime(digest_df["date"], errors="coerce").dt.strftime("%Y-%m-%d").fillna("")\n'
        '    for column in CORE_DIGEST_COLUMNS:\n'
        '        if column == "date":\n'
        '            continue\n'
        '        digest_df[column] = digest_df[column].map(normalize_text)\n'
        '    digest_df["panel_id"] = digest_df["panel_id"].astype(str)\n'
        '    return digest_df.sort_values(["panel_id", "date"]).reset_index(drop=True)\n'
        '\n'
        '\n'
        'def build_core_digest_payload(df: pd.DataFrame, source_name: str) -> dict[str, object]:\n'
        '    digest_df = normalize_core_digest_frame(df, source_name)\n'
        '    joined_rows = "\\n".join(\n'
        '        "|".join(normalize_text(value) for value in row)\n'
        '        for row in digest_df.itertuples(index=False, name=None)\n'
        '    )\n'
        '    return {\n'
        '        "columns": CORE_DIGEST_COLUMNS,\n'
        '        "row_count": int(len(digest_df)),\n'
        '        "digest_sha256": hashlib.sha256(joined_rows.encode("utf-8")).hexdigest(),\n'
        '        "critical_source_counts": {\n'
        '            key: int(value)\n'
        '            for key, value in digest_df["critical_source"].value_counts(dropna=False).sort_index().items()\n'
        '        },\n'
        '        "anom_level_counts": {\n'
        '            key: int(value)\n'
        '            for key, value in digest_df["anom_level"].value_counts(dropna=False).sort_index().items()\n'
        '        },\n'
        '        "confirmed_fault_true_count": int(truthy_mask(digest_df["confirmed_fault"]).sum()),\n'
        '        "critical_fault_true_count": int(truthy_mask(digest_df["critical_fault"]).sum()),\n'
        '        "final_fault_true_count": int(truthy_mask(digest_df["final_fault"]).sum()),\n'
        '    }\n'
        '\n'
        '\n'
        'def load_core_baseline_digest() -> dict[str, object]:\n'
        '    path = baseline_core_digest_path()\n'
        '    if not path.exists():\n'
        '        raise SystemExit(f"missing packaged core baseline digest: {path}")\n'
        '    return json.loads(path.read_text(encoding="utf-8"))\n'
        '\n'
        '\n'
        'def compare_single_site_digest(expected: dict[str, object], actual: dict[str, object]) -> list[str]:\n'
        '    diffs: list[str] = []\n'
        '    for key in [\n'
        '        "row_count",\n'
        '        "digest_sha256",\n'
        '        "confirmed_fault_true_count",\n'
        '        "critical_fault_true_count",\n'
        '        "final_fault_true_count",\n'
        '    ]:\n'
        '        if expected.get(key) != actual.get(key):\n'
        '            diffs.append(f"{key}: expected={expected.get(key)} actual={actual.get(key)}")\n'
        '    if expected.get("columns") != actual.get("columns"):\n'
        '        diffs.append("columns: expected reference columns differ from actual columns")\n'
        '    if expected.get("critical_source_counts") != actual.get("critical_source_counts"):\n'
        '        diffs.append("critical_source_counts: expected reference counts differ from actual counts")\n'
        '    if expected.get("anom_level_counts") != actual.get("anom_level_counts"):\n'
        '        diffs.append("anom_level_counts: expected reference counts differ from actual counts")\n'
        '    return diffs\n'
        '\n'
        '\n'
        'def load_panel_day_core_from_workspace(workspace_root: Path, site: str) -> pd.DataFrame:\n'
        '    path = workspace_root / "data" / site / "out" / "panel_day_core.csv"\n'
        '    if not path.exists():\n'
        '        raise SystemExit(f"missing workspace panel_day_core: {path}")\n'
        '    df = pd.read_csv(path, low_memory=False)\n'
        '    ensure_columns(\n'
        '        df,\n'
        '        ["panel_id", "date", "final_fault", "critical_fault", "fault_like_day", "critical_source"],\n'
        '        path.name,\n'
        '    )\n'
        '    df["panel_id"] = df["panel_id"].astype(str)\n'
        '    df["date"] = pd.to_datetime(df["date"], errors="coerce")\n'
        '    return df\n'
        '\n'
        '\n'
        'def representative_algorithm_fields(site: str, core_df: pd.DataFrame, panel_id: str) -> dict[str, str]:\n'
        '    mapped = MAIL_BUCKET_ALGORITHM_MAP.get((normalize_text(site), normalize_text(panel_id)), "")\n'
        '    if mapped:\n'
        '        return {"커널로그 기존 알고리즘": mapped}\n'
        '    panel_df = core_df.loc[core_df["panel_id"].eq(str(panel_id))].copy().sort_values("date")\n'
        '    if panel_df.empty:\n'
        '        return {"커널로그 기존 알고리즘": ""}\n'
        '\n'
        '    final_days = panel_df.loc[truthy_mask(panel_df["final_fault"])]\n'
        '    critical_days = panel_df.loc[truthy_mask(panel_df["critical_fault"])]\n'
        '    fault_like_days = panel_df.loc[truthy_mask(panel_df["fault_like_day"])]\n'
        '\n'
        '    if not final_days.empty:\n'
        '        representative = final_days.iloc[0]\n'
        '    elif not critical_days.empty:\n'
        '        representative = critical_days.iloc[0]\n'
        '    elif not fault_like_days.empty:\n'
        '        representative = fault_like_days.iloc[0]\n'
        '    else:\n'
        '        representative = panel_df.iloc[-1]\n'
        '\n'
        '    return {"커널로그 기존 알고리즘": normalize_text(representative.get("critical_source"))}\n'
        '\n'
        '\n'
        'def build_live_fault_table(workspace_root: Path) -> pd.DataFrame:\n'
        '    verdict_path = workspace_root / "_share" / "panel_day_engine_panel_multiaxis_verdict_v1.csv"\n'
        '    heuristic_path = workspace_root / "_share" / "panel_day_engine_cause_candidate_heuristics_v1.csv"\n'
        '    audit_path = workspace_root / "_share" / "panel_day_engine_fault_panel_event_audit_v1.csv"\n'
        '    verdict_df = pd.read_csv(verdict_path, encoding="utf-8-sig", low_memory=False)\n'
        '    heuristic_df = pd.read_csv(heuristic_path, encoding="utf-8-sig", low_memory=False)\n'
        '    audit_df = pd.read_csv(audit_path, encoding="utf-8-sig", low_memory=False)\n'
        '    ensure_columns(\n'
        '        verdict_df,\n'
        '        ["site", "panel_id", "패널고장여부_ko", "사건유형_ko", "최종고장양상_ko", "커널로그_원인군_ko"],\n'
        '        verdict_path.name,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        heuristic_df,\n'
        '        ["site", "panel_id", "원인후보_top1_ko", "원인후보_top2_ko", "원인후보_top3_ko"],\n'
        '        heuristic_path.name,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        audit_df,\n'
        '        [\n'
        '            "site",\n'
        '            "panel_id",\n'
        '            "earliest_warning_date",\n'
        '            "strict_trigger_date",\n'
        '            "first_final_fault_date",\n'
        '        ],\n'
        '        audit_path.name,\n'
        '    )\n'
        '\n'
        '    heuristic_lookup = {\n'
        '        row_key(row["site"], row["panel_id"]): row\n'
        '        for row in heuristic_df.to_dict(orient="records")\n'
        '    }\n'
        '    audit_lookup = {\n'
        '        row_key(row["site"], row["panel_id"]): row\n'
        '        for row in audit_df.to_dict(orient="records")\n'
        '    }\n'
        '    rows: list[dict[str, str]] = []\n'
        '    for row in verdict_df.loc[verdict_df["패널고장여부_ko"].map(normalize_text).eq("고장")].to_dict(orient="records"):\n'
        '        key = row_key(row["site"], row["panel_id"])\n'
        '        heuristic_row = heuristic_lookup.get(key)\n'
        '        if heuristic_row is None:\n'
        '            raise SystemExit(f"missing heuristic row for fault panel: {key}")\n'
        '        audit_row = audit_lookup.get(key, {})\n'
        '        rows.append(\n'
        '            {\n'
        '                "site": normalize_text(row["site"]),\n'
        '                "panel_id": normalize_text(row["panel_id"]),\n'
        '                "패널고장여부_ko": normalize_text(row["패널고장여부_ko"]),\n'
        '                "사건유형_ko": normalize_text(row["사건유형_ko"]),\n'
        '                "최종고장양상_ko": normalize_text(row["최종고장양상_ko"]),\n'
        '                "커널로그_원인군_ko": normalize_text(row["커널로그_원인군_ko"]),\n'
        '                "1순위_의심원인_ko": display_heuristic_name(heuristic_row["원인후보_top1_ko"]),\n'
        '                "2순위_의심원인_ko": display_heuristic_name(heuristic_row["원인후보_top2_ko"]),\n'
        '                "3순위_의심원인_ko": display_heuristic_name(heuristic_row["원인후보_top3_ko"]),\n'
        '                "전조날짜": choose_display_precursor_date(\n'
        '                    event_type_ko=row.get("사건유형_ko"),\n'
        '                    interpreted_onset_date=row.get("사건해석상전조시작일"),\n'
        '                    first_warning_date=audit_row.get("earliest_warning_date"),\n'
        '                ),\n'
        '                "고장날짜": choose_display_fault_date(\n'
        '                    fault_date=row.get("세부fault_기준일"),\n'
        '                    strict_trigger_date=audit_row.get("strict_trigger_date"),\n'
        '                    first_final_fault_date=audit_row.get("first_final_fault_date"),\n'
        '                ),\n'
        '            }\n'
        '        )\n'
        '    return (\n'
        '        pd.DataFrame(rows)\n'
        '        .reindex(columns=LIVE_FAULT_OUTPUT_COLS)\n'
        '        .sort_values(["site", "panel_id"], ascending=[True, True])\n'
        '        .reset_index(drop=True)\n'
        '    )\n'
        '\n'
        '\n'
        'def build_live_fault_preview(workspace_root: Path, fault_df: pd.DataFrame) -> pd.DataFrame:\n'
        '    per_site_core = {\n'
        '        site: load_panel_day_core_from_workspace(workspace_root, site)\n'
        '        for site in sorted(fault_df["site"].astype(str).unique())\n'
        '    }\n'
        '    rows: list[dict[str, str]] = []\n'
        '    for _, row in fault_df.iterrows():\n'
        '        site = normalize_text(row["site"])\n'
        '        panel_id = normalize_text(row["panel_id"])\n'
        '        rows.append(\n'
        '            {\n'
        '                "site": site,\n'
        '                "panel_id": panel_id,\n'
        '                "패널고장여부_ko": normalize_text(row["패널고장여부_ko"]),\n'
        '                "사건유형_ko": normalize_text(row["사건유형_ko"]),\n'
        '                "최종고장양상_ko": normalize_text(row["최종고장양상_ko"]),\n'
        '                "전조날짜": normalize_text(row.get("전조날짜")),\n'
        '                "고장날짜": normalize_text(row.get("고장날짜")),\n'
        '                "라벨된 fault": normalize_text(row["커널로그_원인군_ko"]),\n'
        '                "1순위_의심원인_ko": normalize_text(row["1순위_의심원인_ko"]),\n'
        '                "2순위_의심원인_ko": normalize_text(row["2순위_의심원인_ko"]),\n'
        '                "3순위_의심원인_ko": normalize_text(row["3순위_의심원인_ko"]),\n'
        '                **representative_algorithm_fields(site, per_site_core[site], panel_id),\n'
        '            }\n'
        '        )\n'
        '    return pd.DataFrame(rows).reindex(columns=LIVE_PREVIEW_OUTPUT_COLS)\n'
        '\n'
        '\n'
        'def compare_live_fault_to_fixed(live_fault_df: pd.DataFrame) -> dict[str, object]:\n'
        '    fixed_path = fixed_fault6_table_path()\n'
        '    if not fixed_path.exists():\n'
        '        return {\n'
        '            "fixed_reference_available": False,\n'
        '            "exact_match": False,\n'
        '            "diff_columns": [],\n'
        '        }\n'
        '    fixed_df = pd.read_csv(fixed_path, encoding="utf-8-sig", low_memory=False).sort_values(["site", "panel_id"]).reset_index(drop=True)\n'
        '    live_df = live_fault_df.sort_values(["site", "panel_id"]).reset_index(drop=True)\n'
        '    diff_columns: list[str] = []\n'
        '    if len(fixed_df) != len(live_df):\n'
        '        diff_columns.append("__row_count__")\n'
        '    else:\n'
        '        for column in LIVE_FAULT_OUTPUT_COLS:\n'
        '            if column not in LIVE_FAULT_COMPARE_COLS:\n'
        '                continue\n'
        '            left = fixed_df[column].fillna("").astype(str)\n'
        '            right = live_df[column].fillna("").astype(str)\n'
        '            if not left.equals(right):\n'
        '                diff_columns.append(column)\n'
        '    return {\n'
        '        "fixed_reference_available": True,\n'
        '        "exact_match": not diff_columns,\n'
        '        "diff_columns": diff_columns,\n'
        '        "fixed_row_count": int(len(fixed_df)),\n'
        '        "live_row_count": int(len(live_df)),\n'
        '    }\n'
        '\n'
        '\n'
        'def publish_live_chain_outputs(output_root: Path, result_dir: Path, summary_path: Path) -> dict[str, str]:\n'
        '    root_result_dir = output_root / "result"\n'
        '    root_result_dir.mkdir(parents=True, exist_ok=True)\n'
        '\n'
        '    mapping = {\n'
        '        result_dir / "fault_panel_result_live_v1.csv": root_result_dir / ROOT_LIVE_FAULT_NAME,\n'
        '        result_dir / "fault_panel_result_live_preview_v1.csv": root_result_dir / ROOT_LIVE_PREVIEW_NAME,\n'
        '    }\n'
        '    published: dict[str, str] = {}\n'
        '    for source, target in mapping.items():\n'
        '        if not source.exists():\n'
        '            raise SystemExit(f"missing live chain output for publish step: {source}")\n'
        '        shutil.copy2(source, target)\n'
        '        published[target.name] = str(target)\n'
        '    return published\n'
        '\n'
        '\n'
        'def publish_raw_only_chain_outputs(output_root: Path, result_dir: Path) -> dict[str, str]:\n'
        '    root_result_dir = output_root / "result"\n'
        '    root_result_dir.mkdir(parents=True, exist_ok=True)\n'
        '    mapping = {\n'
        '        result_dir / "fault_panel_result_raw_only_v1.csv": root_result_dir / ROOT_RAWONLY_FAULT_NAME,\n'
        '        result_dir / "fault_panel_result_raw_only_preview_v1.csv": root_result_dir / ROOT_RAWONLY_PREVIEW_NAME,\n'
        '    }\n'
        '    published: dict[str, str] = {}\n'
        '    for source, target in mapping.items():\n'
        '        if not source.exists():\n'
        '            raise SystemExit(f"missing raw-only chain output for publish step: {source}")\n'
        '        shutil.copy2(source, target)\n'
        '        published[target.name] = str(target)\n'
        '    return published\n'
        '\n'
        '\n'
        'def build_strict_raw_only_current_outputs(\n'
        '    raw_only_chain_result: dict[str, object],\n'
        '    evidence_df: pd.DataFrame,\n'
        ') -> tuple[pd.DataFrame, pd.DataFrame, dict[str, object]]:\n'
        '    candidate_fault_path = Path(\n'
        '        str(raw_only_chain_result.get("generated_outputs", {}).get("fault_panel_result_raw_only_v1", ""))\n'
        '    )\n'
        '    candidate_preview_path = Path(\n'
        '        str(raw_only_chain_result.get("generated_outputs", {}).get("fault_panel_result_raw_only_preview_v1", ""))\n'
        '    )\n'
        '    if not candidate_fault_path.exists() or not candidate_preview_path.exists():\n'
        '        raise SystemExit("missing candidate raw-only outputs for strict current publish")\n'
        '\n'
        '    candidate_fault_df = pd.read_csv(candidate_fault_path, encoding="utf-8-sig", low_memory=False)\n'
        '    candidate_preview_df = pd.read_csv(candidate_preview_path, encoding="utf-8-sig", low_memory=False)\n'
        '    strict_keys = {\n'
        '        row_key(row["site"], row["panel_id"])\n'
        '        for row in evidence_df.to_dict(orient="records")\n'
        '        if normalize_text(row.get("운영해석등급_ko")) in RAW_ONLY_STRICT_CURRENT_GRADES\n'
        '    }\n'
        '    if strict_keys:\n'
        '        strict_fault_df = candidate_fault_df.loc[\n'
        '            candidate_fault_df.apply(lambda row: row_key(row["site"], row["panel_id"]) in strict_keys, axis=1)\n'
        '        ].copy()\n'
        '        strict_preview_df = candidate_preview_df.loc[\n'
        '            candidate_preview_df.apply(lambda row: row_key(row["site"], row["panel_id"]) in strict_keys, axis=1)\n'
        '        ].copy()\n'
        '    else:\n'
        '        strict_fault_df = candidate_fault_df.iloc[0:0].copy()\n'
        '        strict_preview_df = candidate_preview_df.iloc[0:0].copy()\n'
        '\n'
        '    strict_fault_df = strict_fault_df.sort_values(["site", "panel_id"]).reset_index(drop=True)\n'
        '    strict_preview_df = strict_preview_df.sort_values(["site", "panel_id"]).reset_index(drop=True)\n'
        '    date_lookup = {\n'
        '        row_key(row["site"], row["panel_id"]): {\n'
        '            "전조날짜": normalize_text(row.get("전조날짜")),\n'
        '            "고장날짜": normalize_text(row.get("고장날짜")),\n'
        '        }\n'
        '        for row in evidence_df.to_dict(orient="records")\n'
        '    }\n'
        '    for df in [strict_fault_df, strict_preview_df]:\n'
        '        if df.empty:\n'
        '            continue\n'
        '        df["전조날짜"] = df.apply(\n'
        '            lambda row: date_lookup.get(row_key(row["site"], row["panel_id"]), {}).get("전조날짜", ""),\n'
        '            axis=1,\n'
        '        )\n'
        '        df["고장날짜"] = df.apply(\n'
        '            lambda row: date_lookup.get(row_key(row["site"], row["panel_id"]), {}).get("고장날짜", ""),\n'
        '            axis=1,\n'
        '        )\n'
        '        ordered_cols = [column for column in df.columns if column not in {"전조날짜", "고장날짜"}]\n'
        '        insert_at = ordered_cols.index("최종고장양상_ko") + 1 if "최종고장양상_ko" in ordered_cols else len(ordered_cols)\n'
        '        ordered_cols[insert_at:insert_at] = ["전조날짜", "고장날짜"]\n'
        '        df = df.reindex(columns=ordered_cols)\n'
        '        if df is strict_fault_df:\n'
        '            strict_fault_df = df\n'
        '        else:\n'
        '            strict_preview_df = df\n'
        '    meta = {\n'
        '        "publish_policy_ko": "raw_only current는 운영해석등급_ko=확정 strict subset만 노출",\n'
        '        "strict_grade_csv": ",".join(sorted(RAW_ONLY_STRICT_CURRENT_GRADES)),\n'
        '        "candidate_row_count": int(len(candidate_fault_df)),\n'
        '        "published_current_row_count": int(len(strict_fault_df)),\n'
        '        "dropped_candidate_row_count": int(len(candidate_fault_df) - len(strict_fault_df)),\n'
        '    }\n'
        '    return strict_fault_df, strict_preview_df, meta\n'
        '\n'
        '\n'
        'def publish_raw_only_current_outputs(\n'
        '    output_root: Path,\n'
        '    strict_fault_df: pd.DataFrame,\n'
        '    strict_preview_df: pd.DataFrame,\n'
        ') -> dict[str, str]:\n'
        '    root_result_dir = output_root / "result"\n'
        '    root_result_dir.mkdir(parents=True, exist_ok=True)\n'
        '    fault_path = root_result_dir / ROOT_RAWONLY_FAULT_NAME\n'
        '    preview_path = root_result_dir / ROOT_RAWONLY_PREVIEW_NAME\n'
        '    strict_fault_df.to_csv(fault_path, index=False, encoding="utf-8-sig")\n'
        '    strict_preview_df.to_csv(preview_path, index=False, encoding="utf-8-sig")\n'
        '    return {\n'
        '        ROOT_RAWONLY_FAULT_NAME: str(fault_path),\n'
        '        ROOT_RAWONLY_PREVIEW_NAME: str(preview_path),\n'
        '    }\n'
        '\n'
        '\n'
        'def markdown_table_from_df(df: pd.DataFrame) -> str:\n'
        '    if df.empty:\n'
        '        return "_empty_"\n'
        '    safe_df = df.fillna("").astype(str)\n'
        '    headers = safe_df.columns.tolist()\n'
        '    lines = [\n'
        '        "| " + " | ".join(headers) + " |",\n'
        '        "| " + " | ".join(["---"] * len(headers)) + " |",\n'
        '    ]\n'
        '    for row in safe_df.itertuples(index=False, name=None):\n'
        '        lines.append("| " + " | ".join(str(value) for value in row) + " |")\n'
        '    return "\\n".join(lines)\n'
        '\n'
        '\n'
        'def truncate_report_df(df: pd.DataFrame, limit: int = 20) -> pd.DataFrame:\n'
        '    if df.empty or len(df) <= limit:\n'
        '        return df\n'
        '    return df.head(limit).copy()\n'
        '\n'
        '\n'
        'def build_live_report_markdown(\n'
        '    sites: list[str],\n'
        '    baseline_comparison: dict[str, object],\n'
        '    compare: dict[str, object],\n'
        '    published_outputs: dict[str, str],\n'
        '    live_preview_df: pd.DataFrame,\n'
        ') -> str:\n'
        '    site_lines = "\\n".join(f"- `{site}`" for site in sites)\n'
        '    baseline_site_lines = []\n'
        '    for site in sites:\n'
        '        site_entry = baseline_comparison.get("sites", {}).get(site, {})\n'
        '        baseline_site_lines.append(\n'
        '            f"- `{site}`: `match={site_entry.get(\'match\')}`"\n'
        '        )\n'
        '    baseline_block = "\\n".join(baseline_site_lines)\n'
        '    output_lines = "\\n".join(\n'
        '        f"- `{name}`: `{path}`" for name, path in sorted(published_outputs.items())\n'
        '    )\n'
        '    return (\n'
        '        "# fault_panel_result_current_report_v1\\n\\n"\n'
        '        "## 목적\\n"\n'
        '        "현재 runtime 실행에서 운영자가 바로 확인할 `운영 공식 current` 결과를 한 곳에 모아 보여준다.\\n\\n"\n'
        '        "## 실행 대상 site\\n"\n'
        '        f"{site_lines}\\n\\n"\n'
        '        "## baseline 입력 비교\\n"\n'
        '        f"- `all_sites_match`: `{baseline_comparison.get(\'all_sites_match\')}`\\n"\n'
        '        f"{baseline_block}\\n\\n"\n'
        '        "## live chain 상태\\n"\n'
        '        f"- `fixed_fault_reference_exact_match`: `{compare.get(\'exact_match\')}`\\n"\n'
        '        f"- `baseline_input_all_sites_match`: `{compare.get(\'baseline_input_all_sites_match\')}`\\n"\n'
        '        f"- `diff_columns`: `{compare.get(\'diff_columns\', [])}`\\n\\n"\n'
        '        "## 읽는 법\\n"\n'
        '        "- 이 report는 `official current` 설명용 문서다.\\n"\n'
        '        "- `fault_panel_result_current_preview_v1.csv`와 함께 현재 운영 공식 결과를 먼저 읽는 기본 문서다.\\n"\n'
        '        "- `raw-only` 보조표나 analyst artifact를 대신하지 않는다.\\n"\n'
        '        "- `fault_panel_result_master_report_v1.md`는 artifact 안내와 fallback 설명용 문서이며, 이 report를 대체하지 않는다.\\n\\n"\n'
        '        "## 주요 산출물\\n"\n'
        '        f"{output_lines}\\n\\n"\n'
        '        "## 현재 preview 표\\n"\n'
        '        f"{markdown_table_from_df(live_preview_df)}\\n"\n'
        '    )\n'
        '\n'
        '\n'
        'def build_raw_only_report_markdown(\n'
        '    sites: list[str],\n'
        '    compare: dict[str, object],\n'
        '    published_outputs: dict[str, str],\n'
        '    live_preview_df: pd.DataFrame,\n'
        '    publish_meta: dict[str, object] | None = None,\n'
        ') -> str:\n'
        '    site_lines = "\\n".join(f"- `{site}`" for site in sites)\n'
        '    output_lines = "\\n".join(\n'
        '        f"- `{name}`: `{path}`" for name, path in sorted(published_outputs.items())\n'
        '    )\n'
        '    publish_meta = publish_meta or {}\n'
        '    return (\n'
        '        "# fault_panel_result_raw_only_current_report_v1\\n\\n"\n'
        '        "## 목적\\n"\n'
        '        "raw-only algorithm candidate chain 중 운영 strict current로 승격된 현재 결과를 `분석용/운영 보조표`로 확인한다.\\n\\n"\n'
        '        "## 실행 대상 site\\n"\n'
        '        f"{site_lines}\\n\\n"\n'
        '        "## raw-only vs fixed reference 비교\\n"\n'
        '        f"- `status_ko`: `{compare.get(\'status_ko\')}`\\n"\n'
        '        f"- `reference_available`: `{compare.get(\'reference_available\')}`\\n"\n'
        '        f"- `row_key_match`: `{compare.get(\'row_key_match\')}`\\n"\n'
        '        f"- `decision_columns_match`: `{compare.get(\'decision_columns_match\')}`\\n"\n'
        '        f"- `overlap_decision_columns_match`: `{compare.get(\'overlap_decision_columns_match\')}`\\n"\n'
        '        f"- `exact_match`: `{compare.get(\'exact_match\')}`\\n"\n'
        '        f"- `reference_row_count`: `{compare.get(\'reference_row_count\')}`\\n"\n'
        '        f"- `candidate_row_count`: `{compare.get(\'candidate_row_count\')}`\\n"\n'
        '        f"- `matched_row_key_count`: `{compare.get(\'matched_row_key_count\')}`\\n"\n'
        '        f"- `diff_columns`: `{compare.get(\'diff_columns\', [])}`\\n\\n"\n'
        '        f"- `overlap_diff_columns`: `{compare.get(\'overlap_diff_columns\', [])}`\\n\\n"\n'
        '        "## current 출력 정책\\n"\n'
        '        f"- `publish_policy_ko`: `{publish_meta.get(\'publish_policy_ko\', \'\')}`\\n"\n'
        '        f"- `strict_grade_csv`: `{publish_meta.get(\'strict_grade_csv\', \'\')}`\\n"\n'
        '        f"- `published_current_row_count`: `{publish_meta.get(\'published_current_row_count\', \'\')}`\\n"\n'
        '        f"- `candidate_row_count`: `{publish_meta.get(\'candidate_row_count\', \'\')}`\\n"\n'
        '        f"- `dropped_candidate_row_count`: `{publish_meta.get(\'dropped_candidate_row_count\', \'\')}`\\n\\n"\n'
        '        "## 주의\\n"\n'
        '        "- `커널로그_원인군_ko` 컬럼명은 유지하지만, 이 report에서는 raw-only algorithm-derived family 의미다.\\n"\n'
        '        "- 이 chain은 frozen truth/support asset을 참조하지 않는다.\\n\\n"\n'
        '        "- 이 report는 `official current report`가 아니며, 운영 공식 결과를 대체하지 않는다.\\n"\n'
        '        "- 운영자 기본 진입점은 `fault_panel_result_current_*` 계열이고, 이 report는 analyst/support 확인용이다.\\n\\n"\n'
        '        "- preview 표의 `사건 종결 요약`은 관측 플래그를 먼저 본 뒤, 확정 row에서만 채워지는 요약이다.\\n\\n"\n'
        '        "- `result/raw_only_chain/*`에는 전체 candidate가 남고, `result/fault_panel_result_raw_only_current_*`는 strict current subset만 노출한다.\\n\\n"\n'
        '        "## 주요 산출물\\n"\n'
        '        f"{output_lines}\\n\\n"\n'
        '        "## 현재 preview 표\\n"\n'
        '        f"{markdown_table_from_df(truncate_report_df(live_preview_df))}\\n"\n'
        '    )\n'
        '\n'
        '\n'
        'def build_master_report_markdown(\n'
        '    sites: list[str],\n'
        '    baseline_comparison: dict[str, object],\n'
        '    live_chain_result: dict[str, object],\n'
        '    raw_only_chain_result: dict[str, object],\n'
        '    live_preview_df: pd.DataFrame,\n'
        '    raw_only_preview_df: pd.DataFrame,\n'
        '    precursor_report_df: pd.DataFrame | None = None,\n'
        '    fault_signal_report_df: pd.DataFrame | None = None,\n'
        '    detailed_report_path: Path | None = None,\n'
        '    precursor_report_path: Path | None = None,\n'
        '    fault_signal_report_path: Path | None = None,\n'
        ') -> str:\n'
        '    site_lines = "\\n".join(f"- `{site}`" for site in sites)\n'
        '    baseline_site_lines = []\n'
        '    for site in sites:\n'
        '        site_entry = baseline_comparison.get("sites", {}).get(site, {})\n'
        '        baseline_site_lines.append(f"- `{site}`: `match={site_entry.get(\'match\')}`")\n'
        '    baseline_block = "\\n".join(baseline_site_lines)\n'
        '    live_compare = live_chain_result.get("fixed_fault_reference_compare", {})\n'
        '    raw_only_compare = raw_only_chain_result.get("fixed_fault_reference_compare", {})\n'
        '    primary_output_lines = []\n'
        '    analyst_output_lines = []\n'
        '    for name, path in sorted(live_chain_result.get("published_outputs", {}).items()):\n'
        '        primary_output_lines.append(f"- `live::{name}`: `{path}`")\n'
        '    for name, path in sorted(raw_only_chain_result.get("published_outputs", {}).items()):\n'
        '        analyst_output_lines.append(f"- `raw_only::{name}`: `{path}`")\n'
        '    primary_output_block = "\\n".join(primary_output_lines) if primary_output_lines else "_none_"\n'
        '    analyst_output_block = "\\n".join(analyst_output_lines) if analyst_output_lines else "_none_"\n'
        '    precursor_report_df = precursor_report_df if precursor_report_df is not None else pd.DataFrame()\n'
        '    fault_signal_report_df = fault_signal_report_df if fault_signal_report_df is not None else pd.DataFrame()\n'
        '    precursor_keys = set(\n'
        '        zip(\n'
        '            precursor_report_df.get("site", pd.Series(dtype=object)).astype(str),\n'
        '            precursor_report_df.get("panel_id", pd.Series(dtype=object)).astype(str),\n'
        '        )\n'
        '    )\n'
        '    fault_signal_keys = set(\n'
        '        zip(\n'
        '            fault_signal_report_df.get("site", pd.Series(dtype=object)).astype(str),\n'
        '            fault_signal_report_df.get("panel_id", pd.Series(dtype=object)).astype(str),\n'
        '        )\n'
        '    )\n'
        '    overlap_row_count = len(precursor_keys & fault_signal_keys)\n'
        '    fault_signal_subgroup_summary = pd.DataFrame(\n'
        '        columns=["site", "group root", "subgroup base", "row_count"]\n'
        '    )\n'
        '    fault_signal_cluster_summary = pd.DataFrame(\n'
        '        columns=[\n'
        '            "site",\n'
        '            "group root",\n'
        '            "subgroup base",\n'
        '            "subgroup cluster",\n'
        '            "row_count",\n'
        '            "min_signal_date",\n'
        '            "max_signal_date",\n'
        '        ]\n'
        '    )\n'
        '    if fault_signal_report_df is not None and not fault_signal_report_df.empty:\n'
        '        working = fault_signal_report_df.copy()\n'
        '        working["group root"] = working["group root"].map(normalize_text)\n'
        '        working["subgroup base"] = working["subgroup base"].map(normalize_text)\n'
        '        working["subgroup cluster"] = working["subgroup cluster"].map(normalize_text)\n'
        '        working["신호 기준일_dt"] = pd.to_datetime(working["신호 기준일"], errors="coerce")\n'
        '        working = working.loc[working["subgroup base"].ne("")].copy()\n'
        '        if not working.empty:\n'
        '            fault_signal_subgroup_summary = (\n'
        '                working.groupby(["site", "group root", "subgroup base"], dropna=False)\n'
        '                .size()\n'
        '                .rename("row_count")\n'
        '                .reset_index()\n'
        '                .sort_values(\n'
        '                    ["row_count", "site", "group root", "subgroup base"],\n'
        '                    ascending=[False, True, True, True],\n'
        '                )\n'
        '                .reset_index(drop=True)\n'
        '            )\n'
        '            fault_signal_cluster_summary = (\n'
        '                working.groupby(\n'
        '                    ["site", "group root", "subgroup base", "subgroup cluster"], dropna=False\n'
        '                )\n'
        '                .agg(\n'
        '                    row_count=("panel_id", "size"),\n'
        '                    min_signal_date=("신호 기준일_dt", "min"),\n'
        '                    max_signal_date=("신호 기준일_dt", "max"),\n'
        '                )\n'
        '                .reset_index()\n'
        '                .sort_values(\n'
        '                    ["row_count", "site", "group root", "subgroup base", "subgroup cluster"],\n'
        '                    ascending=[False, True, True, True, True],\n'
        '                )\n'
        '                .reset_index(drop=True)\n'
        '            )\n'
        '            for column in ["min_signal_date", "max_signal_date"]:\n'
        '                fault_signal_cluster_summary[column] = pd.to_datetime(\n'
        '                    fault_signal_cluster_summary[column], errors="coerce"\n'
        '                ).dt.strftime("%Y-%m-%d")\n'
        '    fault_signal_unique_group_root_count = (\n'
        '        int(len(fault_signal_subgroup_summary[["site", "group root"]].drop_duplicates()))\n'
        '        if not fault_signal_subgroup_summary.empty\n'
        '        else 0\n'
        '    )\n'
        '    fault_signal_unique_subgroup_base_count = (\n'
        '        int(len(fault_signal_subgroup_summary[["site", "subgroup base"]].drop_duplicates()))\n'
        '        if not fault_signal_subgroup_summary.empty\n'
        '        else 0\n'
        '    )\n'
        '    fault_signal_unique_subgroup_cluster_count = (\n'
        '        int(len(fault_signal_cluster_summary[["site", "subgroup cluster"]].drop_duplicates()))\n'
        '        if not fault_signal_cluster_summary.empty\n'
        '        else 0\n'
        '    )\n'
        '    fault_signal_top_subgroup_block = (\n'
        '        markdown_table_from_df(fault_signal_subgroup_summary.head(10))\n'
        '        if not fault_signal_subgroup_summary.empty\n'
        '        else "_none_"\n'
        '    )\n'
        '    fault_signal_top_cluster_block = (\n'
        '        markdown_table_from_df(fault_signal_cluster_summary.head(10))\n'
        '        if not fault_signal_cluster_summary.empty\n'
        '        else "_none_"\n'
        '    )\n'
        '    detailed_report_block = (\n'
        '        f"- `fault_panel_result_detailed_report_v1.xlsx`: `{detailed_report_path}`\\n\\n"\n'
        '        if detailed_report_path is not None\n'
        '        else ""\n'
        '    )\n'
        '    precursor_report_block = (\n'
        '        f"- `fault_panel_result_precursor_report_v1.csv`: `{precursor_report_path}`\\n\\n"\n'
        '        if precursor_report_path is not None\n'
        '        else ""\n'
        '    )\n'
        '    fault_signal_report_block = (\n'
        '        f"- `{ROOT_FAULT_SIGNAL_REPORT_NAME}`: `{fault_signal_report_path}`\\n\\n"\n'
        '        if fault_signal_report_path is not None\n'
        '        else ""\n'
        '    )\n'
        '    return (\n'
        '        "# fault_panel_result_master_report_v1\\n\\n"\n'
        '        "## 목적\\n"\n'
        '        "frozen-support live chain과 raw-only algorithm candidate chain을 비교하고, 어떤 artifact를 어떤 순서로 읽을지 안내한다.\\n\\n"\n'
        '        "## 실행 대상 site\\n"\n'
        '        f"{site_lines}\\n\\n"\n'
        '        "## baseline 입력 비교\\n"\n'
        '        f"- `all_sites_match`: `{baseline_comparison.get(\'all_sites_match\')}`\\n"\n'
        '        f"{baseline_block}\\n\\n"\n'
        '        "## frozen-support live chain 요약\\n"\n'
        '        f"- `status_ko`: `{live_chain_result.get(\'status_ko\')}`\\n"\n'
        '        f"- `fixed_fault_reference_exact_match`: `{live_compare.get(\'exact_match\')}`\\n"\n'
        '        f"- `baseline_input_all_sites_match`: `{live_compare.get(\'baseline_input_all_sites_match\')}`\\n"\n'
        '        f"- `diff_columns`: `{live_compare.get(\'diff_columns\', [])}`\\n\\n"\n'
        '        "## raw-only algorithm candidate chain 요약\\n"\n'
        '        f"- `status_ko`: `{raw_only_compare.get(\'status_ko\')}`\\n"\n'
        '        f"- `reference_available`: `{raw_only_compare.get(\'reference_available\')}`\\n"\n'
        '        f"- `overlap_decision_columns_match`: `{raw_only_compare.get(\'overlap_decision_columns_match\')}`\\n"\n'
        '        f"- `reference_row_count`: `{raw_only_compare.get(\'reference_row_count\')}`\\n"\n'
        '        f"- `candidate_row_count`: `{raw_only_compare.get(\'candidate_row_count\')}`\\n"\n'
        '        f"- `published_current_row_count`: `{raw_only_chain_result.get(\'publish_meta\', {}).get(\'published_current_row_count\', \'\')}`\\n"\n'
        '        f"- `matched_row_key_count`: `{raw_only_compare.get(\'matched_row_key_count\')}`\\n"\n'
        '        f"- `overlap_diff_columns`: `{raw_only_compare.get(\'overlap_diff_columns\', [])}`\\n\\n"\n'
        '        "## report split 요약\\n"\n'
        '        f"- `precursor_candidate_row_count`: `{len(precursor_report_df)}`\\n"\n'
        '        f"- `raw_only_fault_signal_row_count`: `{len(fault_signal_report_df)}`\\n"\n'
        '        f"- `raw_only_fault_signal_unique_group_root_count`: `{fault_signal_unique_group_root_count}`\\n"\n'
        '        f"- `raw_only_fault_signal_unique_subgroup_base_count`: `{fault_signal_unique_subgroup_base_count}`\\n"\n'
        '        f"- `raw_only_fault_signal_unique_subgroup_cluster_count`: `{fault_signal_unique_subgroup_cluster_count}`\\n"\n'
        '        f"- `report_row_overlap_count`: `{overlap_row_count}`\\n\\n"\n'
        '        "## 먼저 보는 법\\n"\n'
        '        "- `fault_panel_result_current_*`: frozen-support live chain 기준의 공식 current 결과를 먼저 확인한다. current preview/current report가 있으면 그쪽이 공식 current 설명의 주 문서다.\\n"\n'
        '        "- `fault_panel_result_precursor_report_v1.csv`: 아직 고장 신호는 없지만 추적 가치가 있는 precursor candidate를 본다.\\n"\n'
        '        "- raw-only artifact는 operator 기본 읽기 순서가 아니라 아래 `analyst/support 추가 자료` 섹션에서 필요 시 확인한다.\\n\\n"\n'
        '        "## 해석 가이드\\n"\n'
        '        "- 이 문서는 공식 current 설명 문서를 대체하지 않는 안내/fallback 문서다. current preview/current report가 있으면 그쪽을 먼저 읽는다.\\n"\n'
        '        "- `fault_panel_result_current_*`는 frozen-support live chain 기준 결과다.\\n"\n'
        '        "- `fault_panel_result_raw_only_current_*`는 raw-only candidate 중 strict current subset만 보여준다.\\n"\n'
        '        "- `fault_panel_result_precursor_report_v1.csv`는 고장 신호가 아직 없는 precursor candidate만 보여준다.\\n"\n'
        '        f"- `{ROOT_FAULT_SIGNAL_REPORT_NAME}`는 raw-only candidate 우주에서 고장 신호가 이미 관측된 panel만 모은 analyst/support 보조표다.\\n"\n'
        '        "- raw-only chain의 `커널로그_원인군_ko`는 기존 라벨 family가 아니라 algorithm-derived family 의미다.\\n"\n'
        '        "- preview 표의 `운영 판정`은 현재 신호 단계, `상위 해석 후보`는 가장 가까운 원인 후보를 뜻한다.\\n"\n'
        '        "- `급락 종결 관측`과 `점진 저하 누적`은 관측 축이고, `사건 종결 요약`은 확정 row에서만 채워지는 사건 요약이다.\\n"\n'
        '        "- `고장 기준일`은 확정 고장일만 뜻하는 칼럼이 아니라 판단 기준으로 삼은 날짜다.\\n"\n'
        '        "- `기존 알고리즘 source`의 `미검출`은 legacy source 태그가 없다는 뜻이다.\\n"\n'
        '        "- precursor report와 raw-only fault signal report는 row가 중복되지 않게 분리해 읽어야 한다.\\n"\n'
        '        "- raw-only fault signal report의 row 수는 `panel_id` 기준 count이고, 같은 `subgroup base` 아래 여러 panel이 함께 잡히면 여러 row로 보일 수 있다.\\n"\n'
        '        f"- `subgroup cluster`는 같은 subgroup base 안에서 `신호 기준일` 간격이 `{FAULT_SIGNAL_CLUSTER_GAP_DAYS}`일 이하인 row를 하나의 보조 cluster로 묶은 analyst/support 휴리스틱이다.\\n"\n'
        '        "- 운영자는 기본적으로 current -> precursor 순서로 읽고, raw-only artifact는 analyst/support 추가 자료가 필요할 때만 연다.\\n"\n'
        '        "- 전체 candidate universe는 `result/raw_only_chain/*`와 detailed report 안에 그대로 남는다.\\n\\n"\n'
        '        "## 컬럼 읽는 법\\n"\n'
        '        "- precursor report의 `전조 축`은 EWS/AE/DTW/규칙징후 중 어떤 축이 전조로 묶였는지 보여준다.\\n"\n'
        '        "- precursor report의 `대표 전조 신호`는 전조 후보를 만든 누적 신호를 짧게 풀어쓴 요약이다.\\n"\n'
        '        "- precursor report의 `모니터링 권고`는 다음 수집 주기에 무엇을 먼저 확인할지 알려주는 운영 메모다.\\n"\n'
        '        "- precursor report의 `공통원인 위험`과 `권고 검토 레인`은 panel-local precursor로 읽기 전에 공통 외란 가능성을 얼마나 먼저 볼지 정리한 보조 값이다.\\n"\n'
        '        "- raw-only fault signal report의 `group root`는 넓은 family root, `subgroup base`는 common-cause 검토에 더 가까운 하위 묶음이다.\\n"\n'
        '        "- raw-only fault signal report의 `동일 subgroup row 수`는 같은 subgroup base 아래 함께 잡힌 panel row 수다.\\n"\n'
        '        "- raw-only fault signal report의 `subgroup cluster`와 `동일 cluster row 수`는 `사건 수`를 직접 뜻하지 않고, 같은 subgroup base 안에서 가까운 날짜 row를 묶어 읽기 쉽게 만든 보조 값이다.\\n"\n'
        '        "- raw-only fault signal report의 `확정 경로`는 주 경로 하나만 보여주고, `고장 신호 요약`은 일수와 보조 근거를 덧붙인다.\\n"\n'
        '        "- raw-only fault signal report의 `근접 공통원인`은 strict_trigger 기준 ±3일 안의 common-cause만 적고, warning-anchor 기준 common-cause는 audit 전용으로 남긴다.\\n"\n'
