        'def auto_fit_workbook_columns(path: Path) -> None:\n'
        '    try:\n'
        '        from openpyxl import load_workbook\n'
        '        from openpyxl.utils import get_column_letter\n'
        '    except ModuleNotFoundError as exc:\n'
        '        raise SystemExit(\n'
        '            "openpyxl is required to generate fault_panel_result_detailed_report_v1.xlsx"\n'
        '        ) from exc\n'
        '\n'
        '    workbook = load_workbook(path)\n'
        '    for worksheet in workbook.worksheets:\n'
        '        if worksheet.max_row >= 2:\n'
        '            worksheet.freeze_panes = "A2"\n'
        '            worksheet.auto_filter.ref = worksheet.dimensions\n'
        '        for column_cells in worksheet.columns:\n'
        '            column_letter = get_column_letter(column_cells[0].column)\n'
        '            max_len = max(\n'
        '                len(str(cell.value)) if cell.value is not None else 0\n'
        '                for cell in column_cells\n'
        '            )\n'
        '            worksheet.column_dimensions[column_letter].width = min(max(max_len + 2, 10), 60)\n'
        '    workbook.save(path)\n'
        '\n'
