        '\n'
        'def write_detailed_report_xlsx(path: Path, frames: dict[str, pd.DataFrame]) -> None:\n'
        '    path.parent.mkdir(parents=True, exist_ok=True)\n'
        '    with pd.ExcelWriter(path, engine="openpyxl") as writer:\n'
        '        for sheet_name, df in frames.items():\n'
        '            df.to_excel(writer, index=False, sheet_name=sheet_name[:31])\n'
        '    auto_fit_workbook_columns(path)\n'
        '\n'
        '\n'
        'def stage_live_chain_workspace(output_root: Path, sites: list[str]) -> Path:\n'
        '    workspace_root = output_root / "live_chain_workspace"\n'
        '    if workspace_root.exists():\n'
        '        shutil.rmtree(workspace_root)\n'
        '    copy_tree(packaged_share_root(), workspace_root / "_share")\n'
        '    for site in sites:\n'
        '        copy_tree(output_root / "sites" / site / "output", workspace_root / "data" / site / "out")\n'
        '    return workspace_root\n'
        '\n'
        '\n'
        'def stage_raw_only_chain_workspace(output_root: Path, sites: list[str]) -> Path:\n'
        '    workspace_root = output_root / "raw_only_chain_workspace"\n'
        '    if workspace_root.exists():\n'
        '        shutil.rmtree(workspace_root)\n'
        '    for site in sites:\n'
        '        copy_tree(output_root / "sites" / site / "output", workspace_root / "data" / site / "out")\n'
        '    return workspace_root\n'
        '\n'
        '\n'
        'def run_live_chain(output_root: Path, sites: list[str], baseline_comparison: dict[str, object]) -> dict[str, object]:\n'
        '    support = packaged_live_chain_support()\n'
        '    result_dir = output_root / "result" / "live_chain"\n'
        '    result_dir.mkdir(parents=True, exist_ok=True)\n'
        '    payload: dict[str, object] = {\n'
        '        "requested": True,\n'
        '        "supported": bool(support["supported"]),\n'
        '        "support": support,\n'
        '        "workspace_root": "",\n'
        '        "result_dir": str(result_dir),\n'
        '        "status_ko": "",\n'
        '        "generated_outputs": {},\n'
        '        "fixed_fault_reference_compare": {},\n'
        '        "note_ko": (\n'
        '            "live chain은 package 내부의 bootstrap verdict -> fault_event_audit -> final verdict -> gpvs evidence -> heuristic "\n'
        '            "경로를 workspace-only로 수행한다."\n'
        '        ),\n'
        '    }\n'
        '    if not support["supported"]:\n'
        '        payload["status_ko"] = "packaged live chain assets missing"\n'
        '        return payload\n'
        '    if sorted(sites) != sorted(DEFAULT_SITES):\n'
        '        payload["status_ko"] = "current live chain supports baseline tri-site universe only"\n'
        '        return payload\n'
        '\n'
        '    workspace_root = stage_live_chain_workspace(output_root, sites)\n'
        '    payload["workspace_root"] = str(workspace_root)\n'
        '    commands = [\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_bootstrap_verdict_v1.py")), "--root", str(workspace_root), "--write-panel-verdict-alias"],\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_fault_panel_event_audit_v1.py")), "--root", str(workspace_root)],\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_panel_multiaxis_verdict_v1.py")), "--root", str(workspace_root)],\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_gpvs_evidence_pack_v1.py")), "--root", str(workspace_root)],\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_cause_candidate_heuristics_v1.py")), "--root", str(workspace_root)],\n'
        '    ]\n'
        '    for cmd in commands:\n'
        '        subprocess.run(cmd, cwd=package_root(), check=True)\n'
        '\n'
        '    live_fault_df = build_live_fault_table(workspace_root)\n'
        '    live_preview_df = build_live_fault_preview(workspace_root, live_fault_df)\n'
        '    live_fault_path = result_dir / "fault_panel_result_live_v1.csv"\n'
        '    live_preview_path = result_dir / "fault_panel_result_live_preview_v1.csv"\n'
        '    live_fault_df.to_csv(live_fault_path, index=False, encoding="utf-8-sig")\n'
        '    live_preview_df.to_csv(live_preview_path, index=False, encoding="utf-8-sig")\n'
        '\n'
        '    generated = {\n'
        '        "bootstrap_verdict": str(workspace_root / "_share" / "panel_day_engine_bootstrap_verdict_v1.csv"),\n'
        '        "fault_event_audit": str(workspace_root / "_share" / "panel_day_engine_fault_panel_event_audit_v1.csv"),\n'
        '        "final_verdict": str(workspace_root / "_share" / "panel_day_engine_panel_multiaxis_verdict_v1.csv"),\n'
        '        "gpvs_evidence": str(workspace_root / "_share" / "panel_day_engine_gpvs_evidence_pack_v1.csv"),\n'
        '        "heuristic": str(workspace_root / "_share" / "panel_day_engine_cause_candidate_heuristics_v1.csv"),\n'
        '        "fault_panel_result_live_v1": str(live_fault_path),\n'
        '        "fault_panel_result_live_preview_v1": str(live_preview_path),\n'
        '    }\n'
        '    for name, source in [\n'
        '        ("panel_day_engine_bootstrap_verdict_v1.csv", workspace_root / "_share" / "panel_day_engine_bootstrap_verdict_v1.csv"),\n'
        '        ("panel_day_engine_fault_panel_event_audit_v1.csv", workspace_root / "_share" / "panel_day_engine_fault_panel_event_audit_v1.csv"),\n'
        '        ("panel_day_engine_panel_multiaxis_verdict_v1.csv", workspace_root / "_share" / "panel_day_engine_panel_multiaxis_verdict_v1.csv"),\n'
        '        ("panel_day_engine_gpvs_evidence_pack_v1.csv", workspace_root / "_share" / "panel_day_engine_gpvs_evidence_pack_v1.csv"),\n'
        '        ("panel_day_engine_cause_candidate_heuristics_v1.csv", workspace_root / "_share" / "panel_day_engine_cause_candidate_heuristics_v1.csv"),\n'
        '    ]:\n'
        '        target = result_dir / name\n'
        '        shutil.copy2(source, target)\n'
        '        generated[name] = str(target)\n'
        '\n'
        '    compare = compare_live_fault_to_fixed(live_fault_df)\n'
        '    compare["baseline_input_all_sites_match"] = bool(baseline_comparison.get("all_sites_match", False))\n'
        '    payload["generated_outputs"] = generated\n'
        '    payload["fixed_fault_reference_compare"] = compare\n'
        '    payload["status_ko"] = "completed"\n'
        '    summary_path = result_dir / "live_chain_summary_v1.json"\n'
        '    write_json(summary_path, payload)\n'
        '    payload["summary_path"] = str(summary_path)\n'
        '    payload["published_outputs"] = publish_live_chain_outputs(output_root, result_dir, summary_path)\n'
        '    write_json(summary_path, payload)\n'
        '    root_summary_path = output_root / "result" / ROOT_LIVE_SUMMARY_NAME\n'
        '    shutil.copy2(summary_path, root_summary_path)\n'
        '    payload["published_outputs"][ROOT_LIVE_SUMMARY_NAME] = str(root_summary_path)\n'
        '    root_report_path = output_root / "result" / ROOT_LIVE_REPORT_NAME\n'
        '    write_text(\n'
        '        root_report_path,\n'
        '        build_live_report_markdown(\n'
        '            sites=sites,\n'
        '            baseline_comparison=baseline_comparison,\n'
        '            compare=compare,\n'
        '            published_outputs=payload["published_outputs"],\n'
        '            live_preview_df=live_preview_df,\n'
        '        ),\n'
        '    )\n'
        '    payload["published_outputs"][ROOT_LIVE_REPORT_NAME] = str(root_report_path)\n'
        '    write_json(summary_path, payload)\n'
        '    shutil.copy2(summary_path, root_summary_path)\n'
        '    return payload\n'
        '\n'
        '\n'
        'def run_raw_only_chain(output_root: Path, sites: list[str]) -> dict[str, object]:\n'
        '    support = packaged_raw_only_chain_support()\n'
        '    result_dir = output_root / "result" / "raw_only_chain"\n'
        '    result_dir.mkdir(parents=True, exist_ok=True)\n'
        '    payload: dict[str, object] = {\n'
        '        "requested": True,\n'
        '        "supported": bool(support["supported"]),\n'
        '        "support": support,\n'
        '        "workspace_root": "",\n'
        '        "result_dir": str(result_dir),\n'
        '        "status_ko": "",\n'
        '        "generated_outputs": {},\n'
        '        "fixed_fault_reference_compare": {},\n'
        '        "note_ko": (\n'
        '            "raw-only chain은 panel_day_core와 precursor gate만 사용해 audit -> final verdict -> heuristic를 다시 계산한다. "\n'
        '            "커널로그_원인군_ko는 algorithm-derived family 의미로 해석해야 한다."\n'
        '        ),\n'
        '    }\n'
        '    if not support["supported"]:\n'
        '        payload["status_ko"] = "packaged raw-only chain assets missing"\n'
        '        return payload\n'
        '\n'
        '    workspace_root = stage_raw_only_chain_workspace(output_root, sites)\n'
        '    payload["workspace_root"] = str(workspace_root)\n'
        '    commands = [\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_runtime_fault_event_audit_v1.py")), "--root", str(workspace_root)],\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_runtime_final_verdict_v1.py")), "--root", str(workspace_root)],\n'
        '        [sys.executable, str(packaged_script_path("build_panel_day_engine_runtime_heuristic_v1.py")), "--root", str(workspace_root)],\n'
        '    ]\n'
        '    for cmd in commands:\n'
        '        subprocess.run(cmd, cwd=package_root(), check=True)\n'
        '\n'
        '    raw_only_common = load_raw_only_common_module()\n'
        '    raw_only_fault_df = raw_only_common.build_fault_table_from_outputs(\n'
        '        workspace_root=workspace_root,\n'
        '        verdict_name=raw_only_common.RUNTIME_VERDICT_OUTPUT_NAME,\n'
        '        heuristic_name=raw_only_common.RUNTIME_HEURISTIC_OUTPUT_NAME,\n'
        '    )\n'
        '    raw_only_preview_df = raw_only_common.build_fault_preview(workspace_root, raw_only_fault_df)\n'
        '    raw_only_fault_path = result_dir / "fault_panel_result_raw_only_v1.csv"\n'
        '    raw_only_preview_path = result_dir / "fault_panel_result_raw_only_preview_v1.csv"\n'
        '    raw_only_fault_df.to_csv(raw_only_fault_path, index=False, encoding="utf-8-sig")\n'
        '    raw_only_preview_df.to_csv(raw_only_preview_path, index=False, encoding="utf-8-sig")\n'
        '\n'
        '    generated = {\n'
        '        "runtime_audit": str(workspace_root / "_share" / raw_only_common.RUNTIME_AUDIT_OUTPUT_NAME),\n'
        '        "runtime_verdict": str(workspace_root / "_share" / raw_only_common.RUNTIME_VERDICT_OUTPUT_NAME),\n'
        '        "runtime_heuristic": str(workspace_root / "_share" / raw_only_common.RUNTIME_HEURISTIC_OUTPUT_NAME),\n'
        '        "fault_panel_result_raw_only_v1": str(raw_only_fault_path),\n'
        '        "fault_panel_result_raw_only_preview_v1": str(raw_only_preview_path),\n'
        '    }\n'
        '    for name, source in [\n'
        '        (raw_only_common.RUNTIME_AUDIT_OUTPUT_NAME, workspace_root / "_share" / raw_only_common.RUNTIME_AUDIT_OUTPUT_NAME),\n'
        '        (raw_only_common.RUNTIME_VERDICT_OUTPUT_NAME, workspace_root / "_share" / raw_only_common.RUNTIME_VERDICT_OUTPUT_NAME),\n'
        '        (raw_only_common.RUNTIME_HEURISTIC_OUTPUT_NAME, workspace_root / "_share" / raw_only_common.RUNTIME_HEURISTIC_OUTPUT_NAME),\n'
        '    ]:\n'
        '        target = result_dir / name\n'
        '        shutil.copy2(source, target)\n'
        '        generated[name] = str(target)\n'
        '\n'
        '    compare = raw_only_common.compare_fault_table_to_reference(raw_only_fault_df, fixed_fault6_table_path())\n'
        '    payload["generated_outputs"] = generated\n'
        '    payload["fixed_fault_reference_compare"] = compare\n'
        '    payload["status_ko"] = "completed"\n'
        '    summary_path = result_dir / "raw_only_chain_summary_v1.json"\n'
        '    write_json(summary_path, payload)\n'
        '    payload["summary_path"] = str(summary_path)\n'
        '    return payload\n'
        '\n'
        '\n'
        'def build_shadow_compare_report(\n'
        '    output_root: Path,\n'
        '    site_plans: list[dict[str, object]],\n'
        '    baseline_comparison: dict[str, object],\n'
        ') -> dict[str, object]:\n'
        '    reference = load_core_baseline_digest()\n'
        '    report: dict[str, object] = {\n'
        '        "generated_at_utc": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),\n'
        '        "reference_path": str(baseline_core_digest_path()),\n'
        '        "note_ko": (\n'
        '            "이 shadow compare는 동일 baseline raw corpus로 runtime pack을 다시 실행했을 때 "\n'
        '            "panel_day_core.csv가 reference digest와 같은지 점검한다. "\n'
        '            "현재는 full-chain verdict/evidence/heuristic live compare가 아니라 engine core compare만 수행한다."\n'
        '        ),\n'
        '        "sites": {},\n'
        '        "compared_site_count": 0,\n'
        '        "matched_site_count": 0,\n'
        '        "all_compared_sites_match": True,\n'
        '    }\n'
        '    reference_sites = reference.get("sites", {})\n'
        '\n'
        '    for plan in site_plans:\n'
        '        site = str(plan["site"])\n'
        '        site_entry: dict[str, object] = {\n'
        '            "baseline_input_match": bool(baseline_comparison["sites"].get(site, {}).get("match", False)),\n'
        '            "compared": False,\n'
        '            "match": None,\n'
        '            "skipped_reason": "",\n'
        '            "expected": {},\n'
        '            "actual": {},\n'
        '            "diffs": [],\n'
        '        }\n'
        '        expected = reference_sites.get(site)\n'
        '        if not expected:\n'
        '            site_entry["skipped_reason"] = "missing_packaged_reference_digest"\n'
        '            report["sites"][site] = site_entry\n'
        '            continue\n'
        '        if not site_entry["baseline_input_match"]:\n'
        '            site_entry["skipped_reason"] = "input_manifest_mismatch"\n'
        '            site_entry["expected"] = expected\n'
        '            report["sites"][site] = site_entry\n'
        '            continue\n'
        '\n'
        '        core_path = output_root / "sites" / site / "output" / "panel_day_core.csv"\n'
        '        if not core_path.exists():\n'
        '            site_entry["skipped_reason"] = "missing_generated_panel_day_core"\n'
        '            site_entry["expected"] = expected\n'
        '            report["sites"][site] = site_entry\n'
        '            continue\n'
        '\n'
        '        actual_df = pd.read_csv(core_path, low_memory=False)\n'
        '        actual_digest = build_core_digest_payload(actual_df, core_path.name)\n'
        '        diffs = compare_single_site_digest(expected, actual_digest)\n'
        '        site_entry.update(\n'
        '            {\n'
        '                "compared": True,\n'
        '                "match": not diffs,\n'
        '                "expected": expected,\n'
        '                "actual": actual_digest,\n'
        '                "diffs": diffs,\n'
        '            }\n'
        '        )\n'
        '        report["sites"][site] = site_entry\n'
        '        report["compared_site_count"] += 1\n'
        '        if not diffs:\n'
        '            report["matched_site_count"] += 1\n'
        '        else:\n'
        '            report["all_compared_sites_match"] = False\n'
        '\n'
        '    if report["compared_site_count"] == 0:\n'
        '        report["all_compared_sites_match"] = False\n'
        '    return report\n'
        '\n'
        '\n'
        'def main() -> None:\n'
        '    args = parse_args()\n'
        '    if not engine_path().exists():\n'
        '        raise SystemExit(f"missing packaged engine: {engine_path()}")\n'
        '\n'
        '    emit_progress(1, "실행 준비를 시작합니다.")\n'
        '    data_root = args.data_root.expanduser().resolve()\n'
        '    output_root = args.output_root.expanduser().resolve()\n'
        '    output_root.mkdir(parents=True, exist_ok=True)\n'
        '    reuse_existing_site_outs_root = (\n'
        '        args.reuse_existing_site_outs_root.expanduser().resolve()\n'
        '        if args.reuse_existing_site_outs_root is not None\n'
        '        else None\n'
        '    )\n'
        '\n'
        '    sites = normalize_sites(args.sites)\n'
        '    effective_reuse_existing_site_outs_root, reuse_decision, reuse_freshness = resolve_reuse_existing_site_outs_root(\n'
        '        data_root=data_root,\n'
        '        explicit_reuse_root=reuse_existing_site_outs_root,\n'
        '        prefer_existing_site_outs=args.prefer_existing_site_outs,\n'
        '        sites=sites,\n'
        '    )\n'
        '    site_plans: list[dict[str, object]] = []\n'
        '    commands: list[list[str]] = []\n'
        '    for site in sites:\n'
        '        plan, cmd = build_site_plan(args, site)\n'
        '        site_plans.append(plan)\n'
        '        commands.append(cmd)\n'
        '\n'
        '    emit_progress(8, "입력 CSV 구조와 실행 계획을 점검했습니다.")\n'
        '    fixed_outputs = copy_fixed_results(output_root)\n'
        '    baseline_comparison = compare_to_baseline(site_plans)\n'
        '    live_chain_support = packaged_live_chain_support()\n'
        '    raw_only_chain_support = packaged_raw_only_chain_support()\n'
        '    live_chain_plan = {\n'
        '        "requested": args.run_live_chain == "on",\n'
        '        "supported": bool(live_chain_support["supported"]),\n'
        '        "support": live_chain_support,\n'
        '        "status_ko": "",\n'
        '    }\n'
        '    if not live_chain_plan["requested"]:\n'
        '        live_chain_plan["status_ko"] = "disabled by option"\n'
        '    elif sorted(sites) != sorted(DEFAULT_SITES):\n'
        '        live_chain_plan["status_ko"] = "current live chain supports baseline tri-site universe only"\n'
        '    elif not live_chain_plan["supported"]:\n'
        '        live_chain_plan["status_ko"] = "packaged live chain assets missing"\n'
        '    else:\n'
        '        live_chain_plan["status_ko"] = (\n'
        '            "will run after precomputed out reuse"\n'
        '            if effective_reuse_existing_site_outs_root is not None\n'
        '            else "will run after engine execution"\n'
        '        )\n'
        '    raw_only_chain_plan = {\n'
        '        "requested": args.run_raw_only_chain == "on",\n'
        '        "supported": bool(raw_only_chain_support["supported"]),\n'
        '        "support": raw_only_chain_support,\n'
        '        "status_ko": "",\n'
        '    }\n'
        '    if not raw_only_chain_plan["requested"]:\n'
        '        raw_only_chain_plan["status_ko"] = "disabled by option"\n'
        '    elif not raw_only_chain_plan["supported"]:\n'
        '        raw_only_chain_plan["status_ko"] = "packaged raw-only chain assets missing"\n'
        '    else:\n'
        '        raw_only_chain_plan["status_ko"] = (\n'
        '            "will run after precomputed out reuse"\n'
        '            if effective_reuse_existing_site_outs_root is not None\n'
        '            else "will run after engine execution"\n'
        '        )\n'
        '\n'
        '    plan = {\n'
        '        "generated_at_utc": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),\n'
        '        "package_root": str(package_root()),\n'
        '        "engine_path": str(engine_path()),\n'
        '        "data_root": str(data_root),\n'
        '        "output_root": str(output_root),\n'
        '        "reuse_existing_site_outs_root": str(reuse_existing_site_outs_root) if reuse_existing_site_outs_root else "",\n'
        '        "effective_reuse_existing_site_outs_root": (\n'
        '            str(effective_reuse_existing_site_outs_root)\n'
        '            if effective_reuse_existing_site_outs_root\n'
        '            else ""\n'
        '        ),\n'
        '        "prefer_existing_site_outs": args.prefer_existing_site_outs,\n'
        '        "reuse_decision_ko": reuse_decision,\n'
        '        "reuse_freshness": reuse_freshness,\n'
        '        "execution_mode_ko": (\n'
        '            "auto_reuse_existing_site_outs"\n'
        '            if effective_reuse_existing_site_outs_root is not None and reuse_decision == "auto_fresh"\n'
        '            else "reuse_precomputed_site_outs"\n'
        '            if effective_reuse_existing_site_outs_root is not None\n'
        '            else "run_engine_then_live_chain"\n'
        '        ),\n'
        '        "sites": sites,\n'
        '        "site_plans": site_plans,\n'
        '        "fixed_outputs": fixed_outputs,\n'
        '        "baseline_comparison": baseline_comparison,\n'
        '        "live_chain": live_chain_plan,\n'
        '        "raw_only_chain": raw_only_chain_plan,\n'
        '        "workspace_retention": args.workspace_retention,\n'
        '        "shadow_compare_reference_path": str(baseline_core_digest_path()),\n'
        '        "fault6_provenance_path": str(fault6_provenance_path()),\n'
        '        "dependency_audit_json_path": str(dependency_audit_json_path()),\n'
        '        "dependency_audit_md_path": str(dependency_audit_md_path()),\n'
        '        "shadow_compare_report_path": str(output_root / "shadow_compare_v1.json"),\n'
        '        "workspace_cleanup_report_path": str(output_root / "workspace_cleanup_v1.json"),\n'
        '        "dry_run": bool(args.dry_run),\n'
        '        "note_ko": (\n'
        '            "이 pack은 conalog/gangui/ktc_ess baseline sites에 대해 실제 panel_day_engine.py 를 실행하고, "\n'
        '            "현재 frozen fault 결과표도 함께 export 한다. "\n'
        '            "fault6 결과표 provenance도 함께 남겨, 이 표가 frozen verdict+heuristic direct assembly인지 확인할 수 있다. "\n'
        '            "추가로 baseline core output shadow compare 경로를 남겨, same baseline 입력일 때 engine core output이 유지되는지도 점검한다. "\n'
        '            "workspace_retention=result-only를 사용하면 재생성 가능한 대용량 site/workspace data copy를 실행 후 제거한다."\n'
        '        ),\n'
        '    }\n'
        '\n'
        '    if args.dry_run:\n'
        '        write_json(output_root / "run_plan_v1.json", plan)\n'
        '        emit_progress(100, "dry-run 계획 파일 생성을 완료했습니다.")\n'
        '        print(f"[OK] dry-run plan written: {output_root / \'run_plan_v1.json\'}")\n'
        '        return\n'
        '\n'
        '    reused_site_outs: dict[str, str] = {}\n'
        '    if effective_reuse_existing_site_outs_root is not None:\n'
        '        emit_progress(15, "기존 site out 산출물을 재사용합니다.")\n'
        '        reused_site_outs = copy_existing_site_outs(effective_reuse_existing_site_outs_root, output_root, sites)\n'
        '    else:\n'
        '        site_count = max(1, len(commands))\n'
        '        for idx, cmd in enumerate(commands, start=1):\n'
        '            site_name = str(site_plans[idx - 1]["site"])\n'
        '            start_pct = 15 + int((idx - 1) * 45 / site_count)\n'
        '            done_pct = 15 + int(idx * 45 / site_count)\n'
        '            emit_progress(start_pct, f"메인 엔진 실행 시작: {site_name}")\n'
        '            subprocess.run(cmd, check=True)\n'
        '            emit_progress(done_pct, f"메인 엔진 실행 완료: {site_name}")\n'
        '\n'
        '    emit_progress(65, "engine core 결과를 shadow compare 기준으로 점검합니다.")\n'
        '    shadow_compare = build_shadow_compare_report(output_root, site_plans, baseline_comparison)\n'
        '    write_json(output_root / "shadow_compare_v1.json", shadow_compare)\n'
        '    live_chain_result = {"requested": False, "status_ko": "not requested"}\n'
        '    if args.run_live_chain == "on":\n'
        '        emit_progress(75, "live chain 결과표를 생성합니다.")\n'
        '        live_chain_result = run_live_chain(output_root, sites, baseline_comparison)\n'
        '    raw_only_chain_result = {"requested": False, "status_ko": "not requested"}\n'
        '    if args.run_raw_only_chain == "on":\n'
        '        emit_progress(88, "raw-only candidate chain 결과를 생성합니다.")\n'
        '        raw_only_chain_result = run_raw_only_chain(output_root, sites)\n'
        '\n'
