        '                return df_run.merge(ctx, on="panel_id", how="left")\n'
        '\n'
        '            rep_confirm_ctx = _attach_ctx(rep_confirm, "critical_like")\n'
        '            rep_suspect_ctx = _attach_ctx(rep_suspect, "critical_like_suspect")\n'
        '\n'
        '            ok_critical_reports = True\n'
        '            ok_critical_reports &= _safe_report_write(\n'
        '                rep_confirm_ctx,\n'
        '                log_dir / "report_critical_confirmed_runs.csv",\n'
