        '            ok_critical_reports &= _safe_report_write(\n'
        '                rep_suspect_ctx,\n'
        '                out_dir / "report_critical_suspect_runs.csv",\n'
        '                "report_critical_suspect_runs(out)",\n'
        '                index=False,\n'
        '            )\n'
        '            if ok_critical_reports:\n'
        '                print("[OK] wrote reports: report_critical_confirmed_runs.csv / report_critical_suspect_runs.csv")\n'
        '\n'
        '            print("\\n[TOP] critical_like confirmed max_run (TOP40)")\n'
        '            print(rep_confirm.head(40).to_string(index=False))\n'
        '            print("\\n[TOP] critical_like SUSPECT max_run (TOP40)")\n'
        '            print(rep_suspect.head(40).to_string(index=False))\n'
        '    except Exception as _e:\n'
        '        print(f"[WARN] critical report generation failed: {_e}")\n'
        '\n'
        '    # helper flags for daily fault-like events and degraded candidates\n'
        '    fault_sustain = 90            # minutes of sustained low ratio to consider the day fault-like\n'
        '    fault_last_ratio_thr = 0.10   # if last_ratio <= 0.1, treated as nearly dead at end of day\n'
        '    degraded_upper = 0.60         # upper bound for degraded mid_ratio (0.2 ~ 0.6)\n'
        '\n'
        '    out["fault_like_day"] = (\n'
        '        (~out["data_bad"])\n'
        '        & out["event_A"]\n'
        '        & (out["sustain_mins"] >= fault_sustain)\n'
        '        & (out["last_ratio"] <= fault_last_ratio_thr)\n'
        '        & (out["mid_peer"] >= float(args.mid_peer_alive_thr))\n'
        '    )\n'
        '\n'
        '    out["degraded_candidate"] = (\n'
        '        (~out["data_bad"])\n'
        '        & (~out["state_dead"])\n'
        '        & (out["mid_peer"] >= float(args.mid_peer_alive_thr))\n'
        '        & (out["mid_ratio"] > float(args.mid_ratio_dead_thr))\n'
        '        & (out["mid_ratio"] <= degraded_upper)\n'
        '    )\n'
        '\n'
        '    # shadow-like events (basic): degraded days that recovered at least once\n'
        '    # NOTE: refined later using HS/DTW strengths to better match transient cloud/shading behaviour.\n'
        '    out["shadow_like_basic"] = (\n'
        '        (~out["data_bad"])\n'
        '        & out["degraded_candidate"]\n'
        '        & out["recovered_sustained"]\n'
        '    )\n'
        '\n'
        '    # Refined shadow-like: require spatial concurrence OR segmented behaviour, and avoid near-dead patterns\n'
        '    out["shadow_like"] = (\n'
        '        out["shadow_like_basic"]\n'
        '        & (\n'
        '            (out["co_drop_frac"].fillna(0.0) >= float(args.shadow_co_drop_thr))\n'
        '            | (out["seg_count"].fillna(0).astype(int) >= int(args.shadow_seg_min))\n'
        '        )\n'
        '        & (out["min_ratio"].fillna(1.0) >= float(args.shadow_min_ratio_floor))\n'
        '    )\n'
        '\n'
        '    # Guard: group/string OFF events should not contaminate other event categories\n'
        '    if "group_off_like" in out.columns:\n'
        '        mask_go = out["group_off_like"].fillna(False).astype(bool)\n'
        '        if mask_go.any():\n'
        '            for col in ["fault_like_day", "degraded_candidate", "shadow_like_basic", "shadow_like"]:\n'
        '                if col in out.columns:\n'
        '                    out.loc[mask_go, col] = False\n'
        '\n'
        '    # textual anomaly level for easier downstream use\n'
        '    out["anom_level"] = "normal"\n'
        '    out.loc[out["degraded_candidate"], "anom_level"] = "degraded_or_shadow"\n'
        '    out.loc[out["shadow_like"], "anom_level"] = "shadow_like"\n'
        '    out.loc[out["fault_like_day"], "anom_level"] = "fault_like"\n'
        '    out.loc[out["group_off_like"], "anom_level"] = "group_off_like"\n'
        '    out.loc[out["final_fault"], "anom_level"] = "confirmed_fault"\n'
        '\n'
        '    # Layer 2: AE 기반 강도 / 서브타입 태깅\n'
        '    # 날짜별 AE 재구성오차 분위수 (0~1)\n'
        '    out["recon_rank_day"] = out.groupby("date")["recon_error"].rank(pct=True)\n'
        '\n'
        '    # AE 강도 수준\n'
        '    out["ae_strength"] = "low"\n'
        '    out.loc[out["recon_rank_day"] >= 0.7, "ae_strength"] = "mid"\n'
        '    out.loc[out["recon_rank_day"] >= 0.9, "ae_strength"] = "high"\n'
        '    # is_ae_strong=True인 경우는 무조건 high로 승격\n'
        '    out.loc[out["is_ae_strong"], "ae_strength"] = "high"\n'
        '\n'
        '    # 이상 서브타입 태그\n'
        '    out["anom_subtype"] = "normal"\n'
        '    out.loc[out["group_off_like"], "anom_subtype"] = "group_off_event"\n'
        '\n'
        '    # shadow-like: 음영/날씨성 이벤트를 AE 강도 기준으로 세분화\n'
        '    out.loc[out["shadow_like"] & (~out["is_ae_strong"]), "anom_subtype"] = "shadow_like_mild"\n'
        '    out.loc[out["shadow_like"] & out["is_ae_strong"], "anom_subtype"] = "shadow_like_strong"\n'
        '\n'
        '    # 열화 후보: shadow_like로 이미 태깅된 패널은 제외하고, AE 강도로 구분\n'
        '    out.loc[\n'
        '        out["degraded_candidate"] & (~out["shadow_like"]) & (~out["is_ae_strong"]),\n'
        '        "anom_subtype",\n'
        '    ] = "degradation_mild"\n'
        '    out.loc[\n'
        '        out["degraded_candidate"] & (~out["shadow_like"]) & out["is_ae_strong"],\n'
        '        "anom_subtype",\n'
        '    ] = "degradation_strong"\n'
        '\n'
        '    # 하루 고장 패턴: fault-like day\n'
        '    out.loc[\n'
        '        out["fault_like_day"] & (~out["is_ae_strong"]),\n'
        '        "anom_subtype",\n'
        '    ] = "fault_like_weak"\n'
        '    out.loc[\n'
        '        out["fault_like_day"] & out["is_ae_strong"],\n'
        '        "anom_subtype",\n'
        '    ] = "fault_like_strong"\n'
        '\n'
        '    # 최종 confirmed fault는 항상 confirmed_fault로 override\n'
        '    out.loc[out["confirmed_fault"], "anom_subtype"] = "confirmed_fault"\n'
        '    out.loc[(out["critical_fault"]) & (~out["confirmed_fault"]), "anom_subtype"] = "critical_fault_vdrop"\n'
        '\n'
        '    # Layer 3: EWS(전조) 지표 – 4종 (mid_var, eventA_freq, dtw_mean, hs_mean)\n'
        '    # 패널별 날짜 순으로 정렬 후 롤링 통계 계산\n'
        '    out = out.sort_values(["panel_id", "date"])\n'
        '    grp = out.groupby("panel_id", group_keys=False)\n'
        '\n'
        '    # 1) 기본 롤링 지표 4개\n'
        '    out["ews_mid_var_7d"] = grp["mid_ratio"].transform(\n'
        '        lambda s: s.rolling(window=7, min_periods=3).var()\n'
        '    )\n'
        '    out["ews_eventA_freq_7d"] = grp["event_A"].transform(\n'
        '        lambda s: s.rolling(window=7, min_periods=3).mean()\n'
        '    )\n'
        '    out["ews_dtw_mean_7d"] = grp["dtw_dist"].transform(\n'
        '        lambda s: s.rolling(window=7, min_periods=3).mean()\n'
        '    )\n'
        '    out["ews_hs_mean_7d"] = grp["hs_score"].transform(\n'
        '        lambda s: s.rolling(window=7, min_periods=3).mean()\n'
        '    )\n'
        '\n'
        '    # 2) 운영(인과성) 관점: 전역 임계값과 월별 베이스라인은 "과거 데이터"로만 산정\n'
        '    #    - 날짜 d에서의 판단은 date < d 구간의 분포/베이스라인만 사용 (미래 데이터 누수 방지)\n'
        '\n'
        '    # ==== EXPORT: Save main output CSV with n_total defensively included ====\n'
        '    # Ensure n_total is exported for ops/debug (number of panels per (date, group_key))\n'
        '    if "n_total" not in out.columns:\n'
        '        out["n_total"] = out.groupby(["date", "group_key"])["panel_id"].transform("nunique").astype(float)\n'
        '\n'
        '    # Define output columns (OUT_COLS): insert n_total after n_ref if present, else near v_ref-related cols\n'
        '    OUT_COLS = [\n'
        '        "date", "panel_id",\n'
        '        "recon_error", "ae_thr_used",\n'
        '        "drop_time", "sustain_mins", "recovered",\n'
        '        "last_ratio", "last_peer",\n'
        '        "mid_ratio", "mid_peer", "mid_v_ratio", "mid_i_ratio",\n'
        '        "coverage", "co_drop_frac",\n'
        '        "is_ae_abn", "is_ae_strong", "source_csv",\n'
        '        "dtw_dist", "hs_score", "recovered_any", "recovered_sustained", "re_drop",\n'
        '        "coverage_mid", "seg_count", "total_low_mins", "min_ratio", "p10_ratio", "p50_ratio", "low_area",\n'
        '        "event_A", "data_bad",\n'
        '        "group_key_base", "vbin", "group_key",\n'
        '        "v_ref", "v_ref_span", "v_ref_ok", "n_ref",  # v_ref-related section\n'
        '        # n_total will be inserted after n_ref or after v_ref-related cols below\n'
        '        "no_ref", "v_drop",\n'
        '        "state_dead", "state_dead_eff", "dead_streak", "confirmed_fault",\n'
        '        "dead_diag_on_day", "dead_diag_date",\n'
        '        "critical_like", "critical_like_eff", "crit_streak", "critical_fault", "critical_source",\n'
        '        "critical_diag_on_day", "critical_diag_date", "diagnosis_date_online",\n'
        '        "critical_confirmed", "critical_suspect", "final_fault",\n'
        '        "group_off_date", "group_off_like", "group_off_group",\n'
        '        "base_day_panel_count", "base_day_degraded_panel_count", "subgroup_common_cause_candidate",\n'
        '        "fault_like_day", "degraded_candidate", "shadow_like_basic", "shadow_like",\n'
        '        "anom_level", "recon_rank_day", "ae_strength", "anom_subtype",\n'
        '        "ews_mid_var_7d", "ews_eventA_freq_7d", "ews_dtw_mean_7d", "ews_hs_mean_7d"\n'
        '    ]\n'
        '    # Insert n_total after n_ref if present, else after v_ref_ok, v_ref_span, or v_ref\n'
        '    if "n_total" not in OUT_COLS:\n'
        '        try:\n'
        '            idx = OUT_COLS.index("n_ref") + 1\n'
        '        except ValueError:\n'
        '            # Try after v_ref_ok or v_ref_span or v_ref\n'
        '            for key in ["v_ref_ok", "v_ref_span", "v_ref"]:\n'
        '                if key in OUT_COLS:\n'
        '                    idx = OUT_COLS.index(key) + 1\n'
        '                    break\n'
        '            else:\n'
        '                idx = len(OUT_COLS)\n'
        '        OUT_COLS.insert(idx, "n_total")\n'
        '\n'
        '    # Final save is performed once at the end of main().\n'
        '\n'
        '    out = _compute_ews(out, args)\n'
        '    out = _compute_site_events(out)\n'
        '\n'
        '    # Gate: site event day should not produce EWS/prefault escalation.\n'
        '    out.loc[out["site_event_soft"], "ews_warning"] = False\n'
        '    out.loc[out["site_event_hard"], "ews_warning"] = False\n'
        '    # Gate: group/string-level OFF events should not escalate into EWS/prefault\n'
        '    out.loc[out["group_off_date"].astype(bool), "ews_warning"] = False\n'
        '\n'
        '    # ---- DTW/HS ranking and subtype refinement ----\n'
        '    # 1) Add daily DTW and HS ranks\n'
        '    out["dtw_rank_day"] = out.groupby("date")["dtw_dist"].rank(pct=True)\n'
        '    out["hs_rank_day"] = out.groupby("date")["hs_score"].rank(pct=True)\n'
        '\n'
        '    # 2) Add categorical strengths\n'
        '    out["dtw_strength"] = "low"\n'
        '    out.loc[out["dtw_rank_day"] >= 0.7, "dtw_strength"] = "mid"\n'
        '    out.loc[out["dtw_rank_day"] >= 0.9, "dtw_strength"] = "high"\n'
        '    out["hs_strength"] = "low"\n'
        '    out.loc[out["hs_rank_day"] >= 0.7, "hs_strength"] = "mid"\n'
        '    out.loc[out["hs_rank_day"] >= 0.9, "hs_strength"] = "high"\n'
        '\n'
        '    # Refine shadow-like using HS/DTW strengths to better capture transient cloud/shading\n'
        '    # - require turbulence (HS mid/high)\n'
        '    # - avoid cases where the panel is strongly off its own reference (DTW high)\n'
        '    # - require spatial concurrence (co_drop_frac >= co_drop_thr)\n'
        '    out["shadow_like"] = (\n'
        '        out["shadow_like_basic"].astype(bool)\n'
        '        & out["hs_strength"].isin(["mid", "high"])\n'
        '        & (~out["dtw_strength"].isin(["high"]))\n'
        '        & (out["co_drop_frac"].fillna(0.0) >= float(args.shadow_co_drop_thr))\n'
        '    )\n'
        '\n'
        '    # Update anom_level after refining shadow_like\n'
        '    # (keep confirmed_fault highest priority)\n'
        '    out.loc[out["shadow_like"], "anom_level"] = "shadow_like"\n'
        '    out.loc[out["shadow_like_basic"] & (~out["shadow_like"]), "anom_level"] = "degraded_or_shadow"\n'
        '    out.loc[out["final_fault"], "anom_level"] = "confirmed_fault"\n'
        '\n'
        '    # 3) Refine anom_subtype using DTW/HS\n'
        '    # For shadow-like days\n'
        '    out.loc[out["shadow_like"] & (out["hs_strength"] != "high"), "anom_subtype"] = "shadow_like_mild"\n'
        '    out.loc[\n'
        '        out["shadow_like"] & (out["hs_strength"] == "high") & (out["dtw_strength"].isin(["mid", "high"])),\n'
        '        "anom_subtype"\n'
        '    ] = "shadow_like_strong"\n'
        '\n'
        '    # For degraded candidates (excluding shadow_like and confirmed faults)\n'
        '    mask_deg = out["degraded_candidate"] & (~out["shadow_like"]) & (~out["final_fault"])\n'
        '    out.loc[\n'
        '        mask_deg & (out["hs_strength"] == "low") & (out["dtw_strength"].isin(["low", "mid"])),\n'
        '        "anom_subtype"\n'
        '    ] = "degradation_steady"\n'
        '    out.loc[\n'
        '        mask_deg & (out["dtw_strength"] == "high"),\n'
        '        "anom_subtype"\n'
        '    ] = "degradation_strong"\n'
        '\n'
        '    # For fault-like days not yet final_fault\n'
        '    mask_fault_like = out["fault_like_day"] & (~out["final_fault"])\n'
        '\n'
        '    # 기본값은 fault_like_weak으로 태깅\n'
        '    out.loc[mask_fault_like, "anom_subtype"] = "fault_like_weak"\n'
        '\n'
        '    # DTW가 강하게 틀어지고, HS 난류가 너무 높지 않은 경우를 strong으로 승격\n'
        '    out.loc[\n'
        '        mask_fault_like\n'
        '        & (out["dtw_strength"] == "high")\n'
        '        & (out["hs_strength"].isin(["low", "mid"])),\n'
        '        "anom_subtype"\n'
        '    ] = "fault_like_strong"\n'
        '\n'
        '    # 4) Confirmed faults always override\n'
        '    out.loc[out["final_fault"], "anom_subtype"] = "confirmed_fault"\n'
        '\n'
        '    # 최종 저장 전에는 다시 날짜+패널 기준 정렬\n'
        '    out = out.sort_values(["date", "panel_id"])\n'
        '\n'
        '    # ===== Layer 4: 1.1-style pre-fault template engine (Option B, 엔진 1.0) =====\n'
        '    # 최근 40일 기준으로 패널별 요약 지표를 만들고,\n'
        '    # 1.1 패널에서 관찰된 패턴과 비슷한 경우를 "전조 후보"로 본다.\n'
        '\n'
        '    # 패널-날짜 순으로 한 번 더 정렬하고 그룹 생성\n'
        '    out = out.sort_values(["panel_id", "date"])\n'
        '    grp_pf = out.groupby("panel_id", group_keys=False)\n'
        '\n'
        '    # AE/DTW/HS mid 이상 여부를 0/1 플래그로 변환\n'
        '    out["ae_mid_flag"] = out["ae_strength"].isin(["mid", "high"]).astype(float)\n'
        '    out["dtw_mid_flag"] = out["dtw_strength"].isin(["mid", "high"]).astype(float)\n'
        '\n'
        '    # 최근 40일 롤링 윈도우 (일 데이터 기준), 최소 20일 이상 관측이 있을 때만 유효\n'
        '    window = 40\n'
        '    min_periods = 20\n'
        '\n'
        '    out["pf40_mid_mean"] = grp_pf["mid_ratio"].transform(\n'
        '        lambda s: s.rolling(window=window, min_periods=min_periods).mean()\n'
        '    )\n'
        '    out["pf40_ae_ratio"] = grp_pf["ae_mid_flag"].transform(\n'
        '        lambda s: s.rolling(window=window, min_periods=min_periods).mean()\n'
        '    )\n'
        '    out["pf40_dtw_ratio"] = grp_pf["dtw_mid_flag"].transform(\n'
        '        lambda s: s.rolling(window=window, min_periods=min_periods).mean()\n'
        '    )\n'
        '    out["pf40_ews_ratio"] = grp_pf["ews_warning"].transform(\n'
        '        lambda s: s.rolling(window=window, min_periods=min_periods).mean()\n'
        '    )\n'
        '\n'
        '    # Option B 템플릿 임계값 (1.1 pre-fault 윈도우를 기준으로 잡은 보수적 구간)\n'
        '    mid_low = 0.5      # 평균 mid_ratio가 너무 낮지도(완전 dead) 너무 높지도(완전 정상) 않은 구간\n'
        '    mid_high = 0.9\n'
        '    pf_ae_ratio_thr = 0.7    # 최근 40일 중 AE mid/high 비율\n'
        '    pf_dtw_ratio_thr = 0.7   # 최근 40일 중 DTW mid/high 비율\n'
        '    pf_ews_ratio_thr = 0.05  # 최근 40일 중 EWS_warning 비율 (대략 40일 중 2일 이상)\n'
        '\n'
        '    cond_mid = (out["pf40_mid_mean"] >= mid_low) & (out["pf40_mid_mean"] <= mid_high)\n'
        '    cond_ae = out["pf40_ae_ratio"] >= pf_ae_ratio_thr\n'
        '    cond_dtw = out["pf40_dtw_ratio"] >= pf_dtw_ratio_thr\n'
        '    cond_ews = out["pf40_ews_ratio"] >= pf_ews_ratio_thr\n'
        '    out["prefault_cond_mid"] = cond_mid.astype(bool)\n'
        '    out["prefault_cond_ae"] = cond_ae.astype(bool)\n'
        '    out["prefault_cond_dtw"] = cond_dtw.astype(bool)\n'
        '    out["prefault_cond_ews"] = cond_ews.astype(bool)\n'
        '\n'
        '    # 실제 전조 엔진 플래그 (b안):\n'
        '    # - 데이터 품질이 나쁘지 않고(data_bad=False)\n'
        '    # - 아직 최종 고장(final_fault)이 아닌 상태에서\n'
        '    # - 위 네 조건을 동시에 만족하면 해당 날짜-패널을 "전조 후보"로 표시\n'
        '    out["prefault_B"] = (\n'
        '        (~out["data_bad"]) & (~out["final_fault"]) &\n'
        '        out["prefault_cond_mid"] & out["prefault_cond_ae"] & out["prefault_cond_dtw"] & out["prefault_cond_ews"]\n'
        '    )\n'
        '    out["base_day_panel_count"] = (\n'
        '        out.groupby(["date", "group_key_base"])["panel_id"].transform("nunique").fillna(0).astype(int)\n'
        '    )\n'
        '    out["base_day_degraded_panel_count"] = (\n'
        '        out.groupby(["date", "group_key_base"])["degraded_candidate"]\n'
