        '    out["subgroup_common_cause_candidate"] = (\n'
        '        out["degraded_candidate"].astype(bool)\n'
        '        & (~out["site_event_soft"].astype(bool))\n'
        '        & (~out["site_event_hard"].astype(bool))\n'
        '        & (~out["group_off_date"].astype(bool))\n'
        '        & (~out["group_off_like"].astype(bool))\n'
        '        & out["base_day_degraded_panel_count"].ge(3)\n'
        '    )\n'
        '    prefault_common_cause_overlap = (\n'
        '        out["prefault_B"].astype(bool)\n'
        '        & (\n'
        '            out["site_event_soft"].astype(bool)\n'
        '            | out["site_event_hard"].astype(bool)\n'
        '            | out["group_off_date"].astype(bool)\n'
        '            | out["group_off_like"].astype(bool)\n'
        '        )\n'
