        '    out["prefault_B_common_cause_overlap"] = prefault_common_cause_overlap\n'
        '    out["prefault_B_effective"] = out["prefault_B"].astype(bool) & (~prefault_common_cause_overlap)\n'
        '\n'
        '    # ===== Helper reports: daily summaries & candidate lists =====\n'
        '    # 1) 날짜별 anom_level 요약 테이블\n'
