        '\n'
        '    # 6) local precursor gate states helper sidecar\n'
        '    try:\n'
        '        gate_daily = out.loc[\n'
        '            :,\n'
        '            [\n'
        '                "panel_id",\n'
        '                "date",\n'
        '                "data_bad",\n'
        '                "cond_var",\n'
        '                "cond_evt",\n'
