        '                "subgroup_common_cause_candidate",\n'
        '                "prefault_B",\n'
        '                "prefault_B_common_cause_overlap",\n'
        '                "prefault_B_effective",\n'
        '                "pre_alarm",\n'
        '                "prefault_cond_mid",\n'
        '                "prefault_cond_ae",\n'
        '                "prefault_cond_dtw",\n'
        '                "prefault_cond_ews",\n'
        '                "prealarm_cond_ae_mid_or_hi",\n'
