        '\n'
        '        # 패널별 집계: 기간, 고장 여부, EWS/전조 일수 등\n'
        '        grp_panel = out.groupby("panel_id")\n'
        '        panel_summary = grp_panel.agg(\n'
        '            first_date=("date", "min"),\n'
        '            last_date=("date", "max"),\n'
