        '            # 전조 후보 자체가 없는 패널\n'
        '            if not row["any_pre_alarm"]:\n'
        '                return "no_pre_alarm"\n'
        '\n'
        '            # 실제 고장 패널: 전조 리드타임이 3일 이상이면 전조 후보로 간주\n'
        '            if row["has_fault"]:\n'
        '                if pd.notna(row["lead_days"]) and row["lead_days"] >= 3:\n'
        '                    return "pre_fault_candidate"  # 고장 전에 전조가 선행\n'
        '                else:\n'
        '                    return "near_or_post_fault"  # 고장 직전/직후만 튄 케이스\n'
        '\n'
        '            # 아직 고장은 아니지만, 전조 알람이 장기간 누적된 만성 이상 패널\n'
        '            span_days = (row["last_date"] - row["first_date"]).days\n'
        '            if (row["n_pre_alarm_days"] >= 20) and (span_days >= 60):\n'
        '                return "chronic_abnormal"  # 장기간 만성 이상 패턴\n'
        '\n'
        '            # 나머지: 단기 이상 / 일시적 이상\n'
        '            return "short_abnormal"\n'
        '\n'
        '        panel_summary["alarm_pattern"] = panel_summary.apply(_classify_alarm_pattern, axis=1)\n'
