        'def build_summary(df: pd.DataFrame) -> pd.DataFrame:\n'
        '    status = df["패널고장여부_ko"].map(verdict_mod.normalize_text)\n'
        '    event = df["사건유형_ko"].map(verdict_mod.normalize_text)\n'
        '    row = {\n'
        '        "전체_패널수": int(len(df)),\n'
        '        "고장_패널수": int(status.eq("고장").sum()),\n'
        '        "비고장_패널수": int(status.eq("비고장").sum()),\n'
        '        "미확정_패널수": int(status.eq("미확정").sum()),\n'
        '        "사건해석_전조형_패널수": int(event.eq("전조형 고장").sum()),\n'
        '        "사건해석_급작_패널수": int(event.eq("급작 고장").sum()),\n'
        '        "전조평가셋_편입패널수": int(pd.to_numeric(df["전조평가셋편입_flag"], errors="coerce").fillna(0).sum()),\n'
        '        "급작평가셋_편입패널수": int(pd.to_numeric(df["급작평가셋편입_flag"], errors="coerce").fillna(0).sum()),\n'
