        '\n'
        '\n'
        'def object_particle(text: str) -> str:\n'
        '    normalized = normalize_text(text)\n'
        '    if not normalized:\n'
        '        return "를"\n'
        '    last_char = normalized[-1]\n'
        '    code_point = ord(last_char)\n'
        '    if 0xAC00 <= code_point <= 0xD7A3:\n'
        '        jongseong = (code_point - 0xAC00) % 28\n'
        '        return "을" if jongseong else "를"\n'
        '    return "를"\n'
        '\n'
        '\n'
        'def action_note(\n'
        '    top1_name: str,\n'
        '    competition_ranked: list[tuple[str, int]],\n'
        '    competition_state: str,\n'
        ') -> str:\n'
        '    if competition_state == "단일우세":\n'
        '        return f"{top1_name} 우선 점검"\n'
        '    if competition_state == "2자경합":\n'
        '        cand1, cand2 = [candidate for candidate, _ in competition_ranked[:2]]\n'
        '        return f"{cand1}과 {cand2}{object_particle(cand2)} 함께 우선 점검"\n'
        '    if competition_state == "다자경합":\n'
        '        cand1, cand2, cand3 = [candidate for candidate, _ in competition_ranked[:3]]\n'
        '        return f"{cand1}, {cand2}, {cand3}을 함께 우선 점검"\n'
        '    return f"{top1_name} 우선 점검"\n'
        '\n'
        '\n'
        'def confidence_label(top1_score: int, competition_state: str) -> str:\n'
        '    if top1_score >= 6 and competition_state == "단일우세":\n'
