        '\n'
        '    fault_keys = set(verdict_lookup)\n'
        '    if set(evidence_lookup) != fault_keys:\n'
        '        raise SystemExit("verdict and evidence pack fault key universe must match exactly")\n'
        '    if not detailed_df.empty and set(detailed_lookup) != fault_keys:\n'
