        '        external_pattern = normalize_text(verdict_row["GPVS_외부참조패턴_ko"]) or normalize_text(evidence_row["GPVS_외부참조패턴_ko"])\n'
        '        usage_level = normalize_text(evidence_row["GPVS_최종사용권고_ko"])\n'
