        '        default=repo_root(),\n'
        '        help="Repository root. Defaults to the current repo root.",\n'
        '    )\n'
        '    return parser.parse_args()\n'
        '\n'
        '\n'
        'def ensure_parent(path: Path) -> None:\n'
        '    path.parent.mkdir(parents=True, exist_ok=True)\n'
        '\n'
        '\n'
        'def write_csv(df: pd.DataFrame, path: Path) -> None:\n'
        '    ensure_parent(path)\n'
        '    df.to_csv(path, index=False, encoding="utf-8-sig")\n'
        '\n'
        '\n'
        'def write_text(text: str, path: Path) -> None:\n'
        '    ensure_parent(path)\n'
        '    path.write_text(text, encoding="utf-8-sig")\n'
        '\n'
        '\n'
        'def read_csv(path: Path, required: bool = True) -> pd.DataFrame:\n'
        '    if not path.exists():\n'
        '        if required:\n'
        '            raise FileNotFoundError(f"Required input is missing: {path}")\n'
        '        return pd.DataFrame()\n'
        '    try:\n'
        '        return pd.read_csv(path, low_memory=False, encoding="utf-8-sig")\n'
        '    except EmptyDataError:\n'
        '        return pd.DataFrame()\n'
        '    except UnicodeError:\n'
        '        return pd.read_csv(path, low_memory=False)\n'
        '\n'
        '\n'
        'def ensure_columns(df: pd.DataFrame, required: list[str], name: str) -> None:\n'
        '    missing = [column for column in required if column not in df.columns]\n'
        '    if missing:\n'
        '        raise SystemExit(f"{name} missing columns: {missing}")\n'
        '\n'
        '\n'
        'def normalize_text(value: object) -> str:\n'
        '    if pd.isna(value):\n'
        '        return ""\n'
        '    text = str(value).strip()\n'
        '    return "" if text.lower() == "nan" else text\n'
        '\n'
        '\n'
        'def to_timestamp(value: object) -> pd.Timestamp | None:\n'
        '    if pd.isna(value):\n'
        '        return None\n'
        '    ts = pd.to_datetime(value, errors="coerce")\n'
        '    if pd.isna(ts):\n'
        '        return None\n'
        '    return ts\n'
        '\n'
        '\n'
        'def format_date(value: object) -> str:\n'
        '    ts = to_timestamp(value)\n'
        '    return "" if ts is None else ts.strftime("%Y-%m-%d")\n'
        '\n'
        '\n'
        'def exact_panel_rows(df: pd.DataFrame, panel_id: str, site: str | None = None) -> pd.DataFrame:\n'
        '    if df.empty:\n'
        '        return df.copy()\n'
        '    panel_cols = [col for col in df.columns if col.lower() in {"panel_id", "display_entity_id", "entity_id"}]\n'
        '    if not panel_cols:\n'
        '        return df.iloc[0:0].copy()\n'
        '    mask = pd.Series(False, index=df.index)\n'
        '    for col in panel_cols:\n'
        '        mask = mask | df[col].astype(str).eq(panel_id)\n'
        '    result = df.loc[mask].copy()\n'
        '    if site is not None and "site" in result.columns:\n'
        '        result = result.loc[result["site"].astype(str).eq(site)].copy()\n'
        '    return result\n'
        '\n'
        '\n'
        'def earliest_true_date(df: pd.DataFrame, column: str, date_column: str = "date") -> pd.Timestamp | None:\n'
        '    if df.empty or column not in df.columns or date_column not in df.columns:\n'
        '        return None\n'
        '    working = df.loc[df[column].fillna(False).astype(bool), date_column]\n'
        '    if working.empty:\n'
        '        return None\n'
        '    value = pd.to_datetime(working, errors="coerce").min()\n'
        '    return None if pd.isna(value) else value\n'
        '\n'
        '\n'
        'def repeated_core_date(core_df: pd.DataFrame, column: str) -> pd.Timestamp | None:\n'
        '    if core_df.empty or column not in core_df.columns:\n'
        '        return None\n'
        '    value = pd.to_datetime(core_df[column], errors="coerce").dropna()\n'
        '    if value.empty:\n'
        '        return None\n'
        '    return value.iloc[0]\n'
        '\n'
        '\n'
        'def build_precursor_eval_keys(precursor_truth_df: pd.DataFrame) -> set[tuple[str, str]]:\n'
        '    panel_cols = [col for col in ("panel_id", "display_entity_id", "entity_id") if col in precursor_truth_df.columns]\n'
        '    if not panel_cols:\n'
        '        raise SystemExit(f"{PRECURSOR_TRUTH_NAME} missing panel id column")\n'
        '    positive_df = precursor_truth_df.loc[\n'
        '        precursor_truth_df["preferred_precursor_onset_date"].map(normalize_text).ne("")\n'
        '    ].copy()\n'
        '    keys: set[tuple[str, str]] = set()\n'
        '    for row in positive_df.to_dict(orient="records"):\n'
        '        site = normalize_text(row.get("site"))\n'
        '        for panel_col in panel_cols:\n'
        '            panel_id = normalize_text(row.get(panel_col))\n'
        '            if site and panel_id:\n'
        '                keys.add((site, panel_id))\n'
        '                break\n'
        '    return keys\n'
        '\n'
        '\n'
        'def build_abrupt_keys(abrupt_df: pd.DataFrame) -> set[tuple[str, str]]:\n'
        '    return {\n'
        '        (normalize_text(row["site"]), normalize_text(row["panel_id"]))\n'
        '        for row in abrupt_df.to_dict(orient="records")\n'
        '        if normalize_text(row["site"]) and normalize_text(row["panel_id"])\n'
        '    }\n'
        '\n'
        '\n'
        'def earliest_warning_date(reaudit_row: pd.Series, gate_df: pd.DataFrame) -> pd.Timestamp | None:\n'
        '    candidates = [\n'
        '        to_timestamp(reaudit_row.get("first_warning_date")),\n'
        '        earliest_true_date(gate_df, "ews_warning"),\n'
        '    ]\n'
        '    parsed = [value for value in candidates if value is not None]\n'
        '    if not parsed:\n'
        '        return None\n'
        '    return min(parsed)\n'
        '\n'
        '\n'
        'def abrupt_positive_evidence_exists(\n'
        '    key: tuple[str, str],\n'
        '    abrupt_keys: set[tuple[str, str]],\n'
        '    core_df: pd.DataFrame,\n'
        ') -> int:\n'
        '    if key in abrupt_keys:\n'
        '        return 1\n'
        '    if earliest_true_date(core_df, "final_fault") is not None:\n'
        '        return 1\n'
        '    if earliest_true_date(core_df, "critical_fault") is not None:\n'
        '        return 1\n'
        '    return 0\n'
        '\n'
        '\n'
        'def determine_event_redecision(\n'
        '    reaudit_row: pd.Series,\n'
        '    abrupt_positive_flag: int,\n'
        '    first_final_fault_date: pd.Timestamp | None,\n'
        '    dead_diag_date: pd.Timestamp | None,\n'
        ') -> EventRedecision:\n'
        '    retrospective_onset = to_timestamp(reaudit_row.get("retrospective_onset_date"))\n'
        '    strict_trigger = to_timestamp(reaudit_row.get("strict_trigger_date"))\n'
        '    onset_confidence = normalize_text(reaudit_row.get("onset_confidence"))\n'
        '    onset_method = normalize_text(reaudit_row.get("onset_method"))\n'
        '\n'
        '    precursor_rule = (\n'
        '        retrospective_onset is not None\n'
        '        and strict_trigger is not None\n'
        '        and retrospective_onset < strict_trigger\n'
        '        and onset_confidence == "high"\n'
        '        and onset_method == "persistent_5of7"\n'
        '    )\n'
        '    abrupt_rule = abrupt_positive_flag == 1 and (\n'
        '        retrospective_onset is None\n'
        '        or (\n'
        '            retrospective_onset is not None\n'
        '            and strict_trigger is not None\n'
        '            and retrospective_onset == strict_trigger\n'
        '            and onset_method == "strict_trigger_fallback"\n'
        '            and onset_confidence != "high"\n'
        '        )\n'
        '    )\n'
        '\n'
        '    if precursor_rule:\n'
        '        event_type = "전조형 고장"\n'
        '        event_rule = (\n'
        '            "retrospective_onset_date 비공란, strict_trigger_date 비공란, "\n'
        '            "retrospective_onset_date < strict_trigger_date, onset_confidence=high, "\n'
        '            "onset_method=persistent_5of7 이 모두 성립"\n'
        '        )\n'
        '    elif abrupt_rule:\n'
        '        event_type = "급작 고장"\n'
        '        event_rule = (\n'
        '            "abrupt positive evidence 가 있고, retrospective_onset_date 가 공란이거나 "\n'
        '            "retrospective_onset_date == strict_trigger_date 이면서 onset_method=strict_trigger_fallback, "\n'
        '            "onset_confidence != high 인 same-day fallback onset 이라 급작 고장으로 둠"\n'
        '        )\n'
        '    else:\n'
        '        event_type = "고장유형 보류"\n'
        '        event_rule = "전조형 고장 규칙과 급작 고장 규칙을 모두 만족하지 않음"\n'
        '\n'
        '    abrupt_ending = (\n'
        '        first_final_fault_date is not None\n'
        '        and strict_trigger is not None\n'
        '        and first_final_fault_date == strict_trigger\n'
        '        and dead_diag_date is not None\n'
        '        and dead_diag_date <= strict_trigger + pd.Timedelta(days=1)\n'
        '    )\n'
        '    if abrupt_ending:\n'
        '        terminal_pattern = "급격 종료"\n'
        '        terminal_rule = "first_final_fault_date == strict_trigger_date 이고 dead_diag_date <= strict_trigger_date + 1 day"\n'
        '    elif event_type == "급작 고장":\n'
        '        terminal_pattern = "급작 발생"\n'
        '        terminal_rule = "급격 종료 규칙은 아니지만 사건유형_재판정_ko == 급작 고장 이라 급작 발생으로 둠"\n'
        '    elif event_type == "전조형 고장":\n'
        '        terminal_pattern = "진행성 악화"\n'
        '        terminal_rule = "사건유형_재판정_ko == 전조형 고장 이고 급격 종료 규칙은 아니므로 진행성 악화로 둠"\n'
        '    else:\n'
        '        terminal_pattern = "불충분"\n'
        '        terminal_rule = "stored field 만으로 terminal failure pattern 을 더 좁히기 어려워 불충분으로 둠"\n'
        '\n'
        '    return EventRedecision(\n'
        '        event_type_ko=event_type,\n'
        '        terminal_pattern_ko=terminal_pattern,\n'
        '        event_rule_ko=event_rule,\n'
        '        terminal_rule_ko=terminal_rule,\n'
        '        abrupt_positive_flag=abrupt_positive_flag,\n'
        '    )\n'
        '\n'
        '\n'
        'def load_site_frame(root: Path, site: str, filename: str) -> pd.DataFrame:\n'
        '    return read_csv(root / "data" / site / "out" / filename, required=True)\n'
        '\n'
        '\n'
        'def load_optional_vendor_row(vendor_df: pd.DataFrame, site: str, panel_id: str) -> pd.Series | None:\n'
        '    if vendor_df.empty:\n'
        '        return None\n'
        '    row_df = exact_panel_rows(vendor_df, panel_id, site=site)\n'
        '    if row_df.empty:\n'
        '        return None\n'
        '    return row_df.iloc[0]\n'
        '\n'
        '\n'
        'def build_audit(root: Path) -> tuple[pd.DataFrame, pd.DataFrame, str]:\n'
        '    share_dir = root / "_share"\n'
        '    verdict_df = read_csv(share_dir / PANEL_VERDICT_NAME)\n'
        '    abrupt_df = read_csv(share_dir / ABRUPT6_NAME)\n'
        '    precursor_truth_df = read_csv(share_dir / PRECURSOR_TRUTH_NAME)\n'
        '    reaudit_df = read_csv(share_dir / REAUDIT_NAME)\n'
        '    vendor_df = read_csv(share_dir / VENDOR_ADJUDICATION_NAME, required=False)\n'
        '\n'
        '    ensure_columns(\n'
        '        verdict_df,\n'
        '        [\n'
        '            "site",\n'
        '            "panel_id",\n'
        '            "패널고장여부_ko",\n'
        '            "사건유형_ko",\n'
        '            "최종고장양상_ko",\n'
        '            "전조흔적_flag",\n'
        '            "순수급작_flag",\n'
        '            "전조평가셋편입_flag",\n'
        '            "급작평가셋편입_flag",\n'
        '        ],\n'
        '        PANEL_VERDICT_NAME,\n'
        '    )\n'
        '    ensure_columns(abrupt_df, ["site", "panel_id"], ABRUPT6_NAME)\n'
        '    ensure_columns(\n'
        '        precursor_truth_df,\n'
        '        ["site", "preferred_precursor_onset_date"],\n'
        '        PRECURSOR_TRUTH_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        reaudit_df,\n'
        '        ["site", "panel_id", "retrospective_onset_date", "strict_trigger_date", "onset_confidence", "onset_method"],\n'
        '        REAUDIT_NAME,\n'
        '    )\n'
        '\n'
        '    fault_df = verdict_df.loc[verdict_df["패널고장여부_ko"].eq("고장")].copy()\n'
        '    fault_df = fault_df.sort_values(["site", "panel_id"]).drop_duplicates(subset=["site", "panel_id"], keep="first")\n'
        '    if len(fault_df) != 6:\n'
        '        raise SystemExit(f"expected current fault panel count to be 6, found {len(fault_df)}")\n'
        '\n'
        '    abrupt_keys = build_abrupt_keys(abrupt_df)\n'
        '    precursor_eval_keys = build_precursor_eval_keys(precursor_truth_df)\n'
        '\n'
        '    site_cache: dict[tuple[str, str], pd.DataFrame] = {}\n'
        '    audit_rows: list[dict[str, object]] = []\n'
        '    explicit_precursor_rule_hits = 0\n'
        '\n'
        '    for row in fault_df.to_dict(orient="records"):\n'
        '        site = normalize_text(row["site"])\n'
        '        panel_id = normalize_text(row["panel_id"])\n'
        '        key = (site, panel_id)\n'
        '\n'
        '        core_df = site_cache.setdefault((site, "core"), load_site_frame(root, site, "panel_day_core.csv"))\n'
        '        gate_df = site_cache.setdefault((site, "gate"), load_site_frame(root, site, "ae_simple_local_precursor_gate_daily.csv"))\n'
        '\n'
        '        core_panel_df = exact_panel_rows(core_df, panel_id, site=site)\n'
        '        gate_panel_df = exact_panel_rows(gate_df, panel_id, site=site)\n'
        '        reaudit_panel_df = exact_panel_rows(reaudit_df, panel_id, site=site)\n'
        '        if reaudit_panel_df.empty:\n'
        '            raise SystemExit(f"missing reaudit row for fault panel {site}/{panel_id}")\n'
        '        reaudit_row = reaudit_panel_df.iloc[0]\n'
        '\n'
        '        earliest_warning = earliest_warning_date(reaudit_row, gate_panel_df)\n'
        '        retrospective_onset = to_timestamp(reaudit_row.get("retrospective_onset_date"))\n'
        '        strict_trigger = to_timestamp(reaudit_row.get("strict_trigger_date"))\n'
        '        first_final_fault_date = earliest_true_date(core_panel_df, "final_fault")\n'
        '        dead_diag_date = repeated_core_date(core_panel_df, "dead_diag_date")\n'
        '        abrupt_positive_flag = abrupt_positive_evidence_exists(key, abrupt_keys, core_panel_df)\n'
        '        redecision = determine_event_redecision(\n'
        '            reaudit_row=reaudit_row,\n'
        '            abrupt_positive_flag=abrupt_positive_flag,\n'
        '            first_final_fault_date=first_final_fault_date,\n'
        '            dead_diag_date=dead_diag_date,\n'
        '        )\n'
        '\n'
        '        current_event = normalize_text(row["사건유형_ko"])\n'
        '        current_terminal = normalize_text(row["최종고장양상_ko"])\n'
        '        needs_correction = int(\n'
        '            current_event != redecision.event_type_ko\n'
        '            or current_terminal != redecision.terminal_pattern_ko\n'
        '        )\n'
        '\n'
        '        vendor_row = load_optional_vendor_row(vendor_df, site, panel_id)\n'
        '        vendor_hint_parts: list[str] = []\n'
        '        if vendor_row is not None:\n'
        '            for column in ("vendor_fault_family", "vendor_reply_class"):\n'
        '                value = normalize_text(vendor_row.get(column))\n'
        '                if value:\n'
        '                    vendor_hint_parts.append(f"{column}={value}")\n'
        '\n'
        '        reason_parts = [\n'
        '            redecision.event_rule_ko,\n'
        '            redecision.terminal_rule_ko,\n'
        '            f"abrupt_positive_evidence_flag={abrupt_positive_flag}",\n'
        '        ]\n'
        '        if key in precursor_eval_keys:\n'
        '            reason_parts.append("strict precursor truth positive 포함")\n'
        '        if vendor_hint_parts:\n'
        '            reason_parts.append(", ".join(vendor_hint_parts))\n'
        '\n'
        '        precursor_rule_hit = int(redecision.event_type_ko == "전조형 고장")\n'
        '        explicit_precursor_rule_hits += precursor_rule_hit\n'
        '\n'
        '        audit_rows.append(\n'
        '            {\n'
        '                "site": site,\n'
        '                "panel_id": panel_id,\n'
        '                "현재표_사건유형_ko": current_event,\n'
        '                "현재표_최종고장양상_ko": current_terminal,\n'
        '                "earliest_warning_date": format_date(earliest_warning),\n'
        '                "retrospective_onset_date": format_date(retrospective_onset),\n'
        '                "strict_trigger_date": format_date(strict_trigger),\n'
        '                "first_final_fault_date": format_date(first_final_fault_date),\n'
        '                "dead_diag_date": format_date(dead_diag_date),\n'
        '                "onset_confidence": normalize_text(reaudit_row.get("onset_confidence")),\n'
        '                "onset_method": normalize_text(reaudit_row.get("onset_method")),\n'
        '                "전조흔적_flag": int(pd.to_numeric(pd.Series([row["전조흔적_flag"]]), errors="coerce").fillna(0).iloc[0]),\n'
        '                "순수급작_flag": int(pd.to_numeric(pd.Series([row["순수급작_flag"]]), errors="coerce").fillna(0).iloc[0]),\n'
        '                "전조평가셋편입_flag": int(pd.to_numeric(pd.Series([row["전조평가셋편입_flag"]]), errors="coerce").fillna(0).iloc[0]),\n'
        '                "급작평가셋편입_flag": int(pd.to_numeric(pd.Series([row["급작평가셋편입_flag"]]), errors="coerce").fillna(0).iloc[0]),\n'
        '                "사건유형_재판정_ko": redecision.event_type_ko,\n'
        '                "최종고장양상_재판정_ko": redecision.terminal_pattern_ko,\n'
        '                "재판정_근거_ko": "; ".join(part for part in reason_parts if part),\n'
        '                "현재표_보정필요여부_flag": needs_correction,\n'
        '            }\n'
        '        )\n'
        '\n'
        '    audit_df = pd.DataFrame(audit_rows).reindex(columns=AUDIT_COLS)\n'
        '    if audit_df[["site", "panel_id"]].duplicated().any():\n'
        '        raise SystemExit("fault panel audit output must be unique by (site, panel_id)")\n'
        '    if len(audit_df) != 6:\n'
        '        raise SystemExit(f"fault panel audit output must contain exactly 6 rows, found {len(audit_df)}")\n'
        '\n'
        '    c429_df = audit_df.loc[audit_df["site"].eq(TARGET_SITE) & audit_df["panel_id"].eq(TARGET_PANEL_ID)].copy()\n'
        '    if len(c429_df) != 1:\n'
        '        raise SystemExit("c42997...1.1 must appear exactly once in fault panel event audit")\n'
        '    if normalize_text(c429_df.iloc[0]["사건유형_재판정_ko"]) != "전조형 고장":\n'
        '        raise SystemExit("c42997...1.1 must re-evaluate to 전조형 고장 under explicit rule")\n'
        '\n'
        '    precursor_rule_mask = (\n'
        '        audit_df["retrospective_onset_date"].map(normalize_text).ne("")\n'
        '        & audit_df["strict_trigger_date"].map(normalize_text).ne("")\n'
        '        & (\n'
        '            pd.to_datetime(audit_df["retrospective_onset_date"], errors="coerce")\n'
        '            < pd.to_datetime(audit_df["strict_trigger_date"], errors="coerce")\n'
        '        )\n'
        '        & audit_df["onset_confidence"].eq("high")\n'
        '        & audit_df["onset_method"].eq("persistent_5of7")\n'
        '    )\n'
        '    if audit_df.loc[precursor_rule_mask, "사건유형_재판정_ko"].ne("전조형 고장").any():\n'
        '        raise SystemExit("any fault panel meeting the explicit precursor rule must re-evaluate to 전조형 고장")\n'
        '    if explicit_precursor_rule_hits != int(precursor_rule_mask.sum()):\n'
        '        raise SystemExit("explicit precursor rule hit count mismatch")\n'
        '\n'
        '    mismatch_mask = (\n'
        '        (audit_df["사건유형_재판정_ko"].eq("전조형 고장") & audit_df["전조평가셋편입_flag"].eq(0))\n'
        '        | (audit_df["사건유형_재판정_ko"].eq("급작 고장") & audit_df["급작평가셋편입_flag"].eq(0))\n'
        '    )\n'
        '\n'
        '    summary_row = {\n'
        '        "고유_고장패널수": int(len(audit_df)),\n'
        '        "사건유형_재판정_전조형수": int(audit_df["사건유형_재판정_ko"].eq("전조형 고장").sum()),\n'
        '        "사건유형_재판정_급작수": int(audit_df["사건유형_재판정_ko"].eq("급작 고장").sum()),\n'
