        '    return pd.read_csv(path, low_memory=False, encoding="utf-8-sig")\n'
        '\n'
        '\n'
        'def ensure_columns(df: pd.DataFrame, required: list[str], name: str) -> None:\n'
        '    missing = [column for column in required if column not in df.columns]\n'
        '    if missing:\n'
        '        raise SystemExit(f"{name} missing columns: {missing}")\n'
        '\n'
        '\n'
        'def canonicalize_gpvs_code(value: object) -> str:\n'
        '    text = normalize_text(value)\n'
        '    match = re.match(r"^(F[0-7])", text)\n'
        '    return match.group(1) if match else ""\n'
        '\n'
        '\n'
        'def as_key(site: object, panel_id: object) -> tuple[str, str]:\n'
        '    return normalize_text(site), normalize_text(panel_id)\n'
        '\n'
        '\n'
        'def lookup_map(df: pd.DataFrame) -> dict[tuple[str, str], dict[str, object]]:\n'
        '    if df.empty or "site" not in df.columns or "panel_id" not in df.columns:\n'
        '        return {}\n'
        '    records: dict[tuple[str, str], dict[str, object]] = {}\n'
        '    for row in df.to_dict(orient="records"):\n'
        '        records[as_key(row.get("site"), row.get("panel_id"))] = row\n'
        '    return records\n'
        '\n'
        '\n'
        'def first_existing_column(df: pd.DataFrame, candidates: list[str]) -> str:\n'
        '    for candidate in candidates:\n'
        '        if candidate in df.columns:\n'
        '            return candidate\n'
        '    return ""\n'
        '\n'
        '\n'
        'def first_row_text(row: dict[str, object], candidates: list[str]) -> str:\n'
        '    for candidate in candidates:\n'
        '        text = normalize_text(row.get(candidate))\n'
        '        if text:\n'
        '            return text\n'
        '    return ""\n'
        '\n'
        '\n'
        'def fmt_score(value: object) -> str:\n'
        '    text = normalize_text(value)\n'
        '    if not text:\n'
        '        return ""\n'
        '    try:\n'
        '        return f"{float(text):.3f}"\n'
        '    except ValueError:\n'
        '        return text\n'
        '\n'
        '\n'
        'def build_canonical_dictionary_map(df: pd.DataFrame) -> dict[str, dict[str, str]]:\n'
        '    canonical_map = {\n'
        '        code: payload.copy()\n'
        '        for code, payload in DEFAULT_CANONICAL_DICTIONARY.items()\n'
        '    }\n'
        '    if df.empty or "canonical_gpvs_code" not in df.columns:\n'
        '        return canonical_map\n'
        '    for row in df.to_dict(orient="records"):\n'
        '        code = normalize_text(row.get("canonical_gpvs_code"))\n'
        '        if not code:\n'
        '            continue\n'
        '        payload = canonical_map.setdefault(code, {})\n'
        '        for field in ["current_usage_tier_ko", "mlpe_reference_name_ko", "usage_rule_ko", "note_ko"]:\n'
        '            text = normalize_text(row.get(field))\n'
        '            if text:\n'
        '                payload[field] = text\n'
        '    return canonical_map\n'
        '\n'
        '\n'
        'def build_matching_table_map(df: pd.DataFrame) -> dict[str, list[dict[str, object]]]:\n'
        '    table_map: dict[str, list[dict[str, object]]] = {}\n'
        '    if df.empty or "canonical_gpvs_code" not in df.columns:\n'
        '        return table_map\n'
        '    for row in df.to_dict(orient="records"):\n'
        '        code = normalize_text(row.get("canonical_gpvs_code"))\n'
        '        if not code:\n'
        '            continue\n'
        '        table_map.setdefault(code, []).append(row)\n'
        '    return table_map\n'
        '\n'
        '\n'
        'def build_internal_evidence(\n'
        '    family_row: dict[str, object] | None,\n'
        '    attach_row: dict[str, object] | None,\n'
        ') -> str:\n'
        '    if family_row:\n'
        '        parts = []\n'
        '        source = normalize_text(family_row.get("prediction_source"))\n'
        '        fallback = normalize_text(family_row.get("fallback_rule_used"))\n'
        '        error_type = normalize_text(family_row.get("error_type"))\n'
        '        pred_family = normalize_text(family_row.get("pred_fault_family"))\n'
        '        vendor_family = normalize_text(family_row.get("vendor_fault_family"))\n'
        '        if source:\n'
        '            parts.append(f"family evaluator source={source}")\n'
        '        if fallback:\n'
        '            parts.append(f"fallback={fallback}")\n'
        '        if error_type:\n'
        '            parts.append(f"error={error_type}")\n'
        '        if pred_family:\n'
        '            parts.append(f"pred={pred_family}")\n'
        '        if vendor_family:\n'
        '            parts.append(f"vendor={vendor_family}")\n'
        '        return ", ".join(parts) if parts else "family evaluator row 확인됨"\n'
        '    if attach_row:\n'
        '        source_key = normalize_text(attach_row.get("source_key_ko"))\n'
        '        note = normalize_text(attach_row.get("비고_ko"))\n'
        '        parts = []\n'
        '        if source_key:\n'
        '            parts.append(f"attach candidate key={source_key}")\n'
        '        if note:\n'
        '            parts.append(note)\n'
        '        return ", ".join(parts) if parts else "attach candidate row 확인됨"\n'
        '    return "근거 파일 미확인"\n'
        '\n'
        '\n'
        'def build_external_pattern(\n'
        '    verdict_row: dict[str, object],\n'
        '    canonical_code: str,\n'
        '    canonical_map: dict[str, dict[str, str]],\n'
        ') -> str:\n'
        '    pattern = first_row_text(verdict_row, EXTERNAL_PATTERN_COL_CANDIDATES)\n'
        '    if pattern:\n'
        '        return pattern\n'
        '    if canonical_code in DEFAULT_EXTERNAL_PATTERN_BY_CODE:\n'
        '        return DEFAULT_EXTERNAL_PATTERN_BY_CODE[canonical_code]\n'
        '    return normalize_text(canonical_map.get(canonical_code, {}).get("mlpe_reference_name_ko"))\n'
        '\n'
        '\n'
        'def build_external_evidence(\n'
        '    detailed_row: dict[str, object] | None,\n'
        '    sanity_row: dict[str, object] | None,\n'
        ') -> str:\n'
        '    if not detailed_row:\n'
        '        return "근거 파일 미확인"\n'
        '    parts = []\n'
        '    model_source = normalize_text(detailed_row.get("gpvs_detailed_model_source"))\n'
        '    top1 = normalize_text(detailed_row.get("gpvs_detailed_top1_fault_type"))\n'
        '    top1_score = fmt_score(detailed_row.get("gpvs_detailed_top1_score"))\n'
        '    top2 = normalize_text(detailed_row.get("gpvs_detailed_top2_fault_type"))\n'
        '    top2_score = fmt_score(detailed_row.get("gpvs_detailed_top2_score"))\n'
        '    margin = fmt_score(detailed_row.get("gpvs_detailed_margin"))\n'
        '    status = normalize_text(detailed_row.get("gpvs_detailed_status_ko"))\n'
        '    reason = normalize_text(detailed_row.get("gpvs_detailed_reason_ko"))\n'
        '    if model_source:\n'
        '        parts.append(f"by-type source={model_source}")\n'
        '    if top1:\n'
        '        parts.append(f"top1={top1}({top1_score})")\n'
        '    if top2:\n'
        '        parts.append(f"top2={top2}({top2_score})")\n'
        '    if margin:\n'
        '        parts.append(f"margin={margin}")\n'
        '    if status:\n'
        '        parts.append(f"status={status}")\n'
        '    if reason:\n'
        '        parts.append(f"reason={reason}")\n'
        '    if sanity_row:\n'
        '        attach_recommendation = normalize_text(sanity_row.get("attach_recommendation_ko"))\n'
        '        consistency = normalize_text(sanity_row.get("family_vs_detail_consistency_ko"))\n'
        '        if attach_recommendation:\n'
        '            parts.append(f"sanity={attach_recommendation}")\n'
        '        if consistency:\n'
        '            parts.append(f"consistency={consistency}")\n'
        '    return ", ".join(parts) if parts else "근거 파일 미확인"\n'
        '\n'
        '\n'
        'def map_usefulness_to_compatibility(\n'
        '    usefulness: str,\n'
        '    summary_final_recommendation: str,\n'
        ') -> str:\n'
        '    if usefulness == "비권장":\n'
        '        return "직접 판정축 사용 비권장"\n'
        '    if usefulness in {"참고가능", "주의참고"}:\n'
        '        return "조건부 참고 가능"\n'
        '    if summary_final_recommendation in {\n'
        '        "참고축으로만 사용",\n'
        '        "조건부 참고 가능",\n'
        '        "직접 판정축 사용 비권장",\n'
        '        "비교곤란",\n'
        '    }:\n'
        '        return summary_final_recommendation\n'
        '    return "비교곤란"\n'
        '\n'
        '\n'
        'def build_compatibility_evidence(\n'
        '    agreement_row: dict[str, object] | None,\n'
        '    compatibility_summary_row: dict[str, object],\n'
        ') -> str:\n'
        '    parts = []\n'
        '    if agreement_row:\n'
        '        family_alignment = normalize_text(agreement_row.get("family_vs_kernellog_alignment_ko"))\n'
        '        scenario_alignment = normalize_text(agreement_row.get("scenario_vs_kernellog_alignment_ko"))\n'
        '        shift = normalize_text(agreement_row.get("feature_shift_bucket_ko"))\n'
        '        usefulness = normalize_text(agreement_row.get("overall_gpvs_reference_usefulness_ko"))\n'
        '        trust_note = normalize_text(agreement_row.get("overall_gpvs_trust_note_ko"))\n'
        '        if family_alignment:\n'
        '            parts.append(f"family_alignment={family_alignment}")\n'
        '        if scenario_alignment:\n'
        '            parts.append(f"scenario_alignment={scenario_alignment}")\n'
        '        if shift:\n'
        '            parts.append(f"feature_shift={shift}")\n'
        '        if usefulness:\n'
        '            parts.append(f"panel_usefulness={usefulness}")\n'
        '        if trust_note:\n'
        '            parts.append(trust_note)\n'
        '    summary_final = normalize_text(compatibility_summary_row.get("final_recommendation_ko"))\n'
        '    summary_note = normalize_text(compatibility_summary_row.get("note_ko"))\n'
        '    strong_shift_count = normalize_text(compatibility_summary_row.get("strong_shift_panel_count"))\n'
        '    scenario_conflict_count = normalize_text(compatibility_summary_row.get("scenario_conflict_count"))\n'
        '    if summary_final:\n'
        '        parts.append(f"summary={summary_final}")\n'
        '    if strong_shift_count:\n'
        '        parts.append(f"strong_shift_panel_count={strong_shift_count}")\n'
        '    if scenario_conflict_count:\n'
        '        parts.append(f"scenario_conflict_count={scenario_conflict_count}")\n'
        '    if summary_note:\n'
        '        parts.append(summary_note)\n'
        '    return "; ".join(part for part in parts if part) or "호환성 근거 미확인"\n'
        '\n'
        '\n'
        'def build_matching_policy(canonical_code: str, canonical_map: dict[str, dict[str, str]]) -> str:\n'
        '    if not canonical_code:\n'
        '        return "비권장"\n'
        '    usage_tier = normalize_text(canonical_map.get(canonical_code, {}).get("current_usage_tier_ko"))\n'
        '    return TIER_TO_POLICY.get(usage_tier, "비권장")\n'
        '\n'
        '\n'
        'def build_matching_evidence(\n'
        '    canonical_code: str,\n'
        '    canonical_map: dict[str, dict[str, str]],\n'
        '    matching_table_map: dict[str, list[dict[str, object]]],\n'
        ') -> str:\n'
        '    if not canonical_code:\n'
        '        return "canonical GPVS code 미확인"\n'
        '    rule = normalize_text(canonical_map.get(canonical_code, {}).get("usage_rule_ko"))\n'
        '    note = normalize_text(canonical_map.get(canonical_code, {}).get("note_ko"))\n'
        '    parts = [MATCHING_REASON_BY_CODE.get(canonical_code, "canonical matching rule 미정의")]\n'
        '    if rule:\n'
        '        parts.append(rule)\n'
        '    if note:\n'
        '        parts.append(note)\n'
        '    rows = matching_table_map.get(canonical_code, [])\n'
        '    if rows:\n'
        '        compact = []\n'
        '        for row in rows:\n'
        '            official_fault = normalize_text(row.get("mlpe_official_fault_ko"))\n'
        '            role = normalize_text(row.get("match_role_ko"))\n'
        '            if official_fault and role:\n'
        '                compact.append(f"{official_fault}:{role}")\n'
        '        if compact:\n'
        '            parts.append("matching=" + " / ".join(compact))\n'
        '    return "; ".join(part for part in parts if part)\n'
        '\n'
        '\n'
        'def combine_final_recommendation(\n'
        '    matching_policy: str,\n'
        '    compatibility_judgment: str,\n'
        '    has_internal_evidence: bool,\n'
        '    has_external_evidence: bool,\n'
        ') -> str:\n'
        '    if not has_internal_evidence or not has_external_evidence:\n'
        '        return "비권장"\n'
        '    if matching_policy == "비권장":\n'
        '        return "비권장"\n'
        '    if matching_policy in {\n'
        '        "핵심참조",\n'
        '        "핵심참조후보",\n'
        '        "보조참조",\n'
        '        "교란플래그",\n'
        '        "시스템보류",\n'
        '        "기준선",\n'
        '    }:\n'
        '        return matching_policy\n'
        '    return "비권장"\n'
        '\n'
        '\n'
        'def build_recommendation_reason(\n'
        '    final_recommendation: str,\n'
        '    compatibility_judgment: str,\n'
        '    matching_policy: str,\n'
        '    external_pattern: str,\n'
        '    canonical_code: str,\n'
        ') -> str:\n'
        '    pattern_or_code = external_pattern or canonical_code or "GPVS reference"\n'
        '    if final_recommendation == "핵심참조":\n'
        '        return f"{pattern_or_code}는 direct root-cause가 아니라 reference-only 핵심참조로만 사용한다."\n'
        '    if final_recommendation == "핵심참조후보":\n'
        '        return f"{pattern_or_code}는 direct root-cause가 아니라 reference-only 핵심참조후보로만 사용한다."\n'
        '    if final_recommendation == "보조참조":\n'
        '        return f"{pattern_or_code}는 직접 root-cause 판정에는 쓰지 말고 보조참조로만 사용한다."\n'
        '    if final_recommendation == "교란플래그":\n'
        '        return f"{pattern_or_code}는 고장명보다 교란 신호를 표시하는 용도로만 쓰는 것이 안전하다."\n'
        '    if final_recommendation == "시스템보류":\n'
        '        return f"{pattern_or_code}는 현재 패널 단독표보다 시스템/통합 결과표 후보축으로만 보류한다."\n'
        '    if final_recommendation == "기준선":\n'
        '        return f"{pattern_or_code}는 fault명이 아니라 비교 기준선으로만 사용한다."\n'
        '    if matching_policy == "비권장":\n'
        '        return f"{pattern_or_code}는 matching policy 자체가 비권장이라 direct root-cause로도 reference로도 쓰지 않는다."\n'
        '    return f"{pattern_or_code}는 required evidence가 부족하거나 unusable 상태라 비권장으로 둔다."\n'
        '\n'
        '\n'
        'def main() -> None:\n'
        '    args = parse_args()\n'
        '    share_dir = args.root / "_share"\n'
        '\n'
        '    verdict_df = read_csv(share_dir / VERDICT_NAME)\n'
