        '    matching_summary_df = read_csv(share_dir / MLPE_MATCHING_SUMMARY_NAME)\n'
        '    ensure_columns(\n'
        '        matching_summary_df,\n'
        '        MATCHING_SUMMARY_REQUIRED_COLS,\n'
        '        MLPE_MATCHING_SUMMARY_NAME,\n'
