        '\n'
        '    family_eval_df = read_optional_csv(share_dir / FAMILY_EVAL_NAME)\n'
        '    attach_candidates_df = read_optional_csv(share_dir / ATTACH_CANDIDATES_NAME)\n'
        '    detailed_sanity_df = read_optional_csv(share_dir / DETAILED_SANITY_NAME)\n'
        '    provenance_summary_df = read_optional_csv(share_dir / BYTYPE_PROVENANCE_SUMMARY_NAME)\n'
        '    rebuild_summary_df = read_optional_csv(share_dir / BYTYPE_REBUILD_SUMMARY_NAME)\n'
        '    panel_agreement_df = read_optional_csv(share_dir / MLPE_PANEL_AGREEMENT_NAME)\n'
        '    canonical_dictionary_df = read_optional_csv(share_dir / CANONICAL_DICTIONARY_NAME)\n'
        '\n'
        '    internal_col = first_existing_column(verdict_df, INTERNAL_COL_CANDIDATES)\n'
        '    external_col = first_existing_column(verdict_df, EXTERNAL_PATTERN_COL_CANDIDATES)\n'
        '\n'
        '    fault_df = verdict_df[verdict_df["패널고장여부_ko"].map(normalize_text) == "고장"].copy()\n'
        '    if fault_df.empty:\n'
        '        raise SystemExit("no current fault panels found in verdict table")\n'
        '\n'
        '    family_eval_map = lookup_map(family_eval_df)\n'
        '    attach_candidates_map = lookup_map(attach_candidates_df)\n'
        '    detailed_map = lookup_map(detailed_df)\n'
        '    detailed_sanity_map = lookup_map(detailed_sanity_df)\n'
        '    panel_agreement_map = lookup_map(panel_agreement_df)\n'
        '\n'
        '    compatibility_summary_row = compatibility_summary_df.iloc[0].to_dict()\n'
        '    matching_summary_row = matching_summary_df.iloc[0].to_dict()\n'
        '    provenance_summary_row = provenance_summary_df.iloc[0].to_dict() if not provenance_summary_df.empty else {}\n'
        '    rebuild_summary_row = rebuild_summary_df.iloc[0].to_dict() if not rebuild_summary_df.empty else {}\n'
        '\n'
        '    canonical_map = build_canonical_dictionary_map(canonical_dictionary_df)\n'
        '    matching_table_map = build_matching_table_map(matching_table_df)\n'
        '\n'
        '    pack_rows: list[dict[str, object]] = []\n'
        '    for row in fault_df.to_dict(orient="records"):\n'
        '        key = as_key(row.get("site"), row.get("panel_id"))\n'
        '        detailed_row = detailed_map.get(key)\n'
        '        family_row = family_eval_map.get(key)\n'
        '        attach_row = attach_candidates_map.get(key)\n'
        '        agreement_row = panel_agreement_map.get(key)\n'
        '        sanity_row = detailed_sanity_map.get(key)\n'
        '\n'
        '        canonical_code = canonicalize_gpvs_code(\n'
        '            (detailed_row or {}).get("gpvs_detailed_top1_fault_type")\n'
        '        )\n'
        '        internal_verdict = normalize_text(row.get(internal_col)) if internal_col else ""\n'
        '        external_pattern = normalize_text(row.get(external_col)) if external_col else ""\n'
