        '\n'
        '        pack_rows.append(\n'
        '            {\n'
        '                "site": normalize_text(row.get("site")),\n'
        '                "panel_id": normalize_text(row.get("panel_id")),\n'
        '                "사건유형_ko": normalize_text(row.get("사건유형_ko")),\n'
        '                "최종고장양상_ko": normalize_text(row.get("최종고장양상_ko")),\n'
        '                "커널로그_원인군_ko": normalize_text(row.get("커널로그_원인군_ko")),\n'
        '                "GPVS_내부판정_ko": internal_verdict,\n'
        '                "GPVS_내부판정근거_ko": internal_evidence,\n'
        '                "GPVS_외부참조패턴_ko": external_pattern,\n'
        '                "GPVS_외부참조근거_ko": external_evidence,\n'
        '                "GPVS_호환성판정_ko": compatibility_judgment,\n'
        '                "GPVS_호환성근거_ko": build_compatibility_evidence(\n'
        '                    agreement_row,\n'
