        '    "F5": "일부 연결부가 끊기거나 약해진 것처럼 보이는 패턴으로, 커넥터 이탈·접점 불량·부분 단선과 더 잘 이어짐",\n'
        '    "F6": "제어 응답 또는 제어 파라미터 이상과 유사한 패턴",\n'
        '    "F7": "제어 응답 또는 제어 파라미터 이상과 유사한 패턴",\n'
        '}\n'
        'GPVS_REFERENCE_GRADE_MAP = {\n'
        '    "참고가능": "참고가능",\n'
        '    "주의참고": "주의참고",\n'
