        '    "F4": {\n'
        '        "family": "PV 어레이 이상",\n'
        '        "name": "PV 어레이 mismatch(부분 음영) 시나리오",\n'
        '        "description": "일부 패널이 부분 음영을 받아 어레이 내 전압·전류 균형이 깨지는 상황",\n'
        '    },\n'
        '    "F5": {\n'
        '        "family": "PV 어레이 이상",\n'
        '        "name": "PV 어레이 mismatch(부분 개방회로) 시나리오",\n'
        '        "description": "PV 어레이 일부에 open-circuit 성격 이상이 생겨 어레이 균형이 깨지는 상황",\n'
        '    },\n'
        '    "F6": {\n'
        '        "family": "제어기 이상",\n'
        '        "name": "부스트 컨버터 PI gain 이상 시나리오",\n'
        '        "description": "PI 제어기의 gain 설정 이상으로 제어 응답이 비정상화되는 상황",\n'
        '    },\n'
        '    "F7": {\n'
        '        "family": "제어기 이상",\n'
        '        "name": "부스트 컨버터 PI 시정수 이상 시나리오",\n'
        '        "description": "PI 제어기의 time constant 이상으로 응답 속도와 안정화 과정이 비정상화되는 상황",\n'
        '    },\n'
