        '}\n'
        '\n'
        'EVENT_HISTORY_ORDER = [\n'
        '    "전조형 고장",\n'
        '    "급작 고장",\n'
        '    "고장유형 보류",\n'
        '    "공통원인 이벤트",\n'
        '    "반복 이상",\n'
        ']\n'
        '\n'
        'EVENT_PRIORITY = {\n'
        '    "급작 고장": 1,\n'
