        '    "고장유형 보류": 3,\n'
        '    "공통원인 이벤트": 4,\n'
        '    "반복 이상": 5,\n'
        '}\n'
        '\n'
        'SPECIFIC_TO_BROAD_SYMPTOM = {\n'
        '    "다이오드형": "전압 변화형",\n'
        '    "개방/장치이상형": "전압 변화형",\n'
        '    "모듈손상형": "출력 저하형",\n'
        '    "출력저하형": "출력 저하형",\n'
        '    "전압변화형": "전압 변화형",\n'
        '    "복합형": "복합형",\n'
        '    "불충분": "불충분",\n'
        '}\n'
        '\n'
        'SCOPE_BY_EVENT_TYPE = {\n'
        '    "전조형 고장": "step3_precursor_performance",\n'
        '    "급작 고장": "step4_abrupt_no_precursor",\n'
        '    "공통원인 이벤트": "step4_common_cause_routing",\n'
        '}\n'
        '\n'
        'REQUIRED_FORENSIC_SUMMARY_COLS = [\n'
        '    "site",\n'
        '    "panel_id",\n'
        '    "현재_재감사라벨_ko",\n'
