        '    "strong_trigger_date",\n'
        '    "전조흔적_시작일",\n'
        '    "강한트리거일",\n'
        '    "사건유형_결정규칙_ko",\n'
        '    "최종고장양상_결정규칙_ko",\n'
        '    "사건유형_결정_ko",\n'
        '    "최종고장양상_결정_ko",\n'
        '    "사건시간양상_판정_ko",\n'
        '    "현재표_보정필요여부_flag",\n'
        ']\n'
        '\n'
        'FORENSIC_RULE_SITE = "conalog"\n'
        'FORENSIC_RULE_PANEL_ID = "c42997a6-5881-47e7-9035-7de8a2673b54.1.1"\n'
        'FORENSIC_RULE_ONSET_DATE = "2025-01-20"\n'
        'FORENSIC_RULE_TRIGGER_DATE = "2025-03-21"\n'
        'FORENSIC_RULE_EVENT_TYPE = "전조형 고장"\n'
        'FORENSIC_RULE_TERMINAL_PATTERN = "급격 종료"\n'
        'FORENSIC_RULE_REASON = "stored-field rule 기준 retrospective_onset_date<strict_trigger_date, onset_confidence=high, onset_method=persistent_5of7 이라 전조형 고장으로 읽고 최종고장양상은 급격 종료로 둔다"\n'
        '\n'
        'EXPECTED_FINAL_SCOPES = {\n'
        '    "step3_precursor_performance",\n'
        '    "step4_abrupt_no_precursor",\n'
        '    "step4_common_cause_routing",\n'
        '}\n'
        '\n'
        '\n'
        'def parse_args() -> argparse.Namespace:\n'
        '    parser = argparse.ArgumentParser(\n'
        '        description="Build a panel-level representative multi-axis verdict table with separate event-history and cluster supplements."\n'
        '    )\n'
        '    parser.add_argument(\n'
        '        "--root",\n'
        '        type=Path,\n'
        '        default=Path(__file__).resolve().parents[2],\n'
        '        help="Repository root. Defaults to the project root.",\n'
        '    )\n'
        '    return parser.parse_args()\n'
        '\n'
        '\n'
        'def normalize_text(value: object) -> str:\n'
        '    if pd.isna(value):\n'
        '        return ""\n'
        '    text = str(value).strip()\n'
        '    return "" if text.lower() == "nan" else text\n'
        '\n'
        '\n'
        'def read_csv(path: Path) -> pd.DataFrame:\n'
        '    if not path.exists():\n'
        '        raise SystemExit(f"missing input: {path}")\n'
        '    return pd.read_csv(path, low_memory=False, encoding="utf-8-sig")\n'
        '\n'
        '\n'
        'def ensure_columns(df: pd.DataFrame, required: list[str], name: str) -> None:\n'
        '    missing = [column for column in required if column not in df.columns]\n'
        '    if missing:\n'
        '        raise SystemExit(f"{name} missing columns: {missing}")\n'
        '\n'
        '\n'
        'def normalize_frames(frames: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:\n'
        '    normalized: dict[str, pd.DataFrame] = {}\n'
        '    for key, value in frames.items():\n'
        '        df = value.copy()\n'
        '        for column in df.columns:\n'
        '            if df[column].dtype == object:\n'
        '                df[column] = df[column].map(normalize_text)\n'
        '        normalized[key] = df\n'
        '    return normalized\n'
        '\n'
        '\n'
        'def first_existing_column(df: pd.DataFrame, candidates: list[str], frame_name: str) -> str:\n'
        '    for candidate in candidates:\n'
        '        if candidate in df.columns:\n'
        '            return candidate\n'
        '    raise SystemExit(f"{frame_name} missing any of columns: {candidates}")\n'
        '\n'
        '\n'
        'def to_numeric_flag(series: pd.Series) -> pd.Series:\n'
        '    return pd.to_numeric(series, errors="coerce").fillna(0)\n'
        '\n'
        '\n'
        'def gpvs_scenario_fields(gpvs_detailed_code: object) -> dict[str, str]:\n'
        '    code = normalize_text(gpvs_detailed_code)\n'
        '    blank = {\n'
        '        "GPVS_시나리오_family_ko": "",\n'
        '        "GPVS_시나리오명_ko": "",\n'
        '        "GPVS_시나리오_고장상황설명_ko": "",\n'
        '        "GPVS_운전모드_ko": "",\n'
        '        "GPVS_해석주의_ko": "",\n'
        '    }\n'
        '    if not code:\n'
        '        return blank\n'
        '\n'
        '    prefix = code[:2] if len(code) >= 2 else ""\n'
        '    suffix = code[-1] if len(code) >= 1 else ""\n'
        '    scenario_meta = GPVS_SCENARIO_FAMILY_MAP.get(prefix)\n'
        '    if scenario_meta is None:\n'
        '        return {\n'
        '            "GPVS_시나리오_family_ko": "",\n'
        '            "GPVS_시나리오명_ko": f"외부 GPVS 시나리오 {code}",\n'
        '            "GPVS_시나리오_고장상황설명_ko": "공식 GPVS 시나리오 map에 직접 등록되지 않은 코드",\n'
        '            "GPVS_운전모드_ko": GPVS_SCENARIO_MODE_MAP.get(suffix, ""),\n'
        '            "GPVS_해석주의_ko": GPVS_SCENARIO_WARNING,\n'
        '        }\n'
        '    return {\n'
        '        "GPVS_시나리오_family_ko": scenario_meta["family"],\n'
        '        "GPVS_시나리오명_ko": scenario_meta["name"],\n'
        '        "GPVS_시나리오_고장상황설명_ko": scenario_meta["description"],\n'
        '        "GPVS_운전모드_ko": GPVS_SCENARIO_MODE_MAP.get(suffix, ""),\n'
        '        "GPVS_해석주의_ko": GPVS_SCENARIO_WARNING,\n'
        '    }\n'
        '\n'
        '\n'
        'def canonical_gpvs_code(gpvs_detailed_code: object) -> str:\n'
        '    code = normalize_text(gpvs_detailed_code).upper()\n'
        '    if len(code) < 2 or not code.startswith("F"):\n'
        '        return ""\n'
        '    canonical = code[:2]\n'
        '    return canonical if canonical in GPVS_FRONT_PATTERN_NAME_MAP else ""\n'
        '\n'
        '\n'
        'def gpvs_front_facing_fields(\n'
        '    *,\n'
        '    panel_fault_status: str,\n'
        '    gpvs_type: str,\n'
        '    gpvs_detailed_code: str,\n'
        '    panel_agreement_row: dict[str, str] | None,\n'
        ') -> dict[str, str]:\n'
        '    blank = {\n'
        '        "GPVS_내부참고유형_ko": "",\n'
        '        "GPVS_외부참조패턴_ko": "",\n'
        '        "GPVS_참조사용등급_ko": "",\n'
        '        "GPVS_참조설명_ko": "",\n'
        '    }\n'
        '    if panel_fault_status != "고장":\n'
        '        return blank\n'
        '\n'
        '    canonical_code = canonical_gpvs_code(gpvs_detailed_code)\n'
        '    internal_type = normalize_text(gpvs_type)\n'
        '    usefulness = ""\n'
        '    if panel_agreement_row is not None:\n'
        '        usefulness = GPVS_REFERENCE_GRADE_MAP.get(\n'
        '            normalize_text(panel_agreement_row.get("overall_gpvs_reference_usefulness_ko", "")),\n'
        '            "",\n'
        '        )\n'
        '\n'
        '    return {\n'
        '        "GPVS_내부참고유형_ko": "" if internal_type in {"", "미부착", "비대상"} else internal_type,\n'
        '        "GPVS_외부참조패턴_ko": GPVS_FRONT_PATTERN_NAME_MAP.get(canonical_code, ""),\n'
        '        "GPVS_참조사용등급_ko": usefulness,\n'
        '        "GPVS_참조설명_ko": GPVS_FRONT_DESCRIPTION_MAP.get(canonical_code, ""),\n'
        '    }\n'
        '\n'
        '\n'
        'def load_inputs(root: Path) -> dict[str, pd.DataFrame]:\n'
        '    share_dir = root / "_share"\n'
        '    frames = {\n'
        '        "workflow": read_csv(share_dir / WORKFLOW_DEFAULT_NAME),\n'
        '        "abrupt6": read_csv(share_dir / ABRUPT6_SYMPTOM_MAP_NAME),\n'
        '        "kernel_map": read_csv(share_dir / KERNELLOG_PROJECT_MAPPING_NAME),\n'
        '        "gpv7": read_csv(share_dir / GPV7_PERF_SUMMARY_NAME),\n'
        '        "final_pack": read_csv(share_dir / FINAL_DECISION_PACK_NAME),\n'
        '        "precursor_truth": read_csv(share_dir / PRECURSOR_ONSET_TRUTH_NAME),\n'
        '        "non_precursor_perf": read_csv(share_dir / NON_PRECURSOR_PERFORMANCE_CASES_NAME),\n'
        '        "common_cause": read_csv(share_dir / COMMON_CAUSE_RETROFIT_NAME),\n'
        '        "gpvs_attach_inventory": read_csv(share_dir / GPVS_ATTACH_INVENTORY_NAME),\n'
        '        "gpvs_attach_feasibility": read_csv(share_dir / GPVS_ATTACH_FEASIBILITY_NAME),\n'
        '        "gpvs_attach_candidates": read_csv(share_dir / GPVS_ATTACH_CANDIDATES_NAME),\n'
        '        "consistency_cases": read_csv(share_dir / PRECURSOR_ABRUPT_CONSISTENCY_CASES_NAME),\n'
        '        "consistency_summary": read_csv(share_dir / PRECURSOR_ABRUPT_CONSISTENCY_SUMMARY_NAME),\n'
        '        "consistency_recommendation": read_csv(share_dir / PRECURSOR_ABRUPT_CONSISTENCY_RECOMMENDATION_NAME),\n'
        '        "forensic_summary": read_csv(share_dir / FORENSIC_SUMMARY_NAME),\n'
        '        "fault_event_audit": read_csv(share_dir / FAULT_PANEL_EVENT_AUDIT_NAME),\n'
        '        "detailed_fault_bridge_audit": read_csv(share_dir / DETAILED_FAULT_BRIDGE_AUDIT_NAME),\n'
        '        "detailed_fault_bridge_summary": read_csv(share_dir / DETAILED_FAULT_BRIDGE_SUMMARY_NAME),\n'
        '        "gpvs_bytype_rebuild_summary": read_csv(share_dir / GPVS_BYTYPE_REBUILD_SUMMARY_NAME),\n'
        '        "gpvs_detailed_type_audit": read_csv(share_dir / GPVS_DETAILED_TYPE_INFERENCE_AUDIT_NAME),\n'
        '        "gpvs_detailed_type_realpanel_sanity": read_csv(share_dir / GPVS_DETAILED_TYPE_REALPANEL_SANITY_NAME),\n'
        '        "gpvs_mlpe_panel_agreement": read_csv(share_dir / GPVS_MLPE_PANEL_AGREEMENT_NAME),\n'
        '        "gpvs_canonical_dictionary": read_csv(share_dir / GPVS_CANONICAL_DICTIONARY_NAME),\n'
        '        "gpvs_mlpe_fault_matching": read_csv(share_dir / GPVS_MLPE_FAULT_MATCHING_TABLE_NAME),\n'
        '        "gpvs_mlpe_compatibility_summary": read_csv(share_dir / GPVS_MLPE_COMPATIBILITY_SUMMARY_NAME),\n'
        '    }\n'
        '\n'
        '    ensure_columns(\n'
        '        frames["workflow"],\n'
        '        [\n'
        '            "preview_attention_class",\n'
        '            "site",\n'
        '            "display_entity_id",\n'
        '            "display_shape_or_cluster_kind",\n'
        '            "display_status_or_tier",\n'
        '            "display_score",\n'
        '            "workflow_reason_ko",\n'
        '        ],\n'
        '        WORKFLOW_DEFAULT_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["abrupt6"],\n'
        '        [\n'
        '            "site",\n'
        '            "panel_id",\n'
        '            "고장시점",\n'
        '            "사건유형_ko",\n'
        '            "최종고장양상_ko",\n'
        '            "순수급작_flag",\n'
        '            "증상명_ko",\n'
        '            "세부근거_ko",\n'
        '            "source_field_ko",\n'
        '            "비고_ko",\n'
        '        ],\n'
        '        ABRUPT6_SYMPTOM_MAP_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["kernel_map"],\n'
        '        ["커널로그_증상명", "주_프로젝트분류", "보조_프로젝트분류", "설명_ko", "주의_ko"],\n'
        '        KERNELLOG_PROJECT_MAPPING_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["gpv7"],\n'
        '        ["고장유형_번호", "고장유형_설명_ko", "성능요약_ko", "수치_ko", "source_ref_ko"],\n'
        '        GPV7_PERF_SUMMARY_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["final_pack"],\n'
        '        ["eval_scope", "current_data_decision", "final_usage_decision", "final_reason_ko"],\n'
        '        FINAL_DECISION_PACK_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["precursor_truth"],\n'
        '        [\n'
        '            "site",\n'
        '            "panel_id",\n'
        '            "preferred_precursor_onset_date",\n'
        '            "operational_first_precursor_detected_date",\n'
        '            "operational_first_precursor_marker_name",\n'
        '            "interpretive_precursor_onset_date",\n'
        '            "benchmark_precursor_onset_date",\n'
        '        ],\n'
        '        PRECURSOR_ONSET_TRUTH_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["non_precursor_perf"],\n'
        '        ["eval_bucket_v2", "site", "panel_id"],\n'
        '        NON_PRECURSOR_PERFORMANCE_CASES_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["common_cause"],\n'
        '        [\n'
        '            "eval_bucket_v2",\n'
        '            "site",\n'
        '            "panel_id",\n'
        '            "current_marker_only_flag",\n'
        '            "breadth_marker_only_flag",\n'
        '            "combined_marker_flag",\n'
        '        ],\n'
        '        COMMON_CAUSE_RETROFIT_NAME,\n'
        '    )\n'
        '    ensure_columns(\n'
        '        frames["gpvs_attach_inventory"],\n'
        '        [\n'
        '            "경로",\n'
        '            "존재여부",\n'
        '            "granularity_ko",\n'
        '            "panel_id_컬럼존재_flag",\n'
