        '\n'
        'def validate_inputs(root: Path, frames: dict[str, pd.DataFrame]) -> None:\n'
        '    workflow_df = frames["workflow"]\n'
        '    kernel_map_df = frames["kernel_map"]\n'
        '    final_pack_df = frames["final_pack"]\n'
        '\n'
        '    preview_values = set(workflow_df["preview_attention_class"].tolist())\n'
        '    if not PANEL_LEVEL_PREVIEW_CLASSES.issubset(preview_values):\n'
        '        missing = sorted(PANEL_LEVEL_PREVIEW_CLASSES - preview_values)\n'
        '        raise SystemExit(f"{WORKFLOW_DEFAULT_NAME} missing queue/watch rows: {missing}")\n'
        '\n'
        '    required_kernel_symptoms = {"출력 저하형", "전압 변화형", "패턴 이상형", "불안정형", "복합형"}\n'
        '    missing_symptoms = required_kernel_symptoms - set(kernel_map_df["커널로그_증상명"].tolist())\n'
        '    if missing_symptoms:\n'
        '        raise SystemExit(f"{KERNELLOG_PROJECT_MAPPING_NAME} missing required symptom rows: {sorted(missing_symptoms)}")\n'
        '\n'
        '    final_scopes = set(final_pack_df["eval_scope"].tolist())\n'
        '    missing_scopes = EXPECTED_FINAL_SCOPES - final_scopes\n'
        '    if missing_scopes:\n'
        '        raise SystemExit(f"{FINAL_DECISION_PACK_NAME} missing required scopes: {sorted(missing_scopes)}")\n'
        '\n'
        '    feasibility_df = frames["gpvs_attach_feasibility"]\n'
        '    if len(feasibility_df) != 1:\n'
        '        raise SystemExit(f"{GPVS_ATTACH_FEASIBILITY_NAME} must contain exactly one row, found {len(feasibility_df)}")\n'
        '    feasibility_value = normalize_text(feasibility_df.iloc[0]["GPVS_패널별_직접판정_가능여부"])\n'
        '    if feasibility_value not in {"가능", "불가"}:\n'
        '        raise SystemExit(\n'
        '            f"{GPVS_ATTACH_FEASIBILITY_NAME} has invalid GPVS_패널별_직접판정_가능여부: {feasibility_value}"\n'
        '        )\n'
        '    overlap_value = pd.to_numeric(feasibility_df.iloc[0]["overlap_panel_count"], errors="coerce")\n'
        '    if pd.isna(overlap_value):\n'
        '        raise SystemExit(f"{GPVS_ATTACH_FEASIBILITY_NAME} overlap_panel_count must be numeric")\n'
        '    candidates_df = frames["gpvs_attach_candidates"]\n'
        '    if feasibility_value == "가능" and candidates_df.empty:\n'
        '        raise SystemExit(f"{GPVS_ATTACH_CANDIDATES_NAME} is empty despite feasibility=가능")\n'
        '    if feasibility_value == "불가" and not candidates_df.empty:\n'
        '        raise SystemExit(f"{GPVS_ATTACH_CANDIDATES_NAME} must be empty when feasibility=불가")\n'
        '    if not candidates_df.empty and candidates_df.duplicated(subset=["site", "panel_id"]).any():\n'
        '        dup = candidates_df.loc[candidates_df.duplicated(subset=["site", "panel_id"], keep=False), ["site", "panel_id"]]\n'
        '        raise SystemExit(f"{GPVS_ATTACH_CANDIDATES_NAME} must be unique by (site, panel_id): {dup.to_dict(orient=\'records\')[:5]}")\n'
        '    if frames["gpvs_attach_inventory"].empty:\n'
        '        raise SystemExit(f"{GPVS_ATTACH_INVENTORY_NAME} must not be empty")\n'
        '    if len(frames["detailed_fault_bridge_summary"]) != 1:\n'
        '        raise SystemExit(\n'
        '            f"{DETAILED_FAULT_BRIDGE_SUMMARY_NAME} must contain exactly one row, found {len(frames[\'detailed_fault_bridge_summary\'])}"\n'
        '        )\n'
        '    if len(frames["gpvs_bytype_rebuild_summary"]) != 1:\n'
        '        raise SystemExit(\n'
        '            f"{GPVS_BYTYPE_REBUILD_SUMMARY_NAME} must contain exactly one row, found {len(frames[\'gpvs_bytype_rebuild_summary\'])}"\n'
        '        )\n'
        '    if len(frames["gpvs_mlpe_compatibility_summary"]) != 1:\n'
        '        raise SystemExit(\n'
        '            f"{GPVS_MLPE_COMPATIBILITY_SUMMARY_NAME} must contain exactly one row, found {len(frames[\'gpvs_mlpe_compatibility_summary\'])}"\n'
        '        )\n'
        '    compatibility_recommendation = normalize_text(\n'
        '        frames["gpvs_mlpe_compatibility_summary"].iloc[0]["final_recommendation_ko"]\n'
