        '        )\n'
        '\n'
        '\n'
        'def load_same_event_overlap_keys(frames: dict[str, pd.DataFrame]) -> set[tuple[str, str]]:\n'
        '    recommendation_df = frames["consistency_recommendation"]\n'
        '    if len(recommendation_df) != 1:\n'
        '        raise SystemExit(\n'
        '            f"{PRECURSOR_ABRUPT_CONSISTENCY_RECOMMENDATION_NAME} must contain exactly one row, found {len(recommendation_df)}"\n'
        '        )\n'
