        '    if recommendation != "relabel_overlap_as_precursor_led_faults":\n'
        '        raise SystemExit(\n'
        '            "precursor/abrupt consistency recommendation must be relabel_overlap_as_precursor_led_faults for panel verdict reconciliation; "\n'
        '            f"got {recommendation or \'<blank>\'}"\n'
        '        )\n'
        '\n'
        '    cases_df = frames["consistency_cases"]\n'
        '    same_event_df = cases_df.loc[pd.to_numeric(cases_df["same_event_flag"], errors="coerce").fillna(0).eq(1)].copy()\n'
        '    overlap_keys = {\n'
        '        (normalize_text(row["site"]), normalize_text(row["panel_id"]))\n'
