        '        if normalize_text(row["site"]) and normalize_text(row["panel_id"])\n'
        '    }\n'
        '    summary_row = frames["consistency_summary"].iloc[0].to_dict()\n'
        '    expected_overlap = int(pd.to_numeric(summary_row["overlap_panel_count"], errors="raise"))\n'
        '    expected_same = int(pd.to_numeric(summary_row["same_event_count"], errors="raise"))\n'
        '    corrected_pure_abrupt = int(pd.to_numeric(summary_row["corrected_pure_abrupt_fault_count"], errors="raise"))\n'
        '    if expected_overlap != expected_same:\n'
        '        raise SystemExit(\n'
        '            f"{PRECURSOR_ABRUPT_CONSISTENCY_SUMMARY_NAME} must keep overlap_panel_count == same_event_count for this reconciliation"\n'
        '        )\n'
        '    if len(overlap_keys) != expected_same:\n'
        '        raise SystemExit(\n'
        '            f"same-event overlap count mismatch between cases and summary: cases={len(overlap_keys)}, summary={expected_same}"\n'
        '        )\n'
        '    if len(overlap_keys) != 2:\n'
        '        raise SystemExit(f"expected current same-event overlap panel count to be 2, found {len(overlap_keys)}")\n'
        '    if corrected_pure_abrupt != 4:\n'
        '        raise SystemExit(f"expected corrected pure abrupt fault count to be 4, found {corrected_pure_abrupt}")\n'
        '    return overlap_keys\n'
        '\n'
        '\n'
        'def load_forensic_rule_case(frames: dict[str, pd.DataFrame]) -> dict[str, str]:\n'
        '    forensic_df = frames["forensic_summary"].copy()\n'
        '    target_df = forensic_df.loc[\n'
        '        forensic_df["site"].eq(FORENSIC_RULE_SITE)\n'
        '        & forensic_df["panel_id"].eq(FORENSIC_RULE_PANEL_ID)\n'
