        '        )\n'
        '    row = {key: normalize_text(value) for key, value in target_df.iloc[0].to_dict().items()}\n'
        '    onset_date = normalize_text(row.get("earliest_onset_date")) or normalize_text(row.get("전조흔적_시작일"))\n'
        '    trigger_date = normalize_text(row.get("strong_trigger_date")) or normalize_text(row.get("강한트리거일"))\n'
        '    if onset_date != FORENSIC_RULE_ONSET_DATE or trigger_date != FORENSIC_RULE_TRIGGER_DATE:\n'
        '        raise SystemExit(\n'
