        '        raise SystemExit(f"{FAULT_PANEL_EVENT_AUDIT_NAME} must be unique by (site, panel_id): {dup.to_dict(orient=\'records\')[:5]}")\n'
        '\n'
        '    lookup: dict[tuple[str, str], dict[str, str]] = {}\n'
        '    for row in audit_df.to_dict(orient="records"):\n'
