        'def precursor_truth_lookup(precursor_df: pd.DataFrame) -> dict[tuple[str, str], dict[str, str]]:\n'
        '    panel_col = first_existing_column(\n'
        '        precursor_df,\n'
        '        ["panel_id", "display_entity_id", "entity_id", "panel_entity_id"],\n'
        '        PRECURSOR_ONSET_TRUTH_NAME,\n'
