        '    lookup: dict[tuple[str, str], dict[str, str]] = {}\n'
        '    for row in positive_df.to_dict(orient="records"):\n'
        '        key = (normalize_text(row["site"]), normalize_text(row[panel_col]))\n'
        '        lookup[key] = {column: normalize_text(value) for column, value in row.items()}\n'
        '    return lookup\n'
        '\n'
        '\n'
        'def build_abrupt_eval_keys(non_precursor_df: pd.DataFrame) -> set[tuple[str, str]]:\n'
        '    positive_df = non_precursor_df.loc[\n'
        '        non_precursor_df["eval_bucket_v2"].eq("abrupt_or_no_precursor_now")\n'
        '    ].copy()\n'
        '    keys = panel_key_set(positive_df, "site", "panel_id")\n'
        '    if not keys:\n'
        '        raise SystemExit(\n'
        '            f"{NON_PRECURSOR_PERFORMANCE_CASES_NAME} has no abrupt_or_no_precursor_now rows"\n'
        '        )\n'
        '    return keys\n'
        '\n'
        '\n'
        'def build_common_cause_positive_keys(common_df: pd.DataFrame) -> set[tuple[str, str]]:\n'
        '    marker_mask = (\n'
        '        to_numeric_flag(common_df["current_marker_only_flag"]).eq(1)\n'
        '        | to_numeric_flag(common_df["breadth_marker_only_flag"]).eq(1)\n'
        '        | to_numeric_flag(common_df["combined_marker_flag"]).eq(1)\n'
        '    )\n'
        '    positive_df = common_df.loc[common_df["eval_bucket_v2"].eq("non_panel_or_common_cause") & marker_mask].copy()\n'
        '    keys = panel_key_set(positive_df, "site", "panel_id")\n'
        '    if not keys:\n'
        '        raise SystemExit(\n'
        '            f"{COMMON_CAUSE_RETROFIT_NAME} has no non_panel_or_common_cause positive rows with current/breadth/combined marker evidence"\n'
        '        )\n'
        '    return keys\n'
        '\n'
        '\n'
        'def workflow_lookup(workflow_panel_df: pd.DataFrame) -> dict[tuple[str, str], dict[str, object]]:\n'
        '    return {\n'
        '        (normalize_text(row["site"]), normalize_text(row["display_entity_id"])): row\n'
        '        for row in workflow_panel_df.to_dict(orient="records")\n'
        '    }\n'
        '\n'
        '\n'
        'def current_data_scope_note(\n'
        '    event_type: str,\n'
        '    terminal_pattern: str,\n'
        '    final_pack_by_scope: dict[str, dict[str, object]],\n'
        ') -> str:\n'
        '    if event_type == "전조형 고장" and terminal_pattern == "급격 종료":\n'
        '        return "이 panel은 전조형 사건 한 건이 마지막에 급격 종료로 끝난 것으로 읽는다. event type과 terminal failure pattern은 분리해서 해석해야 한다."\n'
        '    scope = SCOPE_BY_EVENT_TYPE.get(event_type, "")\n'
        '    if scope:\n'
        '        final_row = final_pack_by_scope.get(scope, {})\n'
        '        final_usage = normalize_text(final_row.get("final_usage_decision", ""))\n'
        '        if final_usage == "bounded_reporting_use":\n'
        '            return f"{event_type} 축은 current closeout 기준 bounded current-data 수준으로만 읽는다."\n'
        '        if final_usage == "exploratory_only":\n'
        '            return f"{event_type} 축은 current closeout 기준 exploratory 범위로만 읽는다."\n'
        '    if event_type == "반복 이상":\n'
        '        return "반복 이상은 chronic monitor/반복 lane 해석이며 stable fault classifier claim이 아니다."\n'
        '    if event_type == "불충분":\n'
        '        return "현재 stored positive universe와 직접 연결되지 않아 사건 성격을 보수적으로 유지한다."\n'
        '    return "현재 저장 산출물만으로는 사건 성격 판정 근거가 제한적이다."\n'
        '\n'
        '\n'
        'def event_type_and_terminal_pattern(\n'
        '    flags: dict[str, int],\n'
        '    *,\n'
        '    is_same_event_overlap: bool,\n'
        '    forensic_rule_case: dict[str, str] | None,\n'
        '    fault_audit_row: dict[str, str] | None,\n'
        ') -> tuple[str, str]:\n'
        '    if fault_audit_row is not None:\n'
        '        return (\n'
        '            normalize_text(fault_audit_row["사건유형_재판정_ko"]) or "불충분",\n'
        '            normalize_text(fault_audit_row["최종고장양상_재판정_ko"]) or "불충분",\n'
        '        )\n'
        '    if forensic_rule_case is not None:\n'
        '        return (\n'
        '            normalize_text(forensic_rule_case["사건유형_결정_ko"]) or "불충분",\n'
        '            normalize_text(forensic_rule_case["최종고장양상_결정_ko"]) or "불충분",\n'
        '        )\n'
        '    if is_same_event_overlap:\n'
        '        return ("전조형 고장", "급격 종료")\n'
        '    if flags["has_급작고장"]:\n'
        '        return ("급작 고장", "급작 발생")\n'
        '    if flags["has_전조형고장"]:\n'
        '        return ("전조형 고장", "진행성 악화")\n'
        '    if flags["has_공통원인이벤트"]:\n'
        '        return ("공통원인 이벤트", "해당없음")\n'
        '    if flags["has_반복이상"]:\n'
        '        return ("반복 이상", "해당없음")\n'
        '    return ("불충분", "불충분")\n'
        '\n'
        '\n'
        'def panel_fault_status_from_event_type(event_type: str) -> str:\n'
        '    if event_type in {"전조형 고장", "급작 고장", "고장유형 보류"}:\n'
        '        return "고장"\n'
        '    if event_type == "공통원인 이벤트":\n'
        '        return "비고장"\n'
        '    return "미확정"\n'
        '\n'
        '\n'
        'def gpvs_applicability_from_fault_status(panel_fault_status: str) -> str:\n'
        '    return "적용대상" if panel_fault_status == "고장" else "비대상"\n'
        '\n'
        '\n'
        'def event_history_text(\n'
        '    flags: dict[str, int],\n'
        '    *,\n'
        '    is_same_event_overlap: bool,\n'
        '    forensic_rule_case: dict[str, str] | None,\n'
        '    fault_audit_row: dict[str, str] | None,\n'
        ') -> str:\n'
        '    if fault_audit_row is not None:\n'
        '        event_type = normalize_text(fault_audit_row["사건유형_재판정_ko"])\n'
        '        terminal_pattern = normalize_text(fault_audit_row["최종고장양상_재판정_ko"])\n'
        '        if event_type == "급작 고장" and terminal_pattern == "급작 발생":\n'
        '            return event_type\n'
        '        if event_type == "전조형 고장" and terminal_pattern == "진행성 악화":\n'
        '            return event_type\n'
        '        if event_type and terminal_pattern and terminal_pattern not in {"불충분", "해당없음"}:\n'
        '            return f"{event_type}({terminal_pattern})"\n'
        '        return event_type\n'
        '    if forensic_rule_case is not None:\n'
        '        event_type = normalize_text(forensic_rule_case["사건유형_결정_ko"])\n'
        '        terminal_pattern = normalize_text(forensic_rule_case["최종고장양상_결정_ko"])\n'
        '        if event_type and terminal_pattern and terminal_pattern != "불충분":\n'
        '            return f"{event_type}({terminal_pattern})"\n'
        '        return event_type\n'
        '    members: list[str] = []\n'
        '    if flags["has_전조형고장"]:\n'
        '        if is_same_event_overlap:\n'
        '            members.append("전조형 고장(급격 종료)")\n'
        '        else:\n'
        '            members.append("전조형 고장")\n'
        '    if flags["has_급작고장"]:\n'
        '        members.append("급작 고장")\n'
        '    if flags["has_공통원인이벤트"]:\n'
        '        members.append("공통원인 이벤트")\n'
        '    if flags["has_반복이상"]:\n'
        '        members.append("반복 이상")\n'
        '    return "+".join(members)\n'
        '\n'
        '\n'
        'def interpretation_layer_fields(\n'
        '    flags: dict[str, int],\n'
        '    event_type: str,\n'
        '    *,\n'
        '    precursor_eval_flag: int,\n'
        '    abrupt_eval_flag: int,\n'
        '    is_same_event_overlap: bool,\n'
        '    forensic_rule_case: dict[str, str] | None,\n'
        '    fault_audit_row: dict[str, str] | None,\n'
        ') -> dict[str, object]:\n'
        '    def mismatch_text_for(event_type_ko: str, precursor_flag: int, abrupt_flag: int) -> str:\n'
        '        if event_type_ko == "전조형 고장" and precursor_flag == 0:\n'
        '            return "explicit rule상 전조형 고장이지만 현재 strict precursor evaluation set에는 아직 미편입"\n'
        '        if event_type_ko == "급작 고장" and abrupt_flag == 0:\n'
        '            return "explicit rule상 급작 고장이지만 현재 pure abrupt evaluation set에는 아직 미편입"\n'
        '        return ""\n'
        '\n'
        '    if fault_audit_row is not None:\n'
        '        event_type_ko = normalize_text(fault_audit_row["사건유형_재판정_ko"]) or event_type\n'
        '        return {\n'
        '            "사건유형_해석_ko": event_type_ko,\n'
        '            "전조흔적_flag": int(pd.to_numeric(pd.Series([fault_audit_row["전조흔적_flag"]]), errors="coerce").fillna(0).iloc[0]),\n'
        '            "순수급작_flag": int(pd.to_numeric(pd.Series([fault_audit_row["순수급작_flag"]]), errors="coerce").fillna(0).iloc[0]),\n'
        '            "전조평가셋편입_flag": precursor_eval_flag,\n'
        '            "급작평가셋편입_flag": abrupt_eval_flag,\n'
        '            "해석대평가차이_ko": mismatch_text_for(event_type_ko, precursor_eval_flag, abrupt_eval_flag),\n'
        '        }\n'
        '    if is_same_event_overlap:\n'
        '        return {\n'
        '            "사건유형_해석_ko": "전조형 고장",\n'
        '            "전조흔적_flag": 1,\n'
        '            "순수급작_flag": 0,\n'
        '            "전조평가셋편입_flag": precursor_eval_flag,\n'
        '            "급작평가셋편입_flag": abrupt_eval_flag,\n'
        '            "해석대평가차이_ko": mismatch_text_for("전조형 고장", precursor_eval_flag, abrupt_eval_flag),\n'
        '        }\n'
        '    if forensic_rule_case is not None:\n'
        '        event_type_ko = normalize_text(forensic_rule_case["사건유형_결정_ko"]) or event_type\n'
        '        return {\n'
        '            "사건유형_해석_ko": event_type_ko,\n'
        '            "전조흔적_flag": 1,\n'
        '            "순수급작_flag": 0,\n'
        '            "전조평가셋편입_flag": precursor_eval_flag,\n'
        '            "급작평가셋편입_flag": abrupt_eval_flag,\n'
        '            "해석대평가차이_ko": mismatch_text_for(event_type_ko, precursor_eval_flag, abrupt_eval_flag),\n'
        '        }\n'
        '    if flags["has_급작고장"]:\n'
        '        return {\n'
        '            "사건유형_해석_ko": "급작 고장",\n'
        '            "전조흔적_flag": 0,\n'
        '            "순수급작_flag": 1,\n'
        '            "전조평가셋편입_flag": precursor_eval_flag,\n'
        '            "급작평가셋편입_flag": abrupt_eval_flag,\n'
        '            "해석대평가차이_ko": mismatch_text_for("급작 고장", precursor_eval_flag, abrupt_eval_flag),\n'
        '        }\n'
        '    if flags["has_전조형고장"]:\n'
        '        return {\n'
        '            "사건유형_해석_ko": "전조형 고장",\n'
        '            "전조흔적_flag": 1,\n'
        '            "순수급작_flag": 0,\n'
        '            "전조평가셋편입_flag": precursor_eval_flag,\n'
        '            "급작평가셋편입_flag": abrupt_eval_flag,\n'
        '            "해석대평가차이_ko": mismatch_text_for("전조형 고장", precursor_eval_flag, abrupt_eval_flag),\n'
        '        }\n'
        '    return {\n'
        '        "사건유형_해석_ko": event_type,\n'
        '        "전조흔적_flag": 0,\n'
        '        "순수급작_flag": 0,\n'
        '        "전조평가셋편입_flag": precursor_eval_flag,\n'
        '        "급작평가셋편입_flag": abrupt_eval_flag,\n'
        '        "해석대평가차이_ko": mismatch_text_for(event_type, precursor_eval_flag, abrupt_eval_flag),\n'
        '    }\n'
        '\n'
        '\n'
        'def map_kernel_axis(\n'
        '    event_type: str,\n'
        '    abrupt_row: dict[str, object] | None,\n'
        ') -> tuple[str, str, str]:\n'
        '    if abrupt_row is not None:\n'
        '        specific = normalize_text(abrupt_row["증상명_ko"]) or "불충분"\n'
        '        broad = SPECIFIC_TO_BROAD_SYMPTOM.get(specific, "불충분")\n'
        '        note = (\n'
        '            f"커널로그 원인군은 abrupt6 symptom map의 `{specific}` 를 연결했다."\n'
        '            if specific != "불충분"\n'
        '            else "abrupt6 direct map가 있지만 stored symptom name이 불충분하다."\n'
        '        )\n'
        '        return broad, specific, note\n'
        '\n'
        '    if event_type == "전조형 고장":\n'
        '        return "출력 저하형", "불충분", "전조형 representative verdict라 nearest symptom 축으로 출력 저하형만 부착했다."\n'
        '    if event_type == "공통원인 이벤트":\n'
        '        return "패턴 이상형", "불충분", "공통원인 representative verdict라 nearest symptom 축으로 패턴 이상형만 부착했다."\n'
        '    if event_type == "반복 이상":\n'
        '        return "불안정형", "불충분", "watch_now_panel 반복 lane이라 nearest symptom 축으로 불안정형만 부착했다."\n'
        '    return "불충분", "불충분", "현재 stored field로 커널로그 증상축을 더 붙이기 어렵다."\n'
        '\n'
        '\n'
        'def map_operating_location(workflow_row: dict[str, object] | None) -> str:\n'
        '    if workflow_row is None:\n'
        '        return "현재 workflow 미포함"\n'
        '    preview_class = normalize_text(workflow_row["preview_attention_class"])\n'
        '    if preview_class == "queue_run":\n'
        '        return "바로 확인"\n'
        '    if preview_class == "watch_now_panel":\n'
        '        return "경과 관찰"\n'
        '    return "현재 workflow 미포함"\n'
        '\n'
        '\n'
        'def recover_gpvs_panel_level_reference_from_audit(\n'
        '    feasibility_df: pd.DataFrame,\n'
        '    candidates_df: pd.DataFrame,\n'
        '    panel_keys: set[tuple[str, str]],\n'
        ') -> tuple[dict[tuple[str, str], dict[str, str]], dict[str, str], int]:\n'
        '    feasibility_row = feasibility_df.iloc[0]\n'
        '    feasibility_value = normalize_text(feasibility_row["GPVS_패널별_직접판정_가능여부"])\n'
        '    overlap_expected = int(pd.to_numeric(feasibility_row["overlap_panel_count"], errors="raise"))\n'
        '    best_source = normalize_text(feasibility_row["최선_후보_파일"])\n'
        '    feasibility_reason = normalize_text(feasibility_row["근거_ko"])\n'
        '\n'
        '    if feasibility_value == "불가":\n'
        '        return (\n'
        '            {},\n'
        '            {\n'
        '                "feasibility": feasibility_value,\n'
        '                "best_source": best_source,\n'
        '                "feasibility_reason": feasibility_reason,\n'
        '            },\n'
        '            0,\n'
        '        )\n'
        '\n'
        '    gpvs_lookup: dict[tuple[str, str], dict[str, str]] = {}\n'
        '    for row in candidates_df.to_dict(orient="records"):\n'
        '        key = (normalize_text(row["site"]), normalize_text(row["panel_id"]))\n'
        '        if key not in panel_keys:\n'
        '            continue\n'
        '        source_path = normalize_text(row["source_path"])\n'
        '        source_key = normalize_text(row["source_key_ko"])\n'
        '        note = normalize_text(row["비고_ko"])\n'
        '        reason_parts = [part for part in [source_path, source_key, note] if part]\n'
        '        gpvs_lookup[key] = {\n'
        '            "GPVS_참고유형_ko": normalize_text(row["GPVS_참고유형_ko"]) or "미부착",\n'
        '            "GPVS_근거_ko": " | ".join(reason_parts) if reason_parts else GPVS_ABSENCE_REASON,\n'
        '            "GPVS_후보파일_ko": source_path,\n'
        '        }\n'
        '\n'
        '    return (\n'
        '        gpvs_lookup,\n'
        '        {\n'
        '            "feasibility": feasibility_value,\n'
        '            "best_source": best_source,\n'
        '            "feasibility_reason": feasibility_reason,\n'
        '        },\n'
        '        overlap_expected,\n'
        '    )\n'
        '\n'
        '\n'
        'def gpvs_unattached_reason(\n'
        '    inventory_df: pd.DataFrame,\n'
        '    feasibility_meta: dict[str, str],\n'
        ') -> str:\n'
        '    feasibility_value = normalize_text(feasibility_meta.get("feasibility", ""))\n'
        '    best_source = normalize_text(feasibility_meta.get("best_source", ""))\n'
        '    inventory = inventory_df.copy()\n'
        '    inventory["panel_attach_candidate_flag"] = to_numeric_flag(inventory["panel_attach_candidate_flag"])\n'
        '\n'
        '    if feasibility_value == "가능" and (\n'
        '        best_source\n'
        '        or inventory["panel_attach_candidate_flag"].eq(1).any()\n'
        '    ):\n'
        '        return "GPVS 패널수준 후보 파일은 있으나 이 패널 key가 없음"\n'
        '\n'
        '    key_poor_mask = inventory["panel_attach_candidate_flag"].eq(0) & inventory["granularity_ko"].isin(["유형수준", "집계수준"])\n'
        '    if key_poor_mask.any():\n'
        '        return "GPVS 결과는 있으나 패널수준 key가 없음"\n'
        '\n'
        '    return "패널수준 GPVS 산출물 없음"\n'
        '\n'
        '\n'
        'def detailed_fault_type_label(code: str) -> str:\n'
        '    normalized = normalize_text(code)\n'
        '    if len(normalized) >= 2 and normalized[0] == "F" and normalized[1].isdigit():\n'
        '        family_idx = normalized[1]\n'
        '        if family_idx in {"1", "2", "3", "4", "5", "6", "7"}:\n'
        '            return f"GPVS Fault{family_idx}"\n'
        '    return normalized\n'
        '\n'
        '\n'
        'def detailed_fault_bridge_lookup(\n'
        '    audit_df: pd.DataFrame,\n'
        '    summary_df: pd.DataFrame,\n'
        ') -> tuple[dict[tuple[str, str], dict[str, str]], dict[str, int | str]]:\n'
        '    if audit_df[["site", "panel_id"]].duplicated().any():\n'
        '        dup = audit_df.loc[audit_df[["site", "panel_id"]].duplicated(keep=False), ["site", "panel_id"]]\n'
        '        raise SystemExit(\n'
        '            f"{DETAILED_FAULT_BRIDGE_AUDIT_NAME} must be unique by (site, panel_id): {dup.to_dict(orient=\'records\')[:5]}"\n'
        '        )\n'
        '    lookup: dict[tuple[str, str], dict[str, str]] = {}\n'
        '    for row in audit_df.to_dict(orient="records"):\n'
        '        key = (normalize_text(row["site"]), normalize_text(row["panel_id"]))\n'
        '        lookup[key] = {column: normalize_text(value) for column, value in row.items()}\n'
