        '    for row in sanity_df.to_dict(orient="records"):\n'
        '        key = (normalize_text(row["site"]), normalize_text(row["panel_id"]))\n'
        '        sanity_lookup[key] = {column: normalize_text(value) for column, value in row.items()}\n'
        '\n'
        '    if len(audit_lookup) != 6:\n'
        '        raise SystemExit(f"{GPVS_DETAILED_TYPE_INFERENCE_AUDIT_NAME} must contain current fault panel 6 rows, found {len(audit_lookup)}")\n'
        '    if len(sanity_lookup) != 6:\n'
        '        raise SystemExit(f"{GPVS_DETAILED_TYPE_REALPANEL_SANITY_NAME} must contain current fault panel 6 rows, found {len(sanity_lookup)}")\n'
        '\n'
        '    summary_row = rebuild_summary_df.iloc[0]\n'
        '    attachable_flag = int(pd.to_numeric(summary_row["current_recovered_attachable_flag"], errors="raise"))\n'
        '    recovered_exported_flag = int(pd.to_numeric(summary_row["recovered_model_exported_flag"], errors="raise"))\n'
        '    parity_status = normalize_text(summary_row["parity_overall_status_ko"])\n'
        '    note_ko = normalize_text(summary_row["note_ko"])\n'
