        '        model_source = normalize_text(audit_row.get("gpvs_detailed_model_source", ""))\n'
        '        guard_ok = (\n'
        '            attachable_flag == 1\n'
        '            and model_source == "recovered_artifact"\n'
        '            and attach_recommendation == "attach_ok"\n'
