        '        merged = dict(audit_row)\n'
        '        merged["attach_recommendation_ko"] = attach_recommendation\n'
        '        merged["__guard_ok"] = "1" if guard_ok else "0"\n'
        '        lookup[key] = merged\n'
        '        if guard_ok:\n'
        '            attached_expected += 1\n'
        '        else:\n'
        '            deferred_expected += 1\n'
        '\n'
        '    return lookup, {\n'
