        '    sys.path.insert(0, str(REPO_ROOT))\n'
        '\n'
        'from research.prognostics import runtime_rawonly_chain_common_v1 as common\n'
        '\n'
        '\n'
        'AUDIT_COLS = [\n'
        '    "site",\n'
        '    "panel_id",\n'
        '    "현재표_사건유형_ko",\n'
        '    "현재표_최종고장양상_ko",\n'
