        '    "degradation_onset_backdate_guard_flag",\n'
        '    "degradation_onset_backdate_guard_name",\n'
        '    "degradation_onset_backdate_guard_reason",\n'
        '    "degradation_onset_backdate_guard_degrade_days",\n'
