        '    "g1_suppressed_event_shadow_current_final_pattern_ko",\n'
        '    "g1_suppressed_event_shadow_event_type_if_applied_ko",\n'
        '    "g1_suppressed_event_shadow_final_pattern_if_applied_ko",\n'
        '    "g1_suppressed_event_shadow_transition_class",\n'
        '    "g1_suppressed_event_shadow_reason",\n'
        '    "g1_suppressed_event_guard_applied_flag",\n'
        '    "g1_suppressed_event_guard_apply_reason",\n'
        '    "secondary_window_candidate_flag",\n'
        '    "secondary_window_selected_onset_date",\n'
        '    "secondary_window_selected_marker",\n'
        '    "secondary_window_selected_gap_days",\n'
        '    "secondary_window_qualified_count",\n'
        '    "secondary_window_too_early_count",\n'
        '    "secondary_window_change_class",\n'
        '    "secondary_window_review_tier",\n'
        '    "secondary_window_reason",\n'
        '    "promotion_decision_bucket",\n'
        '    "promotion_decision_reason",\n'
        '    "common_cause_anchor_date",\n'
        '    "common_cause_anchor_kind",\n'
        '    "site_event_history_flag",\n'
        '    "group_off_history_flag",\n'
        '    "subgroup_common_cause_history_flag",\n'
        '    "common_cause_history_flag",\n'
        '    "strict_trigger_proximal_common_cause_flag",\n'
        '    "warning_proximal_common_cause_flag",\n'
        '    "trigger_proximal_common_cause_flag",\n'
        '    "fault_family_hypothesis_shadow_ko",\n'
        '    "fault_subtype_hypothesis_shadow_ko",\n'
        '    "subtype_evidence_tags",\n'
        '    "subtype_confidence_shadow",\n'
        '    "subtype_shape_confidence_shadow",\n'
        '    "subtype_promotion_blocker_shadow",\n'
        '    "subtype_promotion_blocker_detail_shadow",\n'
        '    "subtype_promotion_blocker_reason_ko",\n'
        '    "subtype_hold_reason_ko",\n'
        '    "subtype_production_write_allowed",\n'
        ']\n'
        'SUMMARY_COLS = [\n'
        '    "전체_패널수",\n'
        '    "고장_패널수",\n'
        '    "비고장_패널수",\n'
        '    "미확정_패널수",\n'
        '    "전조형_고장수",\n'
        '    "급작_고장수",\n'
        '    "전조평가셋_패널수",\n'
        '    "급작평가셋_패널수",\n'
        '    "algorithm_family_다이오드형_패널수",\n'
        '    "algorithm_family_개방장치이상형_패널수",\n'
        '    "algorithm_family_모듈손상형_패널수",\n'
        '    "algorithm_family_불충분_패널수",\n'
        '    "secondary_window_candidate_패널수",\n'
        '    "secondary_window_trigger_only_to_precursor_패널수",\n'
        '    "secondary_window_review_required_패널수",\n'
        '    "promotion_decision_promote_candidate_패널수",\n'
        '    "promotion_decision_manual_review_패널수",\n'
        '    "promotion_decision_blocked_cluster_risk_패널수",\n'
        '    "promotion_decision_hold_shadow_only_패널수",\n'
        '    "promotion_decision_backdate_suppression_candidate_패널수",\n'
        '    "promotion_decision_audit_provenance_only_패널수",\n'
        '    "g1_suppressed_event_shadow_candidate_패널수",\n'
        '    "g1_suppressed_event_shadow_precursor_to_sudden_패널수",\n'
        '    "g1_suppressed_event_guard_applied_패널수",\n'
        '    "g1_suppressed_event_guard_hold_review_패널수",\n'
        '    "subtype_shadow_populated_패널수",\n'
        '    "subtype_confidence_high_패널수",\n'
        '    "subtype_confidence_medium_패널수",\n'
        '    "subtype_confidence_low_패널수",\n'
        '    "subtype_confidence_hold_패널수",\n'
        '    "subtype_shape_confidence_high_패널수",\n'
        '    "subtype_shape_confidence_medium_패널수",\n'
        '    "subtype_shape_confidence_low_패널수",\n'
        '    "subtype_shape_confidence_hold_패널수",\n'
        '    "subtype_promotion_blocker_common_cause_패널수",\n'
        '    "subtype_promotion_blocker_insufficient_recurrence_패널수",\n'
        '    "subtype_promotion_blocker_backdating_risk_패널수",\n'
        '    "subtype_promotion_blocker_measurement_quality_패널수",\n'
        '    "subtype_promotion_blocker_insufficient_evidence_패널수",\n'
        '    "subtype_promotion_blocker_none_패널수",\n'
        '    "subtype_promotion_blocker_detail_site_event_패널수",\n'
        '    "subtype_promotion_blocker_detail_strict_trigger_proximal_패널수",\n'
        '    "subtype_promotion_blocker_detail_subgroup_common_cause_패널수",\n'
        '    "subtype_promotion_blocker_detail_group_off_패널수",\n'
        '    "subtype_promotion_blocker_detail_common_cause_history_패널수",\n'
        '    "subtype_promotion_blocker_detail_backdating_risk_패널수",\n'
        '    "subtype_promotion_blocker_detail_none_패널수",\n'
        '    "subtype_production_write_allowed_sum",\n'
        '    "note_ko",\n'
        ']\n'
        '\n'
        '\n'
        'def parse_args() -> argparse.Namespace:\n'
        '    parser = argparse.ArgumentParser(\n'
        '        description=(\n'
        '            "Build a raw-only runtime fault-event audit from panel_day_core and "\n'
        '            "ae_simple_local_precursor_gate_daily without frozen truth/support assets."\n'
        '        )\n'
        '    )\n'
        '    parser.add_argument(\n'
        '        "--root",\n'
        '        type=Path,\n'
        '        default=REPO_ROOT,\n'
        '        help="Workspace root containing data/<site>/out.",\n'
        '    )\n'
        '    return parser.parse_args()\n'
        '\n'
        '\n'
        'def subtype_shadow_row(metrics: common.PanelRuntimeMetrics) -> dict[str, object]:\n'
        '    event_type = common.normalize_text(metrics.사건유형_재판정_ko)\n'
        '    fault_status = common.normalize_text(metrics.패널고장여부_ko)\n'
        '    algorithm_family = common.normalize_text(metrics.algorithm_family_ko)\n'
        '    representative_source = common.normalize_text(metrics.대표critical_source)\n'
        '    representative_subtype = common.normalize_text(metrics.대표anom_subtype)\n'
        '    detailed_code = common.normalize_text(metrics.detailed_fault_code)\n'
        '\n'
        '    def pack(\n'
        '        family: str,\n'
        '        subtype: str,\n'
        '        confidence: str,\n'
        '        hold_reason: str,\n'
        '        tags: list[str],\n'
        '        shape_confidence: str | None = None,\n'
        '        promotion_blocker: str = "none",\n'
        '        promotion_blocker_detail: str = "",\n'
        '        promotion_blocker_reason: str = "",\n'
        '    ) -> dict[str, object]:\n'
        '        compact_tags = list(dict.fromkeys(tag for tag in tags if tag))\n'
        '        family_text = common.normalize_text(family)\n'
        '        subtype_text = common.normalize_text(subtype)\n'
        '        blocker = common.normalize_text(promotion_blocker)\n'
        '        if not family_text and not subtype_text:\n'
        '            blocker = ""\n'
        '        elif not blocker:\n'
        '            blocker = "none"\n'
        '        blocker_detail = common.normalize_text(promotion_blocker_detail)\n'
        '        if blocker == "common_cause" and not blocker_detail:\n'
        '            blocker_detail = "common_cause_history"\n'
        '        elif blocker and not blocker_detail:\n'
        '            blocker_detail = blocker\n'
        '        shape_confidence_text = common.normalize_text(shape_confidence)\n'
        '        if not shape_confidence_text:\n'
        '            shape_confidence_text = common.normalize_text(confidence)\n'
        '        blocker_reason = promotion_blocker_reason\n'
        '        if blocker == "none" and not blocker_reason and (family_text or subtype_text):\n'
        '            blocker_reason = (\n'
        '                "no subtype-specific promotion blocker classified; production write remains "\n'
        '                "disabled by shadow-only branch policy"\n'
        '            )\n'
        '        return {\n'
        '            "fault_family_hypothesis_shadow_ko": family,\n'
        '            "fault_subtype_hypothesis_shadow_ko": subtype,\n'
        '            "subtype_evidence_tags": ",".join(compact_tags),\n'
        '            "subtype_confidence_shadow": confidence,\n'
        '            "subtype_shape_confidence_shadow": shape_confidence_text,\n'
        '            "subtype_promotion_blocker_shadow": blocker,\n'
        '            "subtype_promotion_blocker_detail_shadow": blocker_detail,\n'
        '            "subtype_promotion_blocker_reason_ko": blocker_reason,\n'
        '            "subtype_hold_reason_ko": hold_reason,\n'
        '            "subtype_production_write_allowed": 0,\n'
        '        }\n'
        '\n'
        '    def empty(reason: str = "") -> dict[str, object]:\n'
        '        return pack("", "", "", reason, [], shape_confidence="", promotion_blocker="", promotion_blocker_detail="")\n'
        '\n'
        '    if fault_status != "고장" and not event_type:\n'
        '        return empty("no runtime fault event; subtype hypothesis not assigned")\n'
        '\n'
        '    base_tags = [\n'
        '        f"event_type={event_type}" if event_type else "",\n'
        '        f"algorithm_family={algorithm_family}" if algorithm_family else "",\n'
        '        f"critical_source={representative_source}" if representative_source else "",\n'
        '        f"anom_subtype={representative_subtype}" if representative_subtype else "",\n'
        '        f"gap_days={metrics.gap_days}" if metrics.gap_days else "",\n'
        '        f"onset_method={metrics.onset_method}" if metrics.onset_method else "",\n'
        '    ]\n'
        '    common_cause_tags: list[str] = []\n'
        '    common_cause_blocker = ""\n'
        '    common_cause_blocker_detail = ""\n'
        '    common_cause_hold_reason = ""\n'
        '    if metrics.has_site_event or metrics.has_strict_trigger_proximal_common_cause:\n'
        '        common_cause_tags.append("site_or_strict_proximal_common_cause")\n'
        '        common_cause_blocker = "common_cause"\n'
        '        if metrics.has_site_event:\n'
        '            common_cause_blocker_detail = "site_event"\n'
        '        else:\n'
        '            common_cause_blocker_detail = "strict_trigger_proximal"\n'
        '        common_cause_hold_reason = (\n'
        '            "candidate subtype is held because site/strict-proximal common-cause evidence "\n'
        '            "blocks individual panel precursor promotion"\n'
        '        )\n'
        '    elif metrics.has_subgroup_common_cause or metrics.has_group_off:\n'
        '        common_cause_tags.append("root_or_group_common_cause")\n'
        '        common_cause_blocker = "common_cause"\n'
        '        if metrics.has_subgroup_common_cause:\n'
        '            common_cause_blocker_detail = "subgroup_common_cause"\n'
        '        else:\n'
        '            common_cause_blocker_detail = "group_off"\n'
        '        common_cause_hold_reason = (\n'
        '            "candidate subtype is held because root/group common-cause evidence must be "\n'
        '            "separated before individual panel promotion"\n'
        '        )\n'
        '    elif metrics.has_common_cause_history:\n'
        '        common_cause_tags.append("common_cause_history")\n'
        '        common_cause_blocker = "common_cause"\n'
        '        common_cause_blocker_detail = "common_cause_history"\n'
        '        common_cause_hold_reason = (\n'
        '            "candidate subtype is held because broad common-cause history is episode evidence"\n'
        '        )\n'
        '\n'
        '    if metrics.g1_suppressed_event_shadow_flag:\n'
        '        tags = base_tags + [\n'
        '            "family=degradation_soiling_shadow",\n'
        '            "g1_shadow",\n'
        '            "long_gap",\n'
        '            "one_day_degradation",\n'
        '            "strict_common_cause=1" if metrics.has_strict_trigger_proximal_common_cause else "",\n'
        '        ]\n'
        '        return pack(\n'
        '            "열화·오염·음영 계열",\n'
        '            "장기 gap 단일 저하 보류형",\n'
        '            "hold",\n'
        '            "BR-018 subtype hypothesis: one-day long-gap degradation is backdating-risk evidence, not a confirmed precursor",\n'
        '            tags,\n'
        '            shape_confidence="low",\n'
        '            promotion_blocker="backdating_risk",\n'
        '            promotion_blocker_detail="backdating_risk",\n'
        '            promotion_blocker_reason=(\n'
        '                "one-day degradation marker is too far from the strict trigger to promote as "\n'
        '                "a confirmed precursor"\n'
        '            ),\n'
        '        )\n'
        '\n'
        '    source_text = f"{representative_source} {representative_subtype} {detailed_code}".lower()\n'
        '    if any(token in source_text for token in ["sensor", "feedback", "dropout", "freeze", "scale", "timestamp"]):\n'
        '        tags = base_tags + ["family=measurement_feedback", "measurement_signature"]\n'
        '        if any(token in source_text for token in ["dropout", "freeze"]):\n'
        '            subtype = "센서 dropout·freeze형"\n'
        '        elif "timestamp" in source_text:\n'
        '            subtype = "timestamp·채널 매칭 이상형"\n'
        '        else:\n'
        '            subtype = "센서 scale drift형"\n'
        '        return pack(\n'
        '            "센서·피드백·계측 이상 계열",\n'
        '            subtype,\n'
        '            "hold",\n'
        '            "measurement-feedback subtype is data-quality evidence and is not promoted as panel fault",\n'
        '            tags,\n'
        '            shape_confidence="low",\n'
        '            promotion_blocker="measurement_quality",\n'
        '            promotion_blocker_detail="measurement_quality",\n'
        '            promotion_blocker_reason=(\n'
        '                "measurement-feedback signatures must be separated from physical panel faults"\n'
        '            ),\n'
        '        )\n'
        '\n'
        '    if algorithm_family == "다이오드형" or metrics.has_vdrop:\n'
        '        tags = base_tags + common_cause_tags + ["family=diode_substring", "vi_ratio_shape"]\n'
        '        if "substring" in representative_subtype.lower() or "sub" in representative_subtype.lower():\n'
        '            subtype = "서브스트링 전류 제한형"\n'
        '        else:\n'
        '            subtype = "bypass diode 동작·고장 의심형"\n'
        '        shape_confidence = "medium" if fault_status == "고장" else "low"\n'
        '        confidence = "hold" if common_cause_hold_reason else shape_confidence\n'
        '        return pack(\n'
        '            "다이오드·서브스트링 계열",\n'
        '            subtype,\n'
        '            confidence,\n'
        '            common_cause_hold_reason\n'
        '            or "shadow-only subtype; requires VI curve review before operator-facing label use",\n'
        '            tags,\n'
        '            shape_confidence=shape_confidence,\n'
        '            promotion_blocker=common_cause_blocker or "none",\n'
        '            promotion_blocker_detail=common_cause_blocker_detail or "none",\n'
        '            promotion_blocker_reason=common_cause_hold_reason,\n'
        '        )\n'
        '\n'
        '    if algorithm_family == "모듈손상형" or (\n'
        '        algorithm_family not in {"개방/장치이상형", "다이오드형"}\n'
        '        and (metrics.has_degradation or metrics.has_shadow)\n'
        '    ):\n'
        '        tags = base_tags + common_cause_tags + ["family=degradation_soiling_shadow"]\n'
        '        if metrics.has_shadow and not metrics.has_degradation:\n'
        '            subtype = "국소 음영 패턴형"\n'
        '            tags.append("shadow_pattern")\n'
        '            confidence = "low"\n'
        '            shape_confidence = "low"\n'
        '            promotion_blocker = "insufficient_recurrence"\n'
        '            promotion_blocker_detail = "insufficient_recurrence"\n'
        '            promotion_blocker_reason = "shading-like hypothesis requires repeated time-of-day shape evidence"\n'
        '            hold_reason = "shading-like hypothesis requires repeated time-of-day shape evidence"\n'
        '        elif event_type == "전조형 고장" and metrics.gap_days >= 7:\n'
        '            subtype = "누적 오염·열화형"\n'
        '            tags.extend(["duration_or_gap_support", "precursor_event"])\n'
        '            confidence = "medium"\n'
        '            shape_confidence = "medium"\n'
        '            promotion_blocker = "none"\n'
        '            promotion_blocker_detail = "none"\n'
        '            promotion_blocker_reason = ""\n'
        '            hold_reason = "shadow-only subtype; keep production label unchanged until recurrence/continuity is reviewed"\n'
        '        else:\n'
        '            subtype = "일시 환경 episode형"\n'
        '            tags.append("transient_or_sparse_degradation")\n'
        '            confidence = "hold"\n'
        '            shape_confidence = "low"\n'
        '            promotion_blocker = "insufficient_recurrence"\n'
        '            promotion_blocker_detail = "insufficient_recurrence"\n'
        '            promotion_blocker_reason = "sparse degradation/shadow evidence lacks recurrence or continuity support"\n'
        '            hold_reason = "sparse degradation/shadow evidence is held as an episode, not confirmed precursor"\n'
        '        if common_cause_hold_reason:\n'
        '            confidence = "hold"\n'
        '            hold_reason = common_cause_hold_reason\n'
        '            promotion_blocker = common_cause_blocker\n'
        '            promotion_blocker_detail = common_cause_blocker_detail\n'
        '            promotion_blocker_reason = common_cause_hold_reason\n'
        '        return pack(\n'
        '            "열화·오염·음영 계열",\n'
        '            subtype,\n'
        '            confidence,\n'
        '            hold_reason,\n'
        '            tags,\n'
        '            shape_confidence=shape_confidence,\n'
        '            promotion_blocker=promotion_blocker,\n'
        '            promotion_blocker_detail=promotion_blocker_detail,\n'
        '            promotion_blocker_reason=promotion_blocker_reason,\n'
        '        )\n'
        '\n'
        '    if algorithm_family == "개방/장치이상형":\n'
        '        tags = base_tags + common_cause_tags + ["family=open_connection_partial"]\n'
        '        if metrics.secondary_window_candidate_flag or metrics.secondary_window_qualified_count >= 2:\n'
        '            subtype = "간헐 접촉저항형"\n'
        '            tags.append("recurrence_or_secondary_window")\n'
        '            confidence = "low"\n'
        '            shape_confidence = "medium"\n'
        '            promotion_blocker = "none"\n'
        '            promotion_blocker_detail = "none"\n'
        '            promotion_blocker_reason = ""\n'
        '        elif metrics.has_final_fault or metrics.has_fault_like:\n'
        '            subtype = "부분 개방 진행형"\n'
        '            tags.append("strict_or_final_fault_anchor")\n'
        '            confidence = "medium"\n'
        '            shape_confidence = "medium"\n'
        '            promotion_blocker = "none"\n'
        '            promotion_blocker_detail = "none"\n'
        '            promotion_blocker_reason = ""\n'
        '        else:\n'
        '            subtype = "커넥터·단자·퓨즈 계열 의심형"\n'
        '            tags.append("open_connection_proxy")\n'
        '            confidence = "low"\n'
        '            shape_confidence = "low"\n'
        '            promotion_blocker = "insufficient_recurrence"\n'
        '            promotion_blocker_detail = "insufficient_recurrence"\n'
        '            promotion_blocker_reason = "open-connection proxy lacks recurrence or shape-similarity support"\n'
        '        if common_cause_hold_reason:\n'
        '            confidence = "hold"\n'
