        '\n'
        'def parse_args() -> argparse.Namespace:\n'
        '    parser = argparse.ArgumentParser(\n'
        '        description="Build a raw-only runtime cause-candidate heuristic from runtime final verdict."\n'
        '    )\n'
        '    parser.add_argument(\n'
        '        "--root",\n'
